window.POEM_DB=window.POEM_DB||{};POEM_DB["song_000"]={"n":"无名氏","dyn":"宋","poems":[{"t":"撷芳词","f":"词","c":["风摇荡，雨濛茸，翠条柔弱花头重。","春衫窄，香肌湿，记得年时，共伊曾摘。","都如梦，何曾共，可怜孤似钗头凤。","关山隔，晚云碧，燕儿来也，又无消息。"]},{"t":"九疑山","f":"七言绝句","c":["溪山相似路人疑，众目详观固易知。","厚貌深情怀险阻，离朱子羽谩扬眉。"]},{"t":"二疏","f":"七言绝句","c":["贤者多财应损智，愚而殖货易生嗔。","二疏教子无他祝，愿向先畴加苦辛。"]},{"t":"三鸦镇题壁","f":"七言绝句","c":["二年憔悴在三鸦，无米无钱怎养家。","每日两餐唯是藕，看看口里出莲花。"]},{"t":"义试诗 孔明草庐图","f":"七言绝句","c":["南阳高卧屈将军，往事流传水墨昏。","莫讶轴闲茅屋小，个中藏得汉乾坤。"]},{"t":"义试诗 葡萄月","f":"七言绝句","c":["春藤上架翠成窝，颗颗圆光得月多。","疑是蕊珠开夕宴，结成珠帐待常娥。"]},{"t":"小桃源","f":"五言绝句","c":["绰约去朝真，仙源万木春。","要知窃桃客，定是会稽人。"]},{"t":"月儿弯弯照九州","f":"七言绝句","c":["月儿弯弯照九州，几家欢乐几家愁。","几家夫妇同罗帐，几家飘零在外头。"]},{"t":"讥贾平章","f":"七言绝句","c":["戎马掀天动地来，襄阳城下哭声哀。","平章束手全无策，却把科场恼秀才。"]},{"t":"仙迹岩题诗二十三首 其一 三清殿","f":"七言绝句","c":["虚无混沌未分前，大道元居太极先。","自一而三同祖气，澄清高上积阳天。"]},{"t":"仙迹岩题诗二十三首 其二十三 飞玉亭","f":"七言绝句","c":["闲亭清憩觉情优，四顾岚光景色幽。","湍玉飞帘侵座冷，璇源本自接天流。"]},{"t":"仙迹岩题诗二十三首 其十五 云根石","f":"七言绝句","c":["一片轮囷迹严存，无心出岫瑞腾坤。","不随风雨轻舒卷，触石凝然正性根。"]},{"t":"仙迹岩题诗二十三首 其十六 天柱泉","f":"七言绝句","c":["大涤之西一穷生，源高樵者只闻声。","汲泉烹茗多甘味，内隐丹砂赤更清。"]},{"t":"仙迹岩题诗二十三首 其五 方丈后聚仙亭","f":"七言绝句","c":["高敞山斋立乳巅，飘飖云驭聚群仙。","百灵听讲开坛夜，大法将临报语宣。"]},{"t":"仙迹岩题诗二十三首 其十九 龙井","f":"七言绝句","c":["鲮鳗环绕井楯间，两目神光状类丹。","杖扑投渊阴雾锁，殿堂汹涌尽波澜。"]},{"t":"仙迹岩题诗二十三首 其二 佑圣殿","f":"七言绝句","c":["挺锋镇北阐威权，剪伐魔精正法宣。","化育黎民臻大道，安宁家国享长年。"]},{"t":"仙迹岩题诗二十三首 其十七 冷泉","f":"七言绝句","c":["琳宫门外小桥东，石罅泉流细脉通。","清似玉壶承沆瀣，游人掬饮凛生风。"]},{"t":"仙迹岩题诗二十三首 其十二 张真君祠","f":"七言绝句","c":["圣像迁祠出禁扃，天恩遣使从神灵。","奉安钦敬祈民福，应感昭彰佑帝庭。"]},{"t":"仙迹岩题诗二十三首 其八 昊天殿","f":"七言绝句","c":["游幸名山德寿存，鼎新大殿显仁恩。","玉圭物物皆珍异，安奉严恭玉帝尊。"]},{"t":"仙迹岩题诗二十三首 其十四 经阁","f":"七言绝句","c":["宝阁庄严金玄耀，风铃震响玉丁东。","甍飞杰出青霄上，道典珍藏在此中。"]},{"t":"仙迹岩题诗二十三首 其二十一 采芝朮即事","f":"七言绝句","c":["仙芝灵朮总芳妍，野草闲花各变迁。","古栎复荣松化石，药苗蕃植可延年。"]},{"t":"仙迹岩题诗二十三首 其十一 钟楼","f":"七言绝句","c":["重楼高耸丹霄外，深夜声摩碧落中。","神通无量鸿音远，永镇名山有显功。"]},{"t":"仙迹岩题诗二十三首 其三 斋堂","f":"七言绝句","c":["辨道焚修练性根，应时粥饭益真元。","斋馀有报君恩重，寿祝无疆帝道尊。"]},{"t":"仙迹岩题诗二十三首 其二十二 祥光亭","f":"七言绝句","c":["覆石为亭武肃成，有仙来此变棋枰。","炷香五色祥光现，缥缈灵官朝玉京。"]},{"t":"仙迹岩题诗二十三首 其六 道院","f":"七言绝句","c":["幽栖枹朴古先精，宴坐参同元化并。","一炷清香腾瑞霭，云端时透步虚声。"]},{"t":"仙迹岩题诗二十三首 其四 演教堂","f":"七言绝句","c":["参稽道德本无言，不二门开阐古先。","多谢师尊传演教，要令后学悟真诠。"]},{"t":"仙迹岩题诗二十三首 其七 精思道院","f":"七言绝句","c":["精思名扁列金题，冲素斋居与道齐。","德感天仙来听论，芝軿时降共参稽。"]},{"t":"仙迹岩题诗二十三首 其十 翠蛟亭","f":"七言绝句","c":["湍激清泉舞翠蛟，幽亭跨涧对岩坳。","我来憩此观嘉趣，一洗尘襟凡世抛。"]},{"t":"仙迹岩题诗二十三首 其九 璇玑殿","f":"七言绝句","c":["众圣环拱位中天，统济乾坤妙转旋。","高覆昆崙朝帝阙，注生回死福增延。"]},{"t":"归州竹枝词","f":"七言绝句","c":["人鲊瓮头波放颠，两岸青山青插天。","篙师力尽客破胆，茅屋老翁方醉眠。"]},{"t":"白鹤观题壁","f":"七言绝句","c":["仙人未必皆仙去，还在人间人不知。","手把白髦从两鹿，相逢聊问姓名谁。"]},{"t":"兴化沙溪驿题壁","f":"七言绝句","c":["沙溪祇是旧沙溪，今日重来路欲迷。","独有暮鸦知我意，白云深处尽情啼。"]},{"t":"回文 其二","f":"七言绝句","c":["红手素丝千字锦，故人新曲九回肠。","风吹絮雪愁萦骨，泪洒缣书恨见郎。"]},{"t":"何侯洞","f":"七言绝句","c":["何氏因韩姓始传，无由与舜共升天。","洞前九井皆湮没，唯有荆榛绕庙壖。"]},{"t":"别题","f":"七言绝句","c":["休说三江与五湖，平生心眼此中舒。","人人总道浑如画，祇恐丹青画不如。"]},{"t":"咏古树","f":"七言绝句","c":["四围乔木尽儿孙，曾见吴宫几度春。","若使当年成大厦，也应随例作灰尘。"]},{"t":"斩蛇","f":"五言绝句","c":["皇统承尧运，朱旗启汉家。","未诛秦始鹿，先斩沛中蛇。"]},{"t":"油污衣","f":"七言绝句","c":["一点清油污白衣，斑斑駮駮使人疑。","纵饶洗遍千江水，争似当初不污时。"]},{"t":"金鳌山善际寺题壁","f":"七言绝句","c":["黄帽当年驾舳舻，东浮鲸海出三吴。","中兴事业风波恶，好作君王坐右图。"]},{"t":"钓台题壁","f":"七言绝句","c":["生涯千顷水云宽，舒卷乾坤一钓竿。","梦里偶然伸只脚，渠知天子是何官。"]},{"t":"孩儿花","f":"七言绝句","c":["纤秾初见似娇痴，鼓舞春风二月时。","何事自开还自落，可怜造化亦儿嬉。"]},{"t":"宣圣墓","f":"七言绝句","c":["灵光殿古生秋草，曲阜城荒噪晚鸦。","惟有孔林残照里，至今犹属仲尼家。"]},{"t":"春暮","f":"七言绝句","c":["此春眼不到湖山，过了春光只等闲。","愿有东君相管领，时收花絮入帘看。"]},{"t":"春暮","f":"七言绝句","c":["三月湖天春昼长，东风飘暖草浮光。","樱桃熟后游人倦，柳絮飞时燕子忙。"]},{"t":"春暮","f":"七言绝句","c":["麦髯豆荚雨生肥，闲绿园林粉蝶飞。","剩置好花安四壁，不教人道是春归。"]},{"t":"闺怨","f":"七言绝句","c":["有约未归蚕结局，小轩空度牡丹春。","夜来拣尽鸳鸯茧，留织春衫寄远人。"]},{"t":"项羽庙灾","f":"七言绝句","c":["嬴秦久矣酷斯民，羽入关中又火秦。","父老莫嗟遗庙毁，咸阳三月是何人。"]},{"t":"栖云阁","f":"七言绝句","c":["倚天危阁贴重冈，细路萦纡石磴长。","曲涧碧流疏宿雨，夹山红叶助斜阳。"]},{"t":"逍遥观","f":"七言绝句","c":["昔设黄婆旧酒垆，如何今日似蓬壶。","只因王郭仙人过，化作青城上帝都。"]},{"t":"寄家书","f":"七言绝句","c":["南轩北牖又东扉，取次园林待我归。","当路莫栽荆棘草，他年免挂子孙衣。"]},{"t":"望仙花","f":"七言绝句","c":["风捲珠帘挂玉钩，綵云开处望仙俦。","妍姿不逐东君去，日照斜晖上小楼。"]},{"t":"象耳山","f":"七言绝句","c":["篮舆来自石苍路，喜得幽人陪杖屦。","应是山灵泽旱苗，不关居士随轩雨。"]},{"t":"寒亭","f":"七言绝句","c":["朔风凛凛雪漫漫，未是寒亭分外寒。","六月火云天不雨，请君来此凭阑干。"]},{"t":"禽言二首 其二 著新脱故","f":"七言绝句","c":["蚕茧方成四月初，鸟能早计巧相呼。","谁知机杼声才息，已有王官来索租。"]},{"t":"禽言二首 其一 子规","f":"七言绝句","c":["刚道故乡如许好，其如游子不归何。","自从五柳先生死，空染千山泪血多。"]},{"t":"舒州下寨驿题壁","f":"七言绝句","c":["北堂无老信来稀，十载秋风雁自飞。","今日满头生白发，千山乡路为谁归。"]},{"t":"翠微峰","f":"七言绝句","c":["洞里乾坤世莫知，时闻啸鹤带云归。","几回洞口乘风立，欲挟飞仙入翠微。"]},{"t":"嘲张师雄","f":"七言绝句","c":["昨夜阴山贼吼风，帐中惊起蜜翁翁。","平明不待全师出，连著皮裘入土空。"]},{"t":"嘲林洪","f":"七言绝句","c":["和靖当年不娶妻，只留一鹤一童儿。","可山认作孤山种，正是瓜皮搭李皮。"]},{"t":"题太行山石壁","f":"七言绝句","c":["太行千里连芳草，独酌一杯天地小。","醉卧花间人不知，黄莺啼破春山晓。"]},{"t":"题刘武僖题名后","f":"七言绝句","c":["一入侯门海样深，漫留名字恼行人。","夜来彷佛高唐梦，犹恐行云意未真。"]},{"t":"题严陵钓台","f":"七言绝句","c":["范蠡忘名载西子，介推逃迹累山樊。","先生政尔无多事，聊把渔竿坐水村。"]},{"t":"题岳阳飞吟亭","f":"七言绝句","c":["觅官千里赴神京，钟老相传盖更倾。","未必无心唐事业，金丹一粒误先生。"]},{"t":"题采石蛾眉山","f":"七言绝句","c":["一岛烽烟斡怒流，燃犀捉月两悠悠。","蛾眉中划三千丈，不著人间半点愁。"]},{"t":"题峻极中院法堂壁","f":"词","c":["一团茅草乱蓬蓬，蓦地烧天蓦地空。","争似满炉煨榾?，慢腾腾地热烘烘。"]},{"t":"题鸳鸯浦溆图","f":"七言绝句","c":["睡足鸳鸯各欲飞，水花攲岸两三枝。","多情公子因乘兴，写出江春日暖时。"]},{"t":"题寝宫诗","f":"七言绝句","c":["农桑不扰岁常登，边将无功吏不能。","四十二年如梦过，东风吹泪洒昭陵。"]},{"t":"题景星壁","f":"七言绝句","c":["陌上春风破酒颜，马头珠络响珊珊。","归来院落已深夜，满地月明花影寒。"]},{"t":"题蜕龙洞 伏虎岩","f":"七言绝句","c":["空岩深峻可栖真，猛虎温驯异类亲。","正节天师时憩此，逍遥忘返咏章新。"]},{"t":"题蜕龙洞 鸣凤洞","f":"七言绝句","c":["鸣凤来仪瑞翠巅，洞中阻隘石门全。","傍通小径无穷极，溜响玎珰有穴泉。"]},{"t":"题壁","f":"七言绝句","c":["白塔桥边卖地经，长亭短驿甚分明。","如何祇说临安路，不较中原有几程。"]},{"t":"毛竹山","f":"五言律诗","c":["蜀道称天险，南州号地灵。","山腰生雨露，屋角走雷霆。","挥扇云生岫，开窗月傍棂。","明朝一回首，毛竹插天青。"]},{"t":"仙迹岩题诗二十三首 其二十 无骨箬","f":"七言律诗","c":["许氏功成获上升，曾遗一剂语丁宁。","山生绀箬奇无骨，洞隐金丹显有灵。","松竹攲岩非易取，烟霞塞道卒难经。","有缘仙者当须遇，用倖搜求岂露形。"]},{"t":"代意","f":"七言律诗","c":["懊恼鸳鸯未白头，却寻遗翠失芳洲。","离魂暗逐明珠佩，远目偏伤紫桂楼。","湘水渺瀰归别渚，陇云容与澹新秋。","菖花若有重开日，得见菖花亦自羞。"]},{"t":"合江亭","f":"七言律诗","c":["□□□来□此州，□□偶到合江游。","□□雨过□□□，□□□□□□油。","韩愈诗奇封碧藓，朱陵洞古枕寒流。","肩舆归去日将暮，啼鸟一声山更幽。"]},{"t":"庆元府额上牌致语口号","f":"七言律诗","c":["庆元天子旧名藩，宝祐元戎新榜颜。","郁郁蛟缠三大字，停停虹贯四明山。","百年老稚欢声沸，千古山河旺气还。","便挟岛仙天上去，再提此笔福人间。"]},{"t":"此游淡岩同成一诗敢用拜呈","f":"七言律诗","c":["行尽潇湘山复山，掣舟来叩淡岩关。","幽深虽与尘寰隔，空阔犹容俗驾攀。","是处名山有岩窦，莫如此地最宽闲。","真人仙去知何在，陈迹空留警世顽。"]},{"t":"和别驾萧世范赠玉岩诗四首 其四","f":"七言律诗","c":["富贵须论命有无，谋身只是半行书。","饥肠不羡千钟粟，广厦何如一亩居。","世路茫茫终偃蹇，生涯处处是赢馀。","萧条此道谁为助，掩卷时过长者居。"]},{"t":"和别驾萧世范赠玉岩诗四首 其三","f":"七言律诗","c":["堪笑先生四壁无，寒窗剩有五车书。","一童只许长须伴，半世长同只影居。","白屋不嫌藜藿少，朱门却厌稻粱馀。","枕流漱石多佳趣，不羡人閒驷马车。"]},{"t":"和别驾萧世范赠玉岩诗四首 其二","f":"七言律诗","c":["折腰五斗信非天，荐祢徒劳一鹗书。","渊底纵鳞誇水泳，林间宿鸟乐巢居。","心随俯仰缘无慊，身任行藏自有馀。","试问通衢何处是，圣门无限指南车。"]},{"t":"和别驾萧世范赠玉岩诗四首 其一","f":"七言律诗","c":["莫守陈编学蠹鱼，筌蹄真似古人书。","利名沧海浮沤聚，身世乾坤逆旅居。","懒向明庭陈一得，还留故馆积三馀。","尘埃满足崎岖地，羡子抟风上日车。"]},{"t":"和郭使君韵","f":"七言律诗","c":["郭侯凛凛气横秋，管领江山作胜游。","痛饮不知乌景坠，清歌更觉鸟声幽。","诵君崖畔神仙句，淡我胸中浩荡愁。","万里相逢更相失，他年卜筑共归休。"]},{"t":"奉谢徐献子","f":"七言律诗","c":["入得青山第几重，龙蟠凤舞着仙宗。","九关云锁疑无地，数步天开又一峰。","大涤洞中丹作井，昊穹殿下石为松。","我来自结真人伴，杖屦蹁跹是指踪。"]},{"t":"郎官湖亭","f":"七言律诗","c":["郎官遗爱凿成湖，李白题诗在昔初。","春水浪翻惊野鹭，夏荷盘侧戏游鱼。","冬风结冻凝青汉，秋月分光落碧虚。","我爱四时风景好，买山来此创幽居。"]},{"t":"涵碧堂","f":"五言律诗","c":["方塘纳霁景，一碧共晴寒。","龟鱼桥不隔，霞鹜镇相看。","其谁领胜解，结束小阑干。","微波坐来息，人意亦平宽。"]},{"t":"游象耳山","f":"五言律诗","c":["水似青萝带，山如碧玉环。","池蛙鸣聒聒，林鸟语关关。","松桧磐高盖，藤萝引翠鬟。","倚栏无一语，何以慰幽閒。"]},{"t":"碧虚洞","f":"七言古诗","c":["灌溉工兴古洞荒，洞门□蔽碧池傍。","□□□□□□□，□□波□□□霜。","□□□□□□□，□窗□月□寒光。","□□□□□□□，□□□□代是□。"]},{"t":"嘲林叔茂私挈楚娘","f":"七言律诗","c":["三山城内有神仙，一个夫人一个偏。","开口笑时真似品，直身眠处恰如川。","并头难叙胸中事，攲枕须防背后拳。","王恺石崇池里藕，分明两个大家莲。"]},{"t":"题阳羡溪亭壁","f":"七言律诗","c":["碧云亭上碧云飞，竟日回环面翠微。","梅萼破香知腊尽，柳梢含绿认春归。","风前古涧琴三叠，雪后群峰玉一围。","遥想上人清太甚，水精宫里说禅机。"]},{"t":"题芜湖梦日亭","f":"七言律诗","c":["楼船犀甲下荆州，蜂目将军驻碧油。","虎帐觉来惊日堕，龙媒嘶去逐星流。","奸萌问鼎终何在，计落遗鞭始可羞。","幽草乱花荒故垒，无人能作晋春秋。"]},{"t":"题宜兴迎华驿","f":"七言律诗","c":["家问不来秋夜长，白鸥眠处倚牙樯。","风摇湖水动山影，天压陇云低雁行。","菊老过时犹嚼蕊，鱼逃无水尚鸣榔。","洗兵马诏何时下，免遣农夫坐女墙。"]},{"t":"题桃源 其一","f":"七言律诗","c":["忽入桃源景可猜，莫非道士亦曾栽。","舟行溯水沿溪进，花映清流夹岸开。","石涧有岐封碧草，洞门无俗长苍苔。","方知此景非人世，岩谷幽深少客来。"]},{"t":"题桃源 其二","f":"七言律诗","c":["舍舟入洞夕阳斜，得见方村八九家。","林锁山环藏屋宇，鸡鸣犬吠隐烟霞。","宁知门有今朝客，可使灯开昨夜花。","共喜相邀询动止，呼童汲水煮仙茶。"]},{"t":"题桃源 其四","f":"七言律诗","c":["忆前复入武陵溪，野水微茫烟树迷。","岩闭不闻仙犬吠，山深惟听鹧鸪啼。","神仙悬隔今非昔，乌兔循环东复西。","应向洞中存隐迹，芳名留与后人题。"]},{"t":"题桃源 其三","f":"七言律诗","c":["远近人家尽见招，小童环立总垂髫。","玄冰满椀侵肌爽，绛雪堆盘入口消。","山内不知今晋代，座中犹自问秦朝。","夜深时向花前立，遥见双株合凤箫。"]},{"t":"题旌忠亭","f":"七言律诗","c":["贼壮兵孤众胆惊，忠臣此日见专城。","负君罪大宁如死，守土诚坚不问生。","报国寸心无自愧，呼天浩气几时平。","潺湲多少英雄泪，千古封江不断声。"]},{"t":"题震泽寺壁","f":"五言律诗","c":["民力久已竭，天乎不见怜。","三年两遭水，十室九无烟。","田没官徵赋，家贫子卖钱。","秋风江上路，忽见渡江船。"]},{"t":"赠长安赵先生母","f":"五言律诗","c":["牙发重生黑，延龄三事因。","至诚遵道友，精谨奉高真。","静意摛猿马，清心聚气神。","处端聊拜上，稽首寿长人。"]},{"t":"十七字诗","f":"词","c":["驾幸景灵宫，诸生尽鞠躬。","头乌身上白，米虫。"]},{"t":"开元寺留题 其一","f":"七言绝句","c":["双松偃亚老龙起，唤得清风到别楼。","尚忆曩年诗酒伴，几回天际识归舟。"]},{"t":"无题","f":"七言绝句","c":["试将潜皖问云游，何似灵岩与虎丘。","应道淮南山水胜，清奇都在两三州。"]},{"t":"仙迹岩题诗二十三首 其十三 叶天师书楼","f":"七言绝句","c":["巍然垂象隐精思，著述丹书与世违。","真得紫文无上道，业成遗迹是题诗。"]},{"t":"它山堰","f":"五言古诗","c":["谁将倚天剑，斸出天河水。","倾泻落人间，合流奔至此。","六丁战海若，横筑万石垒。","波涛敛潮汐，辟易走千里。","蓄泄有堨埭，深长富源委。","支派缭村落，河渠贯城市。","千畦藉灌溉，万井酌清沚。","伟哉霖雨功，千载流不已。"]},{"t":"玉手炉花","f":"七言绝句","c":["习习东风二月馀，此花宜近玉庭除。","美人云鬓不宜插，献与观音作手炉。"]},{"t":"白石滩碑刻","f":"楚辞体","c":["太原王氏女，金陵韩守妻。","戊辰年八月，葬在石城西。","日为弓兮月为箭，射四时兮生改变。","千年万年松柏风，悲尽死亡人不见。"]},{"t":"伤双燕","f":"七言古诗","c":["燕燕于飞春欲暮，终日呢喃语如诉。","但闻寄泪来潇湘，不闻有意如烈妇。","夏氏狂儿好游猎，弹射飞禽类几绝。","梁间双燕衔泥至，飞镞伤雄当儿戏。","雌燕视之兀如痴，不能人言人不知。","门前陂水清且泚，一飞径溺澄澜底。","伤哉痛恨应未休，安得化作吕氏女，手刃其头报夫仇。"]},{"t":"戏题林灵素画像","f":"七言绝句","c":["当日先生在市廛，世人那识是真仙。","只因学得飞升后，鸡犬相随也上天。"]},{"t":"周公亭留题","f":"七言绝句","c":["人言周公来结宇，不知建立何年中。","撰词仍是谪御史，残缺欲读嗟难通。"]},{"t":"和孝狗歌","f":"七言古诗","c":["慈乌反哺古所称，不闻乳狗能效颦。","鹿坡王氏世吉人，乞得乳狗于良邻。","良邻家贫并日食，狗母长饥骨柴立。","乳狗食竟掉尾归，呕食喂母使母肥。","朝餐归呕暮复续，兽类之中颍考叔。","纷纷养志多缺如，惭愧四足之韩卢。"]},{"t":"咏蝶","f":"七言古诗","c":["□□□□□□□，一丛浮动戏兰芽。","裁成碧玉搔头样，画作黄金便面花。","闲过楼台飞尽日，又因风雨宿谁家。","儿童爱把襜褕扑，惊起双双贴綵霞。"]},{"t":"武溪歌","f":"五言古诗","c":["武溪深复深，飞鸟不能渡，兽游不能临。"]},{"t":"环翠堂","f":"五言律诗","c":["群山关设险，高屋昼多阴。","晴岚度丘壑，疏翠上衣襟。","琴声有成亏，画手随浅深。","不如陶谢辈，著句写登临。"]},{"t":"诗三首 其三","f":"七言绝句","c":["仙都道士不知名，能用丹书镇幽鬼。","杨郎独宿方醒然，孤鸾独宿重泉底。"]},{"t":"诗三首 其一","f":"七言绝句","c":["越娘墓下秋风起，脱叶纷纷逐流水。","只如明月葬高原，不奈霜威损桃李。"]},{"t":"梦鱼","f":"五言绝句","c":["玉烛和薰日，金穰瑞应初。","丰年知有象，吉梦兆维鱼。"]},{"t":"野翁堂","f":"五言古诗","c":["朝市若山林，意适无远近。","结庐在城郭，茅竹怀远韵。","汉吏贵无华，鲁礼从先进。"]},{"t":"虞帝陵","f":"七言律诗","c":["重华车驾瘗崔嵬，不似秦皇赐玺回。","西治骊山营兆域，东浮沧海访蓬莱。","陟方年已过期颐，老死勤民志不衰。","何事穆王心醉饱，耄荒无复念前规。"]},{"t":"靖州歌","f":"词","c":["小娘子，叶底花，无事出来吃盏茶。"]},{"t":"潭州四通馆题梁","f":"词","c":["蜗角名，蝇头利。","老天术何巧，以此役斯世。","昨日一替死，今日一替生。","暗里换人人不悟，门前每日见人行。"]},{"t":"题太和楼壁","f":"七言古诗","c":["太和酒楼三百间，大槽昼夜声潺潺。","千夫承糟万夫瓮，有酒如海糟如山。","铜锅镕尽龙山雪，金波涌出西湖月。","星宫琼浆天下无，九酝仙方谁漏泄。","皇都春色满钱塘，苏小当垆酒倍香。","席分珠履三千客，后列金钗十二行。","一座行觞歌一曲，楼东声断楼西续。","就中茜袖拥红牙，春葱不露人如玉。","今年和气光华夷，游人不醉终不归。","金貂玉尘宁论价，对月逢花能几时。","有个酒仙人不识，幅巾大袖豪无敌。","醉后题诗自不知，但见龙蛇满东壁。"]},{"t":"题司马悔桥","f":"五言古诗","c":["道书司马悔，福地在天台。","兹山秀盘古，亿载青崔嵬。","如何越中志，纪载殊未该。","浪云唐子微，曾过兹桥来。","奉诏悔轻出，欲勒俗驾回。","至今名字存，修梁架岩隈。","图谍已太戾，土俗尤疏哉。","以悔明兹桥，大字标板牌。","流传愈讹舛，云笈君试开。"]},{"t":"题石鱼","f":"词","c":["诸公讨未决。","朝忌其事夕失功，讵可因循守常法。","人心感处是天心，至诚解使金石裂。","形势不宜久冷落，鼓作须及人情热。","每忧奸雄东风尘，它日未易倾巢穴。","人才政事所急者，此间伊吕何常乏。","况如耿贾郭李辈，马后牛前谁识别。","黄芽摇寒鴥不飞，鬼洞蛮虚新过雪。","行矣强饭莫饮酒，偷闲读书备施设。","一官皆可行其义，勿学庸人苟岁月。","蹄涔之水无鲲鲸，鸳凤宁肯争鸡楬。","吾皇驻跸浙江西，努力朝宗致忠烈。","星驰电走见相。"]},{"t":"题驿壁","f":"五言律诗","c":["记得离家日，尊亲嘱咐言。","逢桥须下马，过渡莫争船。","雨宿宜防夜，鸡鸣更相天。","若能依此语，行路免迍邅。"]},{"t":"题贵池驿壁","f":"词","c":["昨日雨，今朝晴。","前月小，后月大。","君欲问百年，百年如此过。","孰为辱，孰为荣。","何者福，何者祸。","山中多白云，莫教脚一蹉。"]},{"t":"题蜕龙洞 其一 白茆洞","f":"七言律诗","c":["西南十里岭之巅，灵冢岿然洞隐仙。","门辟神扃低视井，柱生一窍仰瞻天。","瓮中春酒今朝酿，洞内仙宾昔日贤。","路阻山高难可到，茆君职守几千年。"]},{"t":"题壁","f":"五言绝句","c":["猛风拔大树，其树根已露。","上有寄生草，青青犹未寤。"]},{"t":"题壁","f":"五言古诗","c":["山行险而脩，老我骖且羸。","独驱六月暑，蹑此千仞梯。","世故不贷人，牵去复挽归。","茗盌参世味，甘苦常相持。","白云抱溪石，令人心愧之。","岂无趺座处，逸固不疗饥。","大叫天上人，凉风为吹衣。"]},{"t":"德兴邑廨石刻 其二","f":"词","c":["我田我地，我桑我梓。","只知百里，不知千里。","我饥有粮，我渴有水。","百里之官，得人生死。","孤儿寡妇，一张白纸。","入著县门，冤者有理。","上官不嗔，民即欢欣。","上官不富，民免辛苦。","生我父母，养我明府。","苗稼萋萋，曷东曷西。","父母之乡，天子马蹄。"]},{"t":"德兴邑廨石刻 其一","f":"词","c":["仕宦之身，天涯海畔。","行商之身，南州北县。","不如田舍，长拘见面。","门无官府，身即强健。","麻麦遍地，猪羊满圈。","不知金贵，唯闻粟贱。","夏新绢衣，秋新米饭。","安稳眠睡，直千直万。"]},{"t":"一丛花","f":"七言古诗","c":["晓来寒露滴疏桐。"]},{"t":"一剪梅","f":"词","c":["漠漠春阴酒半酣。","风透春衫，雨透春衫。","人家蚕事欲眠三，桑满筐篮，柘满筐篮。","先自离怀百不堪。","樯燕呢喃，梁燕呢喃。","篝灯强把锦书看，人在江南，心在江南。"]},{"t":"一剪梅","f":"词","c":["恨入椒觞暖未拈。","春葱微蘸，谁是纤纤。","别来愁夜不胜长，明日从教一线添。","夜久寒深睡未忺。","旧愁新恨，占断眉尖。","一钩斜月却知人。","直到天明，不下疏帘。"]},{"t":"一剪梅 贺生孙","f":"词","c":["太华峰头□□莲。","闻十丈，藕大如船。","晓来佳气蔼飞烟。","彩戏盈门。","弧矢盈门。","共把长生酒一樽。","殷勤祝愿，耳畔低言。","从今流庆更源源。","子既生孙。","孙又生孙。"]},{"t":"一斛珠","f":"词","c":["寒冰初泮。","岭头一朵香苞绽。","菡萏如画真堪羡。","休逞随风、柳絮垂金线。","月宫每嫖开较晓。","寿阳又喜匀妆面。","更闻何处鸣羌管。","一曲一声、惹起神撩乱。"]},{"t":"一萼红","f":"词","c":["断云漏日，青阳布，渐入融和天气。","糁缀夭桃，金绽垂杨，妆点亭台佳致。","晓露染、风裁雨晕，是牡丹、偏称化工美。","向此际会，未教一萼，红开鲜蕊。","迤逦。","渐成春意。","放秀色妖艳，天真难比。","粉惹蝶翅，香上蜂须，忍把芳心萦碎。","争似便，移归深院，将绿盖青帏护风日。","恁时节，占断与、偎红倚翠。"]},{"t":"一落索","f":"词","c":["腊后东风微透。","越梅时候。","一枝芳信到江南，来报先春秀。","宿醉频拈轻嗅。","堪醒残酒。","笛声容易莫相催，留待纤纤手。"]},{"t":"一落索","f":"七言古诗","c":["倚楼一霎酒旗风。"]},{"t":"菩萨蛮 甥寿舅公十月十一","f":"词","c":["新冬十叶蓂添一。","良辰喜是翁生日。","金鸭爇沉香。","祥烟绕画堂。","遐龄方五十。","厚福犹千百。","看取小甥孙。","年年捧寿樽。"]},{"t":"七娘子 寿梅守","f":"词","c":["暖律未回春时候。","向旧根、腊底红先透。","玉有冷香，粉无纤垢。","更饶雪里还清瘦。","琳宫拟诏风流守。","任折来、深醮金杯酒。","欲赏一枝，樽前为寿。","愿公归作调羹手。"]},{"t":"七娘子","f":"词","c":["清香浮动到黄昏，向水边、疏影梅开尽。","溪畔清蕊，有如浅杏。","一枝喜得东君信。","风吹只怕霜侵损。","更新来、插向多情鬓。","寿阳妆鉴，雪肌玉莹。","岭头别后微添粉。"]},{"t":"九张机","f":"词","c":["一张机。","织梭光景去如飞。","兰房夜永愁无寐。","呕呕轧轧，织成春恨，留著待郎归。","两张机。","月明人静漏声稀。","千丝万缕相萦系。","织成一段，回纹锦字。","将去寄呈伊。","三张机。","中心有朵耍花儿。","娇红嫩绿春明媚。","君须早折，一枝浓艳，莫待过芳菲。","四张机。","鸳鸯织就欲双飞。","可怜未老头先白，春波碧草，晓寒深处，相对浴红衣。","五张机。","芳心密与巧心期。","合欢树上枝连理。","双头花下，两同心处，一对化生儿。","六张机。","雕花铺锦半离披。","兰房别有留春计。","炉添小篆，日长一线，相对绣工迟。","七张机。","春蚕吐尽一生丝。","莫教容易裁罗绮。","无端剪破，仙鸾彩凤，分作两般衣。","八张机。","纤纤玉手住无时。","蜀江濯尽春波媚。","香遗囊麝，花房绣被。","归去意迟迟。","九张机。","一心长在百花枝。","百花共作红堆被。","都将春色，藏头里面，不怕睡多时。","轻丝。","象床玉手出新奇。","千花万草光凝碧。","裁缝衣著，春天歌舞，飞蝶语黄鹂。","春衣。","素丝染就已堪悲。","尘世昏污无颜色。","应同秋扇，从兹永弃。","无复奉君时。"]},{"t":"二色宫桃","f":"七言律诗","c":["镂玉香苞酥点萼。","正万木、园林萧索。","惟有一枝雪里开，江南信、更凭谁托。","前年记赏登高阁。","叹年来、旧欢如昨。","听取乐天一句云，花开处、且须行乐。"]},{"t":"人月圆","f":"词","c":["园林已有春消息，寻待岭头梅。","一枝清淡，疏疏带雪，昨夜初开。","芳心几点，东风多少，先为传来。","不随红紫，纷纷闹闹，蝶妒蜂猜。"]},{"t":"八声甘州 寿国太夫人","f":"词","c":["渐纷纷、木叶下亭皋，秋容际寒空。","庆屏山南畔、龟游绿藻，鹤舞青松。","缥缈非烟非雾，喜色有无中。","帘幕金风细，香篆濛濛。","好是庭闱称寿，簇舞裙歌板，欢意重重。","况芝兰满砌，行见黑头公。","看升平、乌栖画戟，更重开、大国荷荣封。","人难老，年年醉赏，满院芙蓉。"]},{"t":"八宝妆 寿节推权教","f":"词","c":["是舍人才调，犹采茅、紫芝峰。","有列宿心胸，清辞太白，雅趣元龙。","从他暂、无毡官冷，怡然怀抱自从容。","枫陛荐章吻合，金闺仙籍名通。","暑馀凉送薰风。","圆桂魄、丽遥空。","庆初度垂弧，莲开十丈，酒满千钟。","明年称寿何处，看玉犀、人在玉堂中。","藻鉴正当莲省，诸生来到蟾宫。"]},{"t":"南郊恭谢三首 其三 十二时慢","f":"词","c":["享嘉会，万宇欢康。","圣化迈陶唐。","元符锡命，天鉴昭彰。","徽号奉琳房。","陈缛礼、献岁惟良。","耀旗章。","翠辇驻仙乡。","睿意极齐庄。","仙衣渥采，玉册共荧煌。","荐芬芳。","飙驭降灵场。","回云罕，尊祖趋仙宇，金石韵锵洋。","聿朝清庙，躬奠瑶觞。","报本国之阳。","执笾豆、列侍貂珰。","对穹苍。","洪恩霈夷夏，大庆浃家邦。","垂衣紫极，圣寿保遐昌。","集祺祥。","地久与天长。"]},{"t":"虞主回京四首 十二时 其三 警场内","f":"词","c":["望嵩邙。","永昭陵畔，王气压龙冈。","巩洛灵光。","郁郁起嘉祥。","虚彩帟，转哀仗，閟幽堂。","叹仙乡路长。","景霞飞松上。","珠襦宵掩，细扇晨归，昆阆茫茫。","满目东郊好，红葩斗芳。","韶景空骀荡。","对春色、倍凄凉。","最情伤。","从辇嫔嫱。","指瑶津路，泪雨泣千行。","翠珥明珰。","曾忆荐琼觞。","春又至，人何往。","事难忘。","向斜阳断肠。","听钧天嘹亮。","清都风细，朱栏花满，谁奏清商。","紫幄重帘外，时飘宝香。","环佩珊珊响。","问何日、反雕房。"]},{"t":"籍田明道二年四曲 其三 十二时","f":"词","c":["君天下，万国来王。","玉帛凑梯航。","五风十雨，品物蕃昌。","栖垄有馀粮。","躬千亩、天步龙翔。","化重光。","举祖彝章。","验晨正农祥。","东郊如砥，黛耜御游场。","荐芬芳。","稼穑伫丰穰。","成耨礼，三事并卿尹，执耒有经常。","此仪旷绝，行自吾皇。","玉振复金相。","睹九色、流衍仓箱。","洽欢康。","虫鱼皆茂育，戈祋永韬藏。","两闱至圣，辅以股肱良。","祚延长。","寿岳保无疆。"]},{"t":"天圣二年南郊鼓吹歌曲三曲 其三 十二时","f":"词","c":["嘉亨运，璇历均调。","光烈迈唐尧。","珍图缘错，垂锡乾霄。","封岱顺车杓。","修合答、万玉来朝。","瑞丕昭。","构宇结瑛瑶。","虚气下仙飙。","钦崇道祖，舆驾动临谯。","整銮镳。","郊报厚黎苗。","均纯贶，渗漉咸滋液，能事播欢谣。","继明缵绪，缓赋轻徭。","京庾比丰饶。","勤中昃、采善询荛。","五风飘。","授人时吏正，休马櫜兵销。","良肱隆栋，助化率皇僚。","德声遥。","懿铄简书标。"]},{"t":"明堂 其三 十二时","f":"词","c":["恢皇统，宵旰勤考，正朔亶同规。","留谈经幄，来谏书帷。","稽古极文思。","尊耀魄、宝秩神祗。","礼从宜。","显相协钦祗。","颢气结华滋。","西成献瑞，百谷满京坻。","化无为。","斯万卜年期。","隆昌运，大报同姬成，文武绍重熙。","历朝缺典，自我亲祠，容采炳葳蕤。","嘉能事、秀错多仪。","太平时。","清风涵溥惠，浩露浃深慈。","群方昭泰，保定宅华夷。","拥灵禧。","万叶累鸿基。"]},{"t":"亲耕籍田四首 其三 十二时","f":"词","c":["临寰宇，恭已岩廊。","属意在耕桑。","爱民利物，德迈陶唐。","跻俗尽淳庞。","开千亩、帝籍神仓。","举彝章。","祗祓坛场。","为农事祈祥。","涓辰行礼，节物值春阳。","罄齐庄。","明德荐馨香。","宫禁邃，嫔妃并御侍，穜稑献君王。","中闱表率，阴教逾光。","帐殿霭熉黄。","梐枑设、翠幕高张。","庆云翔。","樽罍陈酒醴，金石奏宫商。","神灵感格，岁岁富仓箱。","庆明昌。","行旅不赍粮。"]},{"t":"显仁皇后上同发引三首 其三 十二时","f":"词","c":["炎图景运正延鸿。","文思坐深宫。","慈宁大养，乐事时奏宸聪。","皇龄永，恩霈下，遍寰中。","君王乘彩服，嫔御上瑶钟。","年年诞节，就盈吉月，交庆流虹。","欢洽意方浓。","不觉仙游渺邈，但号泣苍穹。","追慕念音容。","诗书慈俭，配古追踪。","躬行四德，谁知继、二南风。","移盼俄空，宝鉴脂泽尘封。","清都远，帝乡遥，杳难通。","想云軿、还上瀛蓬。","稽山何在，当年禹宅，万古葱葱。","最难堪，潮头定，海波融。"]},{"t":"元丰二年慈圣光献皇后发引四首 十二时 其三 警场内","f":"词","c":["治平时。","暂垂帘，佑圣子、解危疑。","坐安天下逾岁。","厌避万机。","退处宸闱。","殿开庆养，志入希夷。","扶皓日，浴咸池。","看神孙、抚御千载，重雍累熙。","四方钦仰洪慈。","阴德远，仁功积，欢养罄九域，礼无违。","事难期。","乘霞去，乍睹升仙，诰下九围。","泣血涟如，更鸾车、动春晚、雾暗翠旗。","路指嵩伊。","薤歌凤吹。","悠扬逐风悲。","珠殿悄，网尘垂。","空坐湿，罔极吾皇孝思。","镂玉写音徽。","彤管炜，青编纪，宁更羡周雅，播声诗。"]},{"t":"嘉祐七年四曲 其四 十二时","f":"词","c":["承平世，嘉祐壬寅。","九月上旬辛。","酒醪香旨，谷实丰珍。","宗祀敞中宸。","宾延上帝五方神。","以严亲。","诚心通杳杳，文物盛彬彬。","金声玉色，和奏翕铿纯。","荡无垠。","天地一洪钧。","明天子、至化深仁。","一意奉精禋。","感时怵惕，即事恭夤。","用孝教斯民。","多仪举，大恩沦。","福来臻。","清风动阊阖，皓气下天津。","币诚玉腆，朱燎焜槱薪。","积欢欣。","皇历万斯春。"]},{"t":"天禧三年南郊鼓吹歌曲三曲 其三 十二时","f":"词","c":["雕戈偃玉塞清明。","道德洽和平。","龟畴凤柙，腾实飞英。","岱畎让功成。","汾水上、寅辂銮声。","荐精诚。","仙宇玉为京。","圭洁奉高明。","瑶山银榜，固国本丕闳。","诏公卿。","绵蕝殉舆情。","稽阳位，报本郊坛畤，助祭俨簪缨。","祖宗配侑，朱燎晶荧。","百礼备丰盈。","答天地、用厚怀生。","泰黎氓。","千畿先润泽，万宝尽开荣。","龙沙日窟，文轨永来并。","保嘉享，史册焕鸿名。"]},{"t":"宁宗皇帝发引三首 其三 十二时","f":"词","c":["弋绨革舄最仁贤。","俭德自躬全。","忧勤庶政，三十馀年。","金风肃，秋渐老，摄调。","忱恂遍，群祀号泣诉旻天。","缀衣将出，神凝玉几，一夜登仙。","弓堕隔苍烟。","七月有来同轨，引绋动灵辁。","凄怆泪潸然。","行号巷哭，薤露声传。","东城去路，惊涛忍见江船。","憔悴山川。","不禁箫鼓咽，山阴处，茂林修竹芊芊。","望陵宫，应弗远，金粟堆前。","人徒慕恋，百神警待，盘翥驱先。","戴鸿恩，空痛慕，泪珠连。","千秋岁、功德寄华编。"]},{"t":"奉祀太清宫三首 其三 十二时","f":"词","c":["乾坤泰，帝祚遐昌。","宇县乐平康。","真游降格，宝诲昭彰。","宸跸造仙乡。","崇妙道、精意齐庄。","款灵场。","洁豆荐芬芳。","备乐奏铿锵。","犹龙垂裕，千古播休光。","极褒扬。","明号洽徽章。","朝修展，春豫谐民望。","睹文物煌煌。","言旋羽卫，肃设坛场。","报本达萧芗。","申严祀、礼备烝尝。","答穹苍。","纯禧沾品汇，庆赉浃穷荒。","封人献寿，德化掩陶唐。","保绵长。","锡祐永无疆。"]},{"t":"治平二年南郊鼓吹歌曲四曲 其三 十二时慢","f":"词","c":["千年运，五叶升平。","法扆坐中楹。","天高日润，雷动风行。","三万里声明。","灵台偃伯仆边兵。","事农耕。","一气重滋萌。","万宝迄登成。","天生嘉谷，博硕又芳馨。","罄齐精。","谒款谢嘉生。","神明地，当阳定，天位来助见人情。","璧圭葱璨，金石铿鈜。","仪礼盛西京。","灵祗喜、福禄来盈。","咏夷庚。","幔城班上笏，銮路趣还衡。","觚棱双阙，赭案切三清。","动欢声。","恩泽遍寰瀛。"]},{"t":"高宗祀大礼鼓吹歌曲五首 其三 十二时","f":"词","c":["日将旦、阴曀潜消。","天宇扇祥飙。","边陲静谧，夜熄鸣刁。","文教普旁昭。","兴太学、多士舒翘。","奉宗祧。","新庙榜宸毫。","配侑享于郊。","慈宁万寿，四海仰东朝。","男女正，中壶至桃夭。","年屡稔，漕舟衔尾夥，高廪接楹饶。","庙堂自有、擎天一柱，功比汉庭萧。","多少群工同德，俊乂旁招。","吉祥诸福集，燮理四时调。","三年郊见，六变奏咸韶。","望云霄。","降福与唐尧。"]},{"t":"八年神宗灵驾发引四首 其三 十二时慢","f":"词","c":["珍符锡佑启真人。","储思在斯民。","勤劳日升万物，皆入陶钧。","收威柄，更法令，鼎从新。","东风吹百卉，上苑正青春。","流虹节近，衣冠玉帛，交奏严宸。","万寿祝尧仁。","忽听宫车晚出，但号慕，瞻云路，企龙鳞。","穷天英。","冠古精神。","杳然上傃，人空望、属车巡。","虚仗星陈。","画翣环拥龙輴。","泉宫掩，帝乡远，邈难亲。","反雕轮。","飞羽盖、还渡天津。","雾迷朱服，风摇细扇，触目悲辛。","列嫔嫱，垂红泪，浥行尘。","相将问。","何日下青旻。"]},{"t":"虞主回京四首 其三 十二时","f":"词","c":["太平时。","御华夷。","躬听断破危疑。","春秋鼎盛，绌声乐游嬉。","日升繁机。","长驾远驭垂。","意在轩羲。","恢六典、斥三垂。","有殊尤绝迹，盛德魄周施。","方将缀缉声诗。","扩皇纲，明帝典，绍累圣重熙。","高拱无为。","事难知。","春色盛，逼千秋嘉节，忽闻玉几。","颁命彤闱。","厌世御云归。","翊翠凤，驾文螭。","缥缈难追。","侍臣宫女，但攀慕号悲。","玉轮动，指嵩伊。","龙镳日益远空游，汉庙冠衣。","惟盛德巍巍。","镂玉册，传青史。","昭示无期。"]},{"t":"祫享太庙 其四 十二时","f":"词","c":["明昌世、乾统弥文。","皇德揆华勋。","三辰顺晷，庆霭轮囷。","潜宝耀坤珍。","躬祫飨、肃荐牺尊。","孝仪申。","助祭俨缨绅。","大乐奏韶钧。","阳开阴闭，幽显尽欣欣。","庆霄文。","思结在黎民。"]},{"t":"宁宗郊祀大礼四首 其二 十二时","f":"词","c":["宵景霁，河汉清夷。","旷典讲明时。","合祛升侑，孝德爰熙。","陈祼閟宫，澹觞太室，来奏天仪。","驷苍螭。","玉辂驭蕤绥。","觚陛展躬祠。","长梢饰玉，翠羽秀金支。","华始倡，雅韵出宫垂。","神来下，云车风马，缤晻蔼、宴栖迟。","毕觞流胙，紫烟竣事，棠梨回谒，宣室受蕃厘。","盛德无心专飨，端为民祈。","云恩有截，雨泽霈无涯。","君王愉乐，和气溢瑶卮。","寿天齐。","长拥神基。"]},{"t":"嘉祐元年四曲 其四 十二时","f":"词","c":["金徒箭、晓漏延长。","霄极烂星芒。","珠旒绚采，黼衮交章。","宸表寝永昂。","上交合奠鬯流香。","燎扬光。","神锡以百祥。","寿延于无疆。","三时告稔，万亿满仓箱。","思边防。","蛮貊尽来王。"]},{"t":"庄献明肃皇后恭谢太庙 其三 十二时","f":"词","c":["母仪下，国祚和平。","玉帛凑寰瀛。","尤祥极瑞，茂实英声。","两耀比皇明。","昭孝飨、躬荐精诚。","祥并保佑洽由庚。","和乐遍怀生。","柔远能迩，海宇永澄清。","复曾城。","宝册受鸿名。","绵龙绪，十治同齐圣。","至治播欢声。","止戈为武，顿纲搜英。","察万物人情。","损服御、不尚瑛琼。","俗怀生动，修文考制，颛法上天明。","地不爱宝，人不爱其诚。","帝图宏。","寿岳永峣峥。"]},{"t":"真宗封禅四首 其三 十二时慢","f":"词","c":["圣明代，海县澄清。","惠化洽寰瀛。","时康岁足，治定功成。","遐迩贺升平。","嘉坛上，昭事神灵。","荐明诚。","报本禅云亭。","俎豆列牺牲。","宸心蠲洁，明德荐惟馨。","纪鸿名。","千载播天声。","燔柴毕，云罕回仙仗，庆銮辂还京。","八神扈跸，四隩来庭。","嘉气覆重城。","殊常礼，旷古难行。","遇文明。","仁恩苏品汇，沛泽被簪缨。","祥符锡祚，武库永销兵。","育群生。","景运保千龄。"]},{"t":"安恭皇后上仙发引三首 其三 十二时","f":"词","c":["皇家景运合无疆。","天子坐明堂。","丰年多黍，四方争报时康。","酒常清，花易好，寿君王。","天宫见玉女，大笑亿千场。","不知何事，椒涂暗淡，瑶殿凄凉。","宝镜玉台光。","可奈画眉人去，脂泽散馀芳。","极目望潇湘。","波遥草远，只见残阳。","南山古阜，松柏茂，蔚苍苍。","杳霭宫商。","风过金殿琳琅。","道歌繁，严鼓近，惨悲伤。","水凝愁，山攒恨，烟淡云黄。","神山何在，蟠桃已远，弱水何长。","最难堪，回翟雉，返鸾凰。","向芙蓉别殿、谩焚香。"]},{"t":"十月桃","f":"词","c":["东篱菊尽，遍园林败叶，满地寒荄。","露井平明，破香笼粉初开。","佳人共喜芳意，呵手剪、密插鸾钗。","无言有艳，不避繁霜，变作春媒。","问武陵溪上谁栽。","分付与南园，舞榭歌台。","恰似凝酥衬玉，点缀装裁。","东君自是为主，先暖信、律管飞灰。","从今雪里，第一番花，休话江梅。"]},{"t":"十月梅/十月桃","f":"词","c":["千林凋尽，一阳未报，已绽南枝。","独对霜天，冒寒先占花期。","清香映月浮动，临浅水、疏影斜敧。","孤标不似，绿李夭桃，取次成蹊。","纵寿阳、妆脸偏宜。","应未笑、天然雅态冰肌。","寄语高楼，凭栏羌管休吹。","东君自是为主，调鼎鼐、终付他时。","从今点缀，百草千花，须待春归。"]},{"t":"卜算子","f":"五言古诗","c":["欲把愁分付。"]},{"t":"卜算子","f":"词","c":["我有一枝花，斟我些儿酒。","唯愿花心似我心，岁岁长相守。","满满泛金杯，重把花来嗅。","不愿花枝在我旁，付与他人手。"]},{"t":"卜算子","f":"词","c":["烟髻绾层巅，云叶生寒树。","斜日行人窈窕村，愁阵纵横处。","细细写蛮笺，道寄相思语。","会倩春风展柳眉，回马章台路。"]},{"t":"卜算子","f":"词","c":["算一一都在我心头。"]},{"t":"卜算子","f":"五言古诗","c":["借问陇头梅，春信还知否。"]},{"t":"卜算子","f":"词","c":["曾约再来时，花暗春风树。","今日人来花未开，春未知人处。","坐客有疏狂，彩笔题新语。","浑为玉人颓玉山，忘了阳关路。"]},{"t":"卜算子","f":"词","c":["垂螺近额时，只怕莺声老。","尽日贪花斗草忙，不信有闲烦恼。","凤鬓已胜钗，恨别王孙早。","若把芳心说与伊，道绿遍、池塘草。"]},{"t":"卜算子","f":"词","c":["半破玉梅春，小簇金莲炬。","结裹风流倬底郎，直入阳台去。","休诧鹊桥仙，说甚缑山侣。","便合齐眉八百年，个是真仙子。"]},{"t":"卜算子","f":"七言古诗","c":["你为情多泪亦多。"]},{"t":"万年欢 其一","f":"词","c":["北陆风回，顿园林凋尽，庭院岑寂。","潇洒寒梅，偷报艳阳消息。","素澹英姿粹质。","天赋与、出伦标格。","一枝向、雪里初开，纤说清香寻得。","神仙乍离姑射。","更琼妆翠佩，冰莹肌骨。","仿佛华清浴罢，懒匀脂泽。","陇上休轰怨笛。","且留取、累累成实。","终须待、金鼎调羹，偏与群芳春色。"]},{"t":"万年欢 仁寿夫人生日","f":"词","c":["日暖霜融，画戟门开，锦筵欲振梁尘。","正是慈闱熙熙，庆诞佳辰。","象服鱼轩粲烂，喜高年、福禄长新。","承颜处，朱紫满堂，华胄诜诜。","家声未论王谢，有禁中颇牧，江左机云。","雁序鸳行，雍容高步金门。","更有子孙侍列，拥阶庭、玉洁兰薰。","持芳醑、满酌瑶觞，意祝遐寿千春。"]},{"t":"万年欢 其二","f":"词","c":["天气严凝，乍寒梅数枝，岭上开拆。","傅粉凝脂，疑是素娥妆饰。","先报阳和信息。","更雪月、交光一色。","因追念，往日欢游，共君携手同摘。","别来又经岁隔。","奈高楼梦断，无计寻觅。","冷艳寒容，啼雨恨烟愁湿。","似向人前泪滴。","怎不使、伊家思忆。","惟只恐，寂寞空枝，又随昨夜羌笛。"]},{"t":"万年欢 寿太守","f":"词","c":["南极星明，问笙歌弦管，今是何夕。","竹马儿童，尽道使君生日。","又见蟠桃结实。","是谁向、珠宫偷得。","炉烟袅，惟愿年年，使君常驻熊轼。","那知宦游似客。","任双旌五马，飘转南北。","细柳甘棠，都是使君亲植。","见说吾皇仄席。","恐非晚、归朝宣直。","功成了，却隐东山，算惟龟鹤相识。"]},{"t":"万年欢慢/万年欢 其三","f":"词","c":["婥妁要肢轻婀娜。","学内样、深深梳果。","如五凤双鸾相对舞，随腰带、乍游琐。","莺幕、满头花，见绿杨摸蔌。","金阶献，一庭细管繁弦里，谁把ㄉ抛过。"]},{"t":"万年欢慢/万年欢 其一","f":"词","c":["禁籞初晴，见万年枝上，巧啭莺声。","藻殿连云，萍曦高照檐楹。","好是帘开丽景，袅金炉、香暖烟轻。","传呼道、天跸来临，两行拱引簪缨。","看看筵敞三清。","洞宝玉杯中，满酌犀觥。","烂熳芳葩，斜簪庆快春情。","更有箫韶九奏，簇鱼龙、百戏俱呈。","吾皇愿、永保洪图，四方长乐升平。"]},{"t":"万年欢慢/万年欢 其二","f":"词","c":["当今圣主，理化感四塞，永减狼烟。","太平朝野无征战，国内晏然。","风调雨顺歌声喧。","箫韶韵，九奏钧天。","愿王永寿，比南山、更奏延年。"]},{"t":"上阳春/蓦山溪 寿邹魁侄十一月廿八","f":"词","c":["疏梅点白，漏泄先春信。","律欲变黄钟，但两日、一阳月尽。","龙头望族，挺挺振家声，窗下业，月中枝，雁塔书名姓。","琴堂拟步，早发梅仙轫。","台阁待风生，想咫尺、天颜已近。","壮行未老，便作黑头公，还未定，祝千春，看子孙昌盛。"]},{"t":"上阳春/蓦山溪 寿人夫妻二子同日十月初二","f":"词","c":["两日梅开，先占阳春小。","鸾凤偶雁行，飞舞画堂交绕。","称觞盛旦，二老同年少。","夫劝妇，弟酬兄，四喜人希有。","灵椿萱草，青翠俱长久。","棠棣戏斑斓，对立齐上长生酒。","有亲有序，慈孝兼恭友。","登科日，未老时，共享南山寿。"]},{"t":"少年游","f":"词","c":["绞绡雾縠，没多重数，紧拟偷怜。","孜孜觑着，算前生、只结得眼因缘。","眼是心媒，心为情本，里外勾连。","天还有意，不违人愿，与个团圆。"]},{"t":"于飞乐","f":"词","c":["教我莫思量，争不思量。"]},{"t":"于飞乐","f":"词","c":["近来清瘦，为谁为谁。"]},{"t":"于飞乐","f":"词","c":["天然体段殊常。"]},{"t":"千春词 寿游侍郎","f":"词","c":["瞿岭云齐，建溪源远，庆衍英奇。","且机乘天巧，臣贤主圣，后光同日月以为期。","千载相逢，一朝盛事，自昔人夸今见之。","催归诏，要领班宸殿，捧万年卮。","嘻嘻。","莫道春迟。","已著梅梢第一枝。","映紫荷持橐，星辰步武，黄金横带，朝夕论思。","不但斯时，重恢事业，整顿乾坤弘所施。","洪钧转，虽寒根雪谷，物物生辉。"]},{"t":"千秋岁 十二月初九","f":"词","c":["斗杓建丑。","蓂叶初开九。","贤哲降，千龄偶。"]},{"t":"千秋岁 四月初九","f":"词","c":["麟垂绂秀。","天纵今司寇。","朱明景，清和候。","缙云开帝乐，括苍钟神秀。","人争羡，昨生一佛今朝又。","璧水声华茂。","玉殿天香袖。","姑小试，陶甄手。","行为黄阁老，屹立丹墀右。","名不朽，斯文名脉从君寿。"]},{"t":"千秋岁","f":"词","c":["腊残春近。","江上梅开粉。","一枝漏泄东君信。","寿阳妆面靓，姑射冰姿莹。","似浅杏。","清香试与分明认。","只恐霜侵破，又怕风吹损。","待折取，还不忍。","莫将花上貌，来点多情鬓。","凝睇久，行人立马成遗恨。"]},{"t":"千秋岁","f":"词","c":["一声啼鸟，常道无消息。"]},{"t":"千秋岁 寿翁文叔三月廿三","f":"词","c":["园林翠幄。","妆点青春色。","犹觉蓂留七叶。","崧神今日降，产此真英杰。","蟾宫客，尽推一代文章伯。","富贵何心得。","积善多阴德。","那管青衫白发。","儿孙俱满目，诗礼传衣钵。","长不老，蓝桥是个神仙宅。"]},{"t":"千秋岁 庆生日女受聘九月十七","f":"词","c":["律调无射。","月望才逾日。","昴宿呈祥南极。","称觞祈五福，膺聘陈双璧。","彩堂上，老人婺宿光交集。","龟鹤年相敌。","孔雀屏开侧。","喜与寿，俱逢吉。","门楣他日作，椒觞歌今日。","看父子，乘龙跨鹤皆仙匹。"]},{"t":"千秋岁 寿江东帅七月十一","f":"词","c":["金陵秋早。","四日中元到。","天降诞，真英表。","长庚腾瑞气，箕宿增辉耀。","膺帝渥，十连镇抚民多少。","莫惜椒觞倒。","祝寿称难老。","分帅阃，江东小。","看看飞诏下，早趣黄扉召。","平章了，长生学取神仙道。"]},{"t":"木兰花慢 夫寿妻","f":"词","c":["记当初归我，似德耀、嫁梁鸿。","算三十年间，艰难历遍，甘苦相同。","新来有孙可抱，也添些、喜色到眉峰。","今日又逢生日，不妨樽酒从容。","老翁。","只是一村农。","欠你孺人封。","幸儿渐知耕，妇能知织，莫问穷通。","君看世间富贵，比浮云、缥缈过晴空。","何似大家清健，玉林岁岁春风。"]},{"t":"千秋岁 十二月三十","f":"词","c":["欢盈万屋。","声杂当庭竹。","腾宝篆，辉银烛。","东君将到处，祗隔邮亭宿。","谁知道，此时诞个人如玉。","红叶题宫墨。","流入人间曲。","天香在，犹芬馥。","满斟眉寿醑，共劝千龄福。","情未足，来朝更把酴酥祝。"]},{"t":"千秋岁引 寿徐直院四月十二","f":"词","c":["词赋伟人，当代一英杰。","信独步儒林蟾宫客。","名登雁塔正青春，更不历郡县徒劳力。","即趋朝，典文衡，居花掖。","得隽词科推第一。","便掌丝纶天上尺。","见说庆生辰，当此日。","翠蓂三四叶方新，况朱明正属清和节。","行作个，黑头公，专调燮。"]},{"t":"千秋岁令/千秋岁引","f":"词","c":["想风流态，种种般般媚。","恨别离时大容易。","香笺欲写相思意。","相思泪滴香笺字。","画堂深，银烛暗，重门闭。","似当日、欢娱何日遂。","愿早早相逢重设誓。","美景良辰莫轻拌，鸳鸯帐里鸳鸯被。","鸳鸯枕上鸳鸯睡。","似恁地，长恁地，千秋岁。"]},{"t":"大圣乐 初夏","f":"词","c":["千朵奇峰，半轩微雨，晓来初过。","渐燕子、引教雏飞，菡萏暗薰芳草，池面凉多。","浅斟琼卮浮绿蚁，展湘簟双纹生细波。","轻纨举，动团圆素月，仙桂婆娑。","临风对月恣乐，便好把千金邀艳娥。","幸太平无事，击壤鼓腹，携酒高歌。","富贵安居，功名天赋，争奈皆由时命呵。","休眉锁。","问朱颜去了，还更来么。"]},{"t":"女冠子","f":"词","c":["同云密布。","撒梨花、柳絮飞舞。","楼台诮似玉。","向红炉暖阁院宇。","深庭广排筵会，听笙歌犹未彻，渐觉轻寒，透帘穿户。","乱飘僧舍，密洒歌楼，酒帘如故。","想樵人、山径迷踪路。","料渔人、收纶罢钓归南浦。","路无伴侣。","见孤村寂寞，招飐酒旗斜处。","南轩孤雁过，呖呖声声，又无书度。","见腊梅、枝上嫩蕊，两两三三微吐。"]},{"t":"减字木兰花 寿亲戚十二月廿七","f":"词","c":["日逢三九。","相对梅花倾寿酒。","次第回春。","甲子从头又一新。","敬翻一曲。","付与歌儿勤为祝。","为问仙翁。","今岁蟠桃几度红。"]},{"t":"林钟商小品 其二","f":"词","c":["戴花殢酒，酒泛金樽，花枝满帽。","笑歌醉拍手，戴花殢酒。"]},{"t":"林钟商小品 其一","f":"词","c":["正天气凄凉，鸣幽砌，向枕畔、偏恼愁心，尽夜苦吟。"]},{"t":"小重山 其二","f":"词","c":["不是蛾儿不是酥。","化工应道也难摹。","花儿清瘦影儿孤。","多情处，时有暗香浮。","试问玉肌肤。","夜来霜雪重，怕寒无。","一枝欲寄洞庭姝。","可惜许，只有雁衔芦。"]},{"t":"小重山","f":"词","c":["鼓报黄昏禽影歇。","单衣犹未试，觉寒怯。","尘生锦瑟可曾阅。","人去也，闲过好时节。","对景复愁绝。","东风吹不散，鬓边雪。","些儿心事对谁说。","眠不得，一枕杏花月。"]},{"t":"小重山","f":"词","c":["络纬声残织翠丝。","金风剪不断、雁来时。","梦回缄泪寄征衣。","寒到早，应怪寄衣迟。","心事有谁知。","黄昏常立尽、暗萤飞。","秋来无处不生悲。","情脉脉，月转辘轳西。"]},{"t":"小重山 其三","f":"词","c":["天际春来都为君。","依稀丹萼动，泛红云。","恼人天气近黄昏。","霜月底，山麝斗微薰。","标格自天真。","寿阳仙骨瘦，玉无纹。","芳容临鉴洗馀醺。","双蛾稳，花面两难分。"]},{"t":"小重山","f":"词","c":["竹里清香帘影明。","一枝照水弄精神。","楼头横管罢龙吟。","休三弄，留为与调羹。","紫陌与青门。","溪边浮动处，绝纤尘。","等闲休付寿阳人。","潇洒处，月淡又黄昏。"]},{"t":"小重山","f":"七言古诗","c":["水风生处小亭临。"]},{"t":"小重山","f":"七言古诗","c":["六曲句阑四面风。"]},{"t":"马家春慢","f":"词","c":["珠箔风轻，绣帘浪卷，乍入人间蓬岛。","斗玉阑干，渐庭馆帘栊春晓。","天许奇葩贵品，异繁杏、夭桃轻巧。","命化工、倾国风流，□与一枝纤妙。","樽前五陵年少。","纵丹青异格，难别颜貌。","悲露凝烟，困红娇额，微颦低笑。","须信浓香易歇，更莫惜、醉攀吟绕。","待舞蝶游蜂，细把芳心都告。"]},{"t":"乌夜啼 其一","f":"词","c":["都无一点残红。","夜来风。","底事东君归去、太匆匆。","桃花醉。","梨花泪。","总成空。","断送一年春在、绿阴中。"]},{"t":"乌夜啼 其二","f":"词","c":["一弯月挂危楼。","似藏钩。","醉里不知黄叶、报新秋。","征鸿断。","归云乱。","远峰愁。","愁见绿杨凝恨、在江头。"]},{"t":"鬓云松令 般涉送傅国华奉使三韩","f":"词","c":["鬓云松，眉叶聚。","一阕离歌，不为行人驻。","檀板停时君看取。","数尺鲛绡，果是梨花雨。","鹭飞遥，天尺五。","凤阁鸾坡，看即飞腾去。","今夜长亭临别处。","断梗飞云，尽是伤情绪。"]},{"t":"五彩结同心","f":"词","c":["珠帘垂户。","金索悬窗，家接浣沙溪路。","相见桐阴下，一钩月、恰在凤凰栖处。","素琼捻就宫腰小。","花枝袅、盈盈娇步。","新妆浅，满腮红雪，绰约片云欲度。","尘寰岂能留住。","唯只愁、化作彩云飞去。","蝉翼衫儿薄，冰肌莹，轻罩一团香雾。","彩笺巧缀相思苦。","脉脉动、怜才心绪。","好作个、秦楼活计，要待吹箫伴侣。"]},{"t":"天禧三年南郊鼓吹歌曲三曲 其二 六州","f":"词","c":["齐天宇，四海洽淳风。","接宝胄，垂真检，景祚无穷。","成玉牒、日观归功。","冀野升方鼎，脽上由崇。","钦桧井、云跸巡东。","国本震为宫。","乾文焕炳，真祠曲密，重祥叠瑞，琼蕴降高穹。","膺丕烈，虔心建垂鸿。","询吉士，郊兆执玉荐衷。","钟律应、云物迎空。","乐和轮囷。","嘉气葱葱。","天神来降发冲融。","玉烛四时通。","星回金辂雷作解，昆蚑被惠，亿载帝基隆。"]},{"t":"亲耕籍田四首 其二 六州","f":"词","c":["昭圣武，不战屈人兵。","干戈戢，烽燧息，海宇清宁。","民丰业，歌咏升平。","愿咸归畎亩，力穑为氓。","经界正、东作西成。","农务轸皇情。","躬亲耒耜，相劝深耕。","人心感悦，击壤沸欢声。","乘鸾辂，羽旗彩仗鲜明。","传清跸，行黄道，缇骑出重城。","仰瞻日表，映朱纮。","环佩更锵鸣。","百执公卿。","不辞染履意专精。","准拟奉粢盛。","田多稼，风行遐迩，家家给足，胥庆三登。"]},{"t":"祫享太庙 其三 六州","f":"词","c":["深仁化。","穹厚格成平。","徇诚虑，托皇统，万宇光亨。","申孝致洁飨宗祊。","金驾徐徐动，容礼辉明。","躬道祖谒款殊庭。","列圣固纯诚。","灵心底豫，休祥充塞，端闱肆眚，爱日灿然明。"]},{"t":"奉祀太清宫三首 其二 六州","f":"词","c":["千载运，宝业正遐昌。","钦至道，崇明祀，盛礼迈前王。","銮辂动，万骑腾骧。","驰道纷彩仗，瑞日煌煌。","奉秘检、玉羽群翔。","非雾满康庄。","躬朝真馆，齐心绎思，顺风俯拜，奠酒爇萧芗。","精衷达，飙轮降格昭彰。","回羽旆，驻雕辇，旧地访睢阳。","享清庙、孝德辉光。","届灵场。","星罗万国圭璋。","陈牲币、金石锵洋。","景福降穰穰。","垂衣法坐，恩覃群品，庆均海宇，圣寿保无疆。"]},{"t":"明堂 其二 六州","f":"词","c":["崇严配，衢室飨中宸。","寻汉礼，崇唐典，袭映情文。","方宝辂、羽卫星陈。","藻绣填驰路，昭烂如云。","灵顾諟，德升闻。","旷瑞集纷纶。","承平嘉靖，收成和熟，万方歌舞，喜气满青旻。","成熙事、宣和舆物惟新。","展宫寝，疑庙室，飨帝极尊亲。","罄宸虑，四海骈臻。","肃簪绅。","斋明际，浃人神。","乾元盛则属兹辰。","皇业协华勋。","房心正位，端居报政，三年美荐，广孝福吾民。"]},{"t":"高宗祀大礼鼓吹歌曲五首 其二 六州","f":"词","c":["双凤落，佳气蔼龙山。","澄江左，清湖右，日夜海潮翻。","因吉地、卜筑圜坛。","宏基隆陛级，神位周环。","边陲静、挂起櫜鞬。","奠枕海隅安。","三年亲祀，一阳初动，虔修大报，高处紫烟燔。","看鸣銮，钩陈肃，天仗转，朔风寒。","孤竹管，云和瑟，乐奏彻天关。","嘉笾荐、玉奠玙璠。","奉神欢。","九霄瑞气起祥烟。","来如风马欻然。","还留福，已滋繁。","回龙驭，升丹阙，布皇泽，春色满人间。"]},{"t":"真宗封禅四首 其二 六州","f":"词","c":["良夜永，玉漏正迟迟。","丹禁肃，周庐列，羽卫绕皇闱。","严鼓动，画角声齐。","金管飘雅韵，远逐轻飔。","荐嘉玉、躬祀神祗。","祈福为黔黎。","升中盛礼，增高益厚，登封检玉，时迈合周诗。","玄文锡，庆云五色相随。","甘露降，醴泉涌，三秀发灵芝。","皇犹播、史册光辉。","受鸿禧。","万年永固丕基。","吾君德、荡荡巍巍。","迈尧舜文思。","从今寰宇，休牛归马，耕田凿井，鼓腹乐昌期。"]},{"t":"八年神宗灵驾发引四首 其二 六州","f":"词","c":["炎图盛，六叶正，协重光。","膺宝瑞，更法度，智勇超轶成汤。","昭回云汉烂文章。","震扬威武慑多方。","生民帖泰拥殊祥。","封人祝颂，万寿与天长。","岂知丹鼎就，龙下五云旁。","飘然真驭。","游衍仙乡。","泣彤裳。","伊落洋洋。","嵩峰少室相望。","藏弓剑，游衣冠，俊功盛德难忘。","泉台寂、鱼烛荧煌。","银海深、凫雁翱翔。","想像平居谩焚香。","望陵人散，翠柏忽成行。","犹馀嵩峰月，夜夜照幽堂。","千秋陈迹凄凉。"]},{"t":"天圣二年南郊鼓吹歌曲三曲 其二 六州","f":"词","c":["承皇统，天地洽清宁。","熙帝载，建民极，百度推明。","崇讲肄、博考儒经。","游豫腾谣诵，星跸天行。","留绀宇、顺拜金庭。","兆庶动欢声。","灵心上达，卿云成盖，祥风袭物，瑞日耀圜清。","列圣孝德被寰瀛。","就阳位协吉，周正俨簪缨。","交对越群灵。","皇威赫奕盛仪成。","徽册受鸿名。","鸡竿肆赦，鸳行均庆，翾飞浸泽，期万保升平。"]},{"t":"嘉祐七年四曲 其三 六州","f":"词","c":["承景运，天子奉明堂。","玉烛应，金飙动，万宝盈箱。","严法驾、天路龙骧。","采仗迎祥。","日色动扶桑。","款清庙、我诚将。","回御八鸾锵。","于皇仁孝，祖宗来顾，熙于四极，令问载无疆。","躬严配、笙镛奏凤来翔。","瑞烟起，浮帝衮，玉步间天香。","升重宇、璧玉华光。","桂流觞。","神虞夕照熉黄。","九霄鸣佩下清厢。","齐拱太微傍。","群心同愿，长临路寝，三年讲礼，显祀文王。"]},{"t":"宁宗郊祀大礼四首 其一 六州","f":"词","c":["皇抚极，明德贯乾坤。","信星列，卿云烂，辉亘紫微垣。","思报贶、明诏祠宫，练时搜旷典，紫畤觚坛，昭孝德、亲御和銮。","振鹭玉珊珊。","精纯谒款，膋萧爌炀。","黄流湛澹，百末布生兰。","扣天阍，延飞驾，相彷佛，降云端。","神光集，嘉向应，霭霭万衣冠。","竣熙事清晓轻寒。","恣荣观。","华衣雾縠般般。","乾坤并贶庆君欢。","翘首圣恩宽。","遵皇极，沛天泽，灵心怿，龟鼎永尊安。"]},{"t":"宁宗皇帝发引三首 其二 六州","f":"词","c":["明天子，昔日丕纂鸿图。","躬道德，崇学问，稽古训，访群儒。","日亲广厦、论唐虞。","讲求政治、想都俞。","君臣一德、志交孚。","外夷效顺，犹自选车徒。","仁恩沾四国，固结满寰区。","千年宗社，万岁规摹。","重新天命出乾符。","老癃策杖相扶。","愿观德化遍方隅。","幸无死须臾。","谓宜圣寿等嵩呼。","遽登云舆。","上龙湖。","宸居幽寂紫云孤。","宸章宝画，但与日星俱。","龙帷凤翣已载涂。","忍听笳鼓嗟呼。"]},{"t":"嘉祐元年四曲 其三 六州","f":"词","c":["严太寝，容礼绎前经。","仰苍粹，钦厚顺，式报生成。","至信洽，上格神灵。","太和凝气象，霄宇澄清。","圭币列，鼓钟铿。","群品荐丰盈。","熙事既备，大仪交举，百嘉允集，万福来迎。"]},{"t":"虞主回京四首 其二 六州","f":"词","c":["承圣绪，垂意在升平。","驱貔虎，策豪英。","号令肃天兵。","四方无复羽书征。","德泽浸群生。","睿谋雄俊，绌汉高狭陋，慕三皇二帝，登闳缉乐缀文明。","将升岱岳告功成。","玉牒金绳。","腾宝飞声。","事难评。","轩鼎就、清都一梦俄顷。","飞霞佩，乘龙驭，羽卫入高清。","祥光浮动五色，迎鸾凤，杂箫笙。","因山功就，同轨人至，铭旌画翣，行背重城。","楚笳凝咽，汉仪雄盛，攀慕伤情。","惟馀内传，知向蓬瀛。"]},{"t":"虞主回京四首 六州 其二 警场内","f":"词","c":["庆深恩。","宝历正乾坤。","前帝子，后圣孙。","援立两仪轩。","西宫大母朝寝门。","望椒闼常温。","芳时媚景，有三千宫女，相将奉、玉辇金根。","上林红英繁。","缥缈钧天。","奏梨园。","望绝瑶池，影断桃源。","恨难论。","开禁阍。","春风丹旐翩翩。","飞翠盖、驾雕辒。","容卫入西原。","管箫动地清喧。","陵上柏烟昏。","残霞弄影，孤蟾浮天外，行人触目是销魂。","问苍天。","尘世光阴去如奔。","河洛潺湲。","此恨长存。"]},{"t":"元丰二年慈圣光献皇后发引四首 六州 其二 警场内","f":"词","c":["九龙舆。","记春暮、幸蓬壶。","琼囿敞，绣仗趋。","年华与逝水俱。","瑶京远，信息断无。","宝津池面落花铺。","愁晚容车来禁涂。","凤箫鸾翣，西指昭陵去。","旧赏蟠桃熟，又见涨海枯。","应共灵真母，曳霞裾。","宴清都。","恨满山隅。","春城翠柏藏乌。","扃户剑，照灯鱼。","人间一梦觉馀。","泉宫窈窕锁夜龙，银江澄澹浴仙凫。","烟冷金炉玉殿虚。","绿苔新长，雕辇曾行处。","夜夜东朝月，似旧照锦疏。","侍女盈盈泪珠。"]},{"t":"南郊恭谢三首 其二 六州","f":"词","c":["承天统，圣主应昌辰。","宝箓降，飙游至，瑞命庆惟新。","崇大号，仰奉高真。","献岁当初吉，天下皆春。","谒秘宇、藻卫星陈。","芗霭极纷纶。","琼编焜耀，仙衣綷䌨，垂旒俯拜，荐献礼惟寅。","芬芳备，精衷上达穹旻。","尊道祖，享清庙，助祭万方臻。","升泰畤、缛典弥文。","侍群臣。","汉庭儒雅彬彬。","烟飞火举毕严禋。","天地降氤氲。","高临华阙，恩覃动植，庆延宗社，圣寿比灵椿。"]},{"t":"籍田明道二年四曲 其二 六州","f":"词","c":["寰宇定，四海奉文思。","书轨混，梯航凑，共戴昌期。","稽古典、方咏京坻。","耕籍丰民稼，敦本农时。","陈羽卫、日月旌旗。","衮冕次坛壝。","帷宫宿设，梐枑相差。","穆清端拱，星毕照罘罳。","良宵永，为民广洽，厖褫奏、行漏昭庭燎，铙吹鼓曾飔。","百神拥卫斗东移。","明发俨皇仪。","手揽洪縻。","丰年万亿与千斯。","德泽遍华夷。","回旋辂、天临双阙，四方在宥，永保鸿基。"]},{"t":"显仁皇后上同发引三首 其二 六州","f":"词","c":["中兴运，孝治格升平。","回騩驭，弭凤驾，册宝初上鸿名。","龙楼问寝候鸡鸣。","更翻莱戏彩衣轻。","坤躔夜照老人星。","金觞上寿，长愿燕慈宁。","乘云何处去，愁断紫箫声。","追思金殿，椒壁丹楹。","又谁知、勤俭仁明。","风行化被宫庭。","佑圣主，底明时。","阴功暗及生灵。","离宫晚、花卉娉婷。","甲观高、潮海峥嵘。","往事回头忽飘零。","空留嫔御，掩泣望霓旌。","会稽山翠，永祐陵高，而今便是蓬瀛。"]},{"t":"治平二年南郊鼓吹歌曲四曲 其二 六州","f":"词","c":["垂炎运，真主嗣瑶图。","海波晏，卿云烂，日月丽皇都。","年屡稔、万宝山储。","广莫风生律，一气潜嘘。","陈法驾、翠羽装舆。","清跸下天衢。","金匏六变，欻然灵顾，来车风马，拜贶紫坛初。","奉神娱。","嘉笾荐，美玉奠，照荧?。","星彩动，霜华薄，禁阁漏声疏。","回龙驭、宝瑞纷敷。","众心愉。","钧天别奏箫竽。","仙人楼上捧赦书。","舞鹤更踌蹰。","丹徼北，穷沙漠，涵皇泽，盛德迈唐虞。"]},{"t":"庄献明肃皇后恭谢太庙 其二 六州","f":"词","c":["炎灵永。","长乐助文明。","居靖懿，敷皇化，四海升平。","慈是宝、万物怀生。","耀德不观兵。","大治欢声。","金辂饬、藻卫天行。","春色满皇京。","登歌清庙，神祗顾飨，瑄玉纯精。","亿万载持盈。","膺天贶。","尤祥纷委来呈。","木连芝三秀，玉烛协和平。","仲春月、万杏初荣。","整羽卫葱衡。","亲款神明。","九韶叠奏罄箫笙。","上以继咸英。","黄流玉瓒，殊庭肸蚃，宸仪回复，景祐遍寰瀛。"]},{"t":"六州歌头 寿徐枢密","f":"词","c":["扬休玉色，山立秉鸿枢。","圣天子、方有志，会东都。","得真儒。","身佩安危寄，本兵柄，修军政，朝野庆，钧衡任，赖诗谟。","天上麒麟挺，徐卿子，坐肃憸夫。","向六阳时候，佳瑞纪门弧。","炳炳阶符。","照蓬壶。","看兄枢使，弟元帅，真盛事，世间无。","筹密边烽息，凛羌胡。","玉音俞。","伫正三槐位，散膏泽，福寰区。","河如带，山如砺，巩皇图。","金鼎调元远大，中书考，致主唐虞。","想公门桃李，应不弃山樗。","愿借嘘枯。"]},{"t":"凤栖梧","f":"词","c":["绿暗红稀春已暮，燕子衔泥，飞入垂杨处。","柳絮欲停风不住，杜鹃声里山无数。","竹杖芒鞋无定据，穿过溪南，独木横桥路。","樵子渔师来又去，一川风月谁为主。"]},{"t":"凤栖梧/蝶恋花","f":"词","c":["姑射仙人游汗漫。","白凤翩翩，银海光凌乱。","龟手儿童贪戏玩。","风檐更折梅梢看。","漠漠银沙平晚岸。","笑拥寒蓑，聊作渔翁伴。","横玉愁云吹不断。","归舟又载蘋花满。"]},{"t":"凤凰台忆吹箫/凤凰台上忆吹箫","f":"词","c":["红蓓珠圆，素蕤玉净，南荒已报春还。","便迤逦，云开五岭，雪霁群蛮。","喜见东君信息，应不管、潘鬓新班。","凭谁寄，心萦秋水，目断春山。","长记小桥斜渡，潇洒处，苇篱茅舍三间。","肯伴我、风光赏遍，月影疑残。","好为调羹结子，玉铉冷、金鼎空闲。","北枝畔，谁念嶰律犹寒。"]},{"t":"双头莲","f":"词","c":["触目庭台，当岁晚凋残，恁时方见。","琼英细蕊，似美玉碾就，轻冰裁剪。","暗想蜂蝶不知，有清香为援。","深疑是，傅粉酡颜，何殊寿阳妆面。","惟恐易落难留，仗何人巧把，名词褒羡。","狂风横雨，枉坠落、细蕊纷纷千片。","异日结实成阴，托称殊非浅。","调鼎鼐，试作和羹，佳名方显。"]},{"t":"双雁儿","f":"词","c":["这心事、倚他谁。"]},{"t":"天下乐令/减字木兰花 其一","f":"词","c":["寿星明久。","寿曲高歌沉醉后。","寿烛荧煌。","手把金炉，燃一寿香。","满斟寿酒。","我意殷勤来祝寿。","问寿如何。","寿比南山福更多。"]},{"t":"天仙子","f":"词","c":["危楼十二阑干曲，望不尽、愁不尽。"]},{"t":"天仙子","f":"七言古诗","c":["残月朦胧人瘦损。"]},{"t":"太平年慢 中腔唱","f":"词","c":["皇州春满群芳丽。","散异香旖旎。","鳌宫开宴赏佳致。","举笙歌鼎沸。","永日迟迟和风媚。","柳色烟凝翠。","唯恐日西坠。","且乐欢醉。"]},{"t":"太常引 其二","f":"词","c":["江梅开似蕊珠宫。","报桃李、又春风。","蓦岫看前峰。","待摘取、横斜盏中。","魏林楚岭，素妆清绝，不与众芳同。","和月映帘栊。","羡几点、施朱太红。"]},{"t":"太常引 其一","f":"词","c":["行云踪迹杳无期。","梅梢上、又春归。","不道久别离。","这一度、清香为谁。","多情嘱付，庾楼羌管，凭仗且休吹。","留取两三枝。","待和泪、封将寄伊。"]},{"t":"太清歌词","f":"五言古诗","c":["红片半随风，又半随流水。"]},{"t":"少年游","f":"词","c":["上苑莺调舌。","暖日融融媚节。","秦晋新婚，人间天上真奇绝。","傅粉烟霄，倾国神仙列。","彼此和鸣，凤楼一处明月。","歌喉佳宴设。","鸳帐炉香对爇。","合卺杯深，少年相睹欢情切。","罗带盘金缕，好把同心结。","终取山河，誓为夫妇欢悦。"]},{"t":"少年游 题锦标社疏","f":"词","c":["新竿界断一天游。","万弩向云头。","彩羽飞星，红心破日，胜集总名流。","好手业中施好，利物敢轻酬。","捧杆箭多，旗花饯少，快请办头筹。"]},{"t":"忆人人/鹊桥仙 其一","f":"词","c":["密传春信。","微妆晓景，淡伫香苞欲绽。","临风虽未吐芳心，奈暗露、盈盈粉面。","何人月下，一声长笛，即是飞英凌乱。","凭阑无惜赏芳姿，更莫待、倾筐已满。"]},{"t":"忆人人/鹊桥仙 其二","f":"词","c":["前村深雪，难寻幽艳，无奈清香漏绽。","烟梢霜萼出墙时，似暗妒、寿阳妆面。","幽香浮动，无缘攀赏，但只心劳魂乱。","不辞他日醉琼姿，又只恐、阴成子满。"]},{"t":"忆王孙","f":"词","c":["杨柳风前旗鼓闹。","正陌上、闲花芳草。","忍将愁眼觑芳菲，人未老。","春先老。","长安比日知多少。","日易见、长安难到。","无情苕水不西流，渐迤逦、仙舟小。"]},{"t":"忆吹箫慢/凤凰台上忆吹箫","f":"词","c":["血洒霜罗，泪薄艳锦，伊方教我成行。","渐望断、斜桥暮柳，曲水归云。","月暗风高露冷，独自才抵孤城。","江南远，今夜就中，愁损行人。","愁人。","旧香遗粉，空淡淡馀暖，隐隐残痕。","到这里、思量是我，忒㬠无情。","水更无情侣我，催画航、一日三程。","休烦恼，相见定约新春。"]},{"t":"忆秦娥","f":"词","c":["花蹊侧。","秦楼夜访金钗客。","金钗客。","江梅风韵，野棠颜色。","尊前醉倒君休惜。","不成去后空相忆。","空相忆。","山长水远，几时来得。"]},{"t":"忆秦娥 其三 咏笛","f":"词","c":["秋寂寂。","碧纱窗外人横笛。","人横笛。","天津桥上，旧曾听得。","宫妆玉指无人识。","龙吟水底声初息。","声初息。","月明江上，数峰凝碧。"]},{"t":"忆秦娥 其一 忆别","f":"词","c":["暮云碧。","佳人不见愁如织。","愁如织。","两行征雁，数声羌笛。","锦书难寄西飞翼。","无言只是空相忆。","空相忆。","纱窗人梦，梦双人只。"]},{"t":"忆秦娥","f":"词","c":["烟漠漠。","水天摇荡蓬莱阁。","蓬莱阁，朱甍碧瓦，半浸寥廓。","三山谩有长生药。","茫茫云海风涛恶。","风涛恶。","仙槎不见，暮沙潮落。"]},{"t":"忆秦娥","f":"词","c":["瑶台月。","寒光零乱蒙香雪。","蒙香雪。","横枝疏影，动人清彻。","分明姑射神仙骨。","冰姿雪里难埋没。","难埋没。","百花头上，为春先发。"]},{"t":"忆秦娥","f":"词","c":["香馥馥。","樽前有个人如玉。","人如玉。","翠翘金凤，内家妆束。","娇羞爱把眉儿蹙。","逢人只唱相思曲。","相思曲。","一声声是，怨红愁绿。"]},{"t":"忆秦娥 其一","f":"词","c":["娇滴滴。","双眉敛破春山色。","春山色。","为君含笑，为君愁蹙。","多情别后无消息。","此时更有谁知得。","谁知得。","夜深无寐，度江横笛。"]},{"t":"月上海棠","f":"词","c":["南枝昨夜先回暖。","便临寒、开花暗香远。","化工忒㬠，把琼瑶、恣情裁剪。","皑皑的、点缀梢头又遍。","横斜影蘸清溪浅。","似玉人、临鸾照粉面。","大家休折，且迟留、对花开宴。","祝东风、吹作和羹未晚。"]},{"t":"月华清慢/月华清","f":"词","c":["雨洗天开，风将云去，极目都无纤翳。","当遇中秋夜，静月华如水。","素光晃、金屋楼台，清气彻、玉壶天地。","此际。","比无常三五，婵娟特异。","因念玉人千里。","待尽把愁肠，分付沉醉。","只恐难当漏尽，又还经岁。","最堪恨、独守书帏，空对景、不成欢意。","除是。","问姮娥觅取，一枝仙桂。"]},{"t":"木兰花慢 其一","f":"词","c":["望阳生渐布，见梅萼、暖初回。","向雪里、一枝才苞，素艳已占春台。","烟笼半含粉面，透清香、暗触满襟怀。","可惜前村望断，魏林庾岭栽培。","皑皑。","嫩蕊清光，凝笑也恁风猥。","但折取行人，途中对酒，不用尊罍。","芬芳正当岁暮，谩休夸桃李苦相催。","早报明年律应，又还依旧先开。"]},{"t":"木兰花慢 其二","f":"词","c":["饱经霜古树，怕春寒、趁腊引青枝。","逗一点阳和，隔年信息，远报佳期。","凄葩未容易吐，但凝酥半面点胭脂。","山路相逢驻马，暗香微染征衣。","风前袅袅含情，虽不语、引长思。","似怨感芳姿，山高水远，折赠何迟。","分明为传驿使，寄一枝春色写新词。","寄语市桥官柳，此先占了芳菲。"]},{"t":"木兰花慢 寿主簿十一月初五","f":"词","c":["腊前冬至后，报春意、动南坡。","见葭管浮灰，梅英缀玉，漏泄阳和。","阶蓂呈瑞五叶，祥开嵩岳耸嵯峨。","笑拥两行珠翠，欢腾一曲笙歌。","试将铜狄细摩挲。","问寿富如何。","道寿等冈陵，富连阡陌，福禄多多。","德门最堪羡处，有乔松丹桂映婆娑。","管取脱身簿领，即登奕世儒科。"]},{"t":"减字木兰花 贺人女试晬","f":"词","c":["小春良月。","尧砌蓂开三数叶。","瑞启三躔。","此夕人间诞女仙。","寿期百岁。","今日欢娱初庆晬。","喜事重重。","亦有嘉祥应梦熊。"]},{"t":"木兰花/玉楼春 其一","f":"七言律诗","c":["东风昨夜吹春昼。","陡觉去年梅蕊旧。","谁人能解把长绳，系得乌飞并兔走。","清香潋滟杯中酒。","新眼苗条江上柳。","尊前莫惜玉颜酡，且喜一年年入手。"]},{"t":"木兰花/玉楼春 其二","f":"七言律诗","c":["东风昨夜归来后。","景物便为春意候。","金丝齐奏喜新春，愿介香醪千岁寿。","寻花插破桃枝臭。","造化工夫先到柳。","熔酥剪彩恨无香，且放真香先入酒。"]},{"t":"木兰花 春日述怀","f":"七言律诗","c":["小桃枝上东风转。","□□草绿江南岸。","绿杨学舞小蛮腰，红药惜开菩萨面。","故乡何处天涯远。","黄粱梦断行云断。","登楼准拟故人书，殷勤试问西归雁。"]},{"t":"减字木兰花 兄螟乃弟子","f":"词","c":["花间棠棣。","匹似人间兄与弟。","一种花枝。","底事当年却盛衰。","中藏蜾蠃。","忽遇螟蛉真类我。","换叶移根。","要与相辉映一门。"]},{"t":"减字木兰花 庆女人三月初五","f":"词","c":["蓂开五叶。","正是瑶池逢诞节。","昨夜观星。","南极边头婺女明。","家邻九曲。","寿比群仙何待祝。","满劝金钟。","但问蟠桃几度红。"]},{"t":"减字木兰花 庆赵倅","f":"词","c":["北湖云锦。","铺遍琉璃三万顷。","风月诗仙。","趁得花时出洞天。","红菱碧藕。","满劝一杯千岁寿。","来岁看花。","新筑苏堤路上沙。"]},{"t":"木兰花慢 寿制干三月初七","f":"词","c":["晓烟生绿树，听叶底、数声莺。","正节届清明，蓂开七荚，梦叶长庚。","桥门旧时冠带，念短檠、读尽夜深灯。","文价乾坤推重，世紏父子同登。","莹然玉雪做精神。","野鹤见长身。","算婉画崇台，活人多少，自合长生。","荆襄暂烦佐幕，听秋风鼓角夜连营。","唤起隆中豪杰，共图盖世功名。"]},{"t":"天仙子 寿贩米运舟人四月廿三","f":"词","c":["浮家泛宅生涯好。","聚米堆盐多积宝。","烟波得趣乐江湖，宜乘兴，寻安道。","不负轩辕当日造。","初度喜逢维夏早。","孔释昔曾亲送抱。","下弦良日是生朝，称觞献，金樽倒。","惟愿寿筵长不老。"]},{"t":"天仙子 贺生孙生子","f":"词","c":["晚节寒花犹带蕊。","隐映老人星瑞世。","绿衣初是政成归，真盛事。","谁可比。","那更新来孙又子。","烟细金炉香旖旎。","想像瑶池生绿蚁。","酿成佳气郁葱葱，当此际。","将一醉。","百岁从交今日始。"]},{"t":"水龙吟 寿李府尹","f":"词","c":["邦人前世条缘，福星遇得长庚李。","光芒初照，一声霹雳，重开天地。","试问年来，民间安枕，伊谁之赐。","有青天白日，和风甘雨，公如父、氏如子。","今度虎牌重到，感皇恩、欢声千里。","衮归未晚，纱笼人物，御屏名字。","碧嶂长春，清江不尽，棠阴堪憩。","愿年年把酒，庆公初度，祝公千岁。"]},{"t":"水龙吟慢/水龙吟","f":"词","c":["玉皇金阙长春，民仰高天欣载。","年年一度定佳期，风情多感慨。","绮罗竞交会。","争折花枝两相对。","舞袖翩翩歌声妙，掩粉面、斜窥翠黛。","锦额门开彩架，球儿裳、先秀神仙队。","融香拂席霓裳动，铿锵环佩。","宝座巍巍五云密，欢呼争拜退。","管弦众作欲归去，愿吾皇、万年恩爱。"]},{"t":"水调歌头","f":"词","c":["不能烦恼得，掉臂便归休。","前度风樯，这回潦辙几悠悠。","幸得有云一谷，更自有书万卷，著甚么来由。","月采混鱼目，霜口涴蝇头。","相山中，侯醉境，将诗流。","情知薄命，天样勋业也须收。","辟逻世间万事，推放那边一壁，百尺卧高楼。","日月草头露，天地水中沤。"]},{"t":"水调歌头 贺真西山","f":"词","c":["人道孰为大，尚小易咸常。","厥初皇极中建，扶世有三纲。","仁义阴阳道立，父母乾坤位正，六子发辉光。","一日不容缓，此意久弥昌。","杯举庆，天作合，月探囊。","十年不字以正，乃字便惟良。","推阐家人一卦，迤逦齐家治国，鼎鼐得姬姜。","旧物中书令，玉润继汾阳。"]},{"t":"水调歌头 其二 贺新居","f":"词","c":["三径当松竹，五亩足烟霞。","个中卜宅，蓬山佳致足君家。","前有书江环绕，后有横岗崒嵂，万象总森罗。","轮奂翚飞处，此屋岂无华。","绿窗开，朱户敞，绣帘遮。","燕闲自适，百篇斗酒是生涯。","种善善根未绝，延桂桂枝可待，谁子为君夸。","佳嗣一夔足，荣耀必多嘉。"]},{"t":"水调歌头 其一 寿学生","f":"词","c":["金兽袅香穗，银烛灿花枝。","眼前风景殊异，酌酒庆生时。","要是祖宗流庆，方有此身此日，盍亦反其思。","何以上雅寿，敢用此为规。","况君家，本学业，致轻肥。","牙签玉轴，全胜阡陌占东西。","好把胸中一点，照破堂中万卷，五福自来宜。","谨勿效雌伏，指日要雄飞。"]},{"t":"水调歌头 寿刘宰母","f":"词","c":["泽国嫩寒月，天气小阳春。","萱堂今朝生日，瑞霭郁轮囷。","身佩铜章墨绶，手捧霞觞玉液，献寿太夫人。","且喜藤舆稳，共戏彩衣新。","发垂鹄，瞳点漆，倍精神。","麻姑来庆，笑道沧海几扬尘。","伫看起居八座，更好回班百辟，异数耸朝绅。","此母生此子，再拜谢宸恩。"]},{"t":"水调歌头","f":"词","c":["八蛮朝凤阙，四境绝狼烟。","太平无事，超烘聚哨效梨园。","笛弄昆崙上品，筛动云阳妙选，画鼓可人怜。","乱撒真珠迸，点滴雨声喧。","韵堪听，声不俗，驻云轩。","谐音节奏，分明花里遇神仙。","到处朝山拜岳，长是争筹赌赛，四海把名传。","幸遇知音听，一曲赞尧天。"]},{"t":"水调歌头 寿平交五十","f":"词","c":["学易喜加数，富贵正当年。","谁识晚成大器，信道古来然。","莫叹无闻不足，官政从今艾服，知命自由天。","恰合买臣愿，好著祖生鞭。","藏学问，通今古，冠英贤。","管取一名一第，行折桂枝先。","未数奉书朱穆，窃笑表微拭镜，接武引群仙。","生日年年庆，绛老愿齐肩。"]},{"t":"水调歌头 十二月十四日","f":"词","c":["今日雪飞六出，明夜月圆三五，梅腊正传芳。","恰值生申节，共献椒觞。"]},{"t":"水调歌头","f":"词","c":["帆落松陵浦，枯柳缆琼艘。","杖策无人独步，浪压百花桥。","我挂风裳水佩，一笑波寒月白，馀韵触惊涛。","绝景有谁赏，雾幕闭三高。","不须臾，千古事，一萧条。","鲈鱼纵有，泽荒甫里失溪桥。","更吾名高业茂，终归荒田野草，且稳一枝巢。","举酒酹空阔，烟远路迢迢。"]},{"t":"水调歌头 寿王枢密，又得子八月廿六","f":"词","c":["谷旦垂弧矢，兰阃梦熊罴。","称觞内外相庆，同日又同时。","有此重重盛事，未羡石门奋建，韦氏信名齐。","珠履赴汤饼，玉果酌琼卮。","斗枢转，金瓯覆，筑沙堤。","争推是父是子，相继入黄扉。","方叔歌猷元老，复见少年黄琬，前后拜丹墀。","今日寿星现，再祝寿庞眉。"]},{"t":"水调歌头 贺人生侄","f":"词","c":["燕分炳箕宿，鲁野照奎星。","天开岳渎，储瑞重见吐书麟。","人道兰庭生谢，我羡竹林得阮，中夜沸欢声。","奇称符百药，童号迈终军。","姿禀厚，骨骼异，气神清。","好把一经为教，切莫诧籯金。","击瓮画图休展，对日有言可听，材大等庄椿。","年欲临志学，上国早充宾。"]},{"t":"水调歌头 其三 十二月廿六","f":"词","c":["年春里，归去凤凰池上，国号恰新颁。","玉立诸郎秀，丹桂看齐樊。"]},{"t":"水调歌头 庆友人","f":"词","c":["何以作公寿，一纸寄讴吟。","当年生申有兆，鸑鷟梦文禽。","气宇虹霓万丈，胸次蟠龙七泽，锦绣萃中心。","高谊薄云表，随处是知音。","人俊逸，文卓荦，气雄深。","版岩合辞故隐，霖雨慰当今。","且把梅花酌酒，行即桂枝入手，桑荫未移阴。","珍重此时祝，何日盍朋簪。"]},{"t":"水调歌头 生日自寿","f":"词","c":["久雨忽开霁，花靥斗春娇。","家人笑道，老子今日是生朝。","细数平生功行，断自狂吟之外，全不犯科条。","心事淡如水，天合与逍遥。","也何须，期寿算，比松乔。","但令此去清健，到处狎渔樵。","说与门前鸥鹭，护我山中杞菊，日日长心苗。","世事儿戏耳，尊酒百尤消。"]},{"t":"水调歌头 其一 十二月二十四","f":"词","c":["瑞溢飞猿峤，秀毓凤凰山。","腊馀六日春到，人间世庆生贤。"]},{"t":"水调歌头 其一","f":"词","c":["昭代数人物，谁似我公贤。","平生礌礌磊磊，常以义为先。","广立湖中义学，盛集陕西义社，良法自家传。","阴德有如此，眉寿不须言。","圣天子，方右武，复宗文。","诗中马上，看君父子共争先。","伫听天山三箭，还共秋闱一举，相继凯歌旋。","金印大如斗，富贵出长年。"]},{"t":"水调歌头","f":"词","c":["握虎符，持玉节，佩金鱼。","三十正当方面，此事世间无。","寄语东淮父老，夺我诗书元帅，于汝抑安乎。","早早归廊庙，天下尽欢娱。"]},{"t":"水调歌头 贺人生子","f":"词","c":["尧历庆良月，嶰管换新冬。","玉成西爽，五云拂晓画楼东。","人指谢家庭砌，眼底猗兰奕叶，特地茁新丛。","不是善根种，争得占春风。","步鹏程，名虎榜，早收功。","建安衣钵，定知他日属奇童。","且说而今胜事，珠履三千称贺，相对醉颜红。","拜贺无他语，相庆黑头公。"]},{"t":"水调歌头 其三 庆东屏","f":"词","c":["来复迈七日，亨泰兆三阳。","恰逢临吉中应，浸长三阳刚。","天地凝成正气，岳渎钟为秀杰，玉燕纪呈祥。","莹彻冰壶操，皎月映秋霜。","日星回，乾坤辟，再更张。","时乘君子道长，茅茹喜生光。","抱负黄钟大吕，资禀盐梅栋柏，施用在岩廊。","一骑春风里，紫诏下山堂。"]},{"t":"水调歌头 其一 贺新居","f":"词","c":["蹑足半天下，作意赋归欤。","燕申经始不日，胸次出规模。","千古神峰拥护，万古横江缭绕，佳致足方壶。","一饮一词美，还得似君无。","十步楼、五步阁，恣安居。","薰蒸和气，袭人盎盎觉春如。","况是庄椿不老，那更徐鸡并秀，父子看名俱。","驷马高车盖，不减汉之于。"]},{"t":"水调歌头 其二 寿刘监丞","f":"词","c":["一线添宫绣，昼景刻初还。","五云旬浃不散，瑞色满乾坤。","凝作山堂佳气，来庆冰壶寿旦，戏彩喜重斑。","相对窦桂椿，环列谢芝兰。","经纶事，戡定策，两才全。","苍生翘首三载，霖雨报东山。","已感宵衣梦寐，应录御屏姓字，光动紫微垣。","一骑日边至，趣诏凤池班。"]},{"t":"水调歌头","f":"词","c":["竹边风细，月色淡阴阴。"]},{"t":"水调歌头 寿太守傅侍郎，前三日冬至十一月十八","f":"词","c":["关中有萧相，江左见夷吾。","中兴帝赉良弼，休运应乾符。","百五期过一日，十万声号半夜，南极灿晴虚。","崧岳生申甫，河洛出图书。","领坡仙，陪橐从，镇潜都。","九重昨夜有梦，问到北岩无。","须信建溪桃李，难驻商川舟楫，归去伴都俞。","岁伴南山寿，日拱北辰居。"]},{"t":"水调歌头 六月十六","f":"词","c":["律纪林钟月，兔魄夜来圆。","彩麟入梦，天教英物出人间。","志气平生浩荡，欲试经纶大手，赞画向名藩。","见说齐瓜熟，鹏路快扶抟。","称寿处，歌齿皓，戏衣斑。","辉联甥馆，那堪一笑共团栾。","好看蜚声霹雳，使有蒲轮迎召，催入侍龙颜。","却待功成后，归伴幔亭仙。"]},{"t":"水调歌头 贺人再娶","f":"词","c":["阿谁煎凤髓，续此玉琴弦。","依然音调清婉，律吕互相宣。","天使彭城姝丽，来配鲁邦才子，永作地行仙。","况有盈门礼，百两拥骈阗。","更临鸾，看举案，两无偏。","从此欢谐千岁，月下与花前。","胜长芝兰玉树，俱作蟾宫佳客，声誉振螺川。","仍看明年去，平步上青天。"]},{"t":"水调歌头 寿赵阆州五月初五","f":"词","c":["玉斧折丹桂，锦绣拂银河。","蟠胸虹气千丈，捧砚唤宫娥。","三度花攒五马，一笑毫挥万字，何处不恩波。","试问老仙寿，铜狄几摩挲。","舞槐龙，垂艾虎，弄清和。","湖山风月，且与吟笑侧金荷。","明岁端阳时节，人在薰风殿阁，凉意入赓歌。","宣劝滟昌歜，叠雪赐香罗。"]},{"t":"水调歌头 寿枢密","f":"词","c":["明月双溪上，胜景号金华。","当年此夕，多少鸾凤杂云霞。","共拥飘飘仙伯，来作人间英杰，王谢旧名家。","纶綍妙文采，帷幄富忠嘉。","圣天子，形梦寐，眷尤加。","麒麟阁上，早晚丹陛听宣麻。","鼎轴无穷勋业，岁岁熏风日永，萱秀北堂花。","潋滟绮筵酒，寿算等河沙。"]},{"t":"水调歌头 寿隐士十月十八","f":"词","c":["橘记一年景，梅泄小春英。","见说彭成仙隐，对此庆生辰。","寿比太公欠一，年并楚丘逾九，益壮异常人。","细数称觞日，信宿两弥旬。","戏莱衣，桥梓列，桂兰荣。","一门盛事难得，一子两层孙。","休论若儿渠父，差胜杨椿黄琬，四代眼前亲。","积善有馀庆，享福百千春。"]},{"t":"水调歌头 寿刘枢甥十月廿九","f":"词","c":["今日小春月，后日是周正。","瑞蔼挹仙堂上，崧岳喜生申。","文物师垣宅相，诗礼枢庭世胄，冰骨玉精神。","浩气凌牛斗，胸次夐凡尘。","郭中书，广成子，李长庚。","勋业词章福寿，直上等三人。","松菊亭前诗酒，梅竹园中翰墨，时复萃嘉宾。","人指屏山下，双桂一灵椿。"]},{"t":"水调歌头 其一 寿真玉堂","f":"词","c":["早是玉堂客，犹著侍臣冠。","便为霖去亦晚，何况此身闲。","胸次光风霁月，意味满庭芳草，体用两相关。","坐对粤山好，名更重于山。","寿生申，霜肃晓，露宾寒。","从教重九过了，政有菊堪餐。","日绕东篱笑傲，香共秋容淡薄，晚节要人看。","久不见贾谊，天已问平安。"]},{"t":"水调歌头","f":"词","c":["云作伴，月为邻。"]},{"t":"水调歌头 其二 寿丘月林","f":"词","c":["天地钟奇秀，山泽有儒仙。","词锋前驱万马，三度奏捷菊花天。","信是文场敏手，如把枭卢对掷，高叱便回旋。","一点英雄气，四顾浩无边。","长羡君，先我著，祖生鞭。","今朝尊酒持劝，岂特颂长年。","要入兰宫妙选，共向集英殿里，玉陛听胪传。","姓字标黄甲，香墨照人鲜。"]},{"t":"水调歌头 寿范帅","f":"词","c":["三楚诗书帅，人物压中州。","飘飘青琐，典刑蜀国旧风流。","小袖玉堂挥手，来拥元戎十乘，红旆照青油。","尺一唤归去，名久在金瓯。","倚春声，赓水调，倩歌喉。","登龙旧客，只回误上武陵舟。","正是蟠桃开也，特向尊前为寿，一醉一千秋。","携取此花去，还侍玉宸游。"]},{"t":"水调歌头 寿王制置十一月初六","f":"词","c":["宝历契昌运，岳渎启珍符。","汾阳忠义勋阅，此际挂蓬弧。","正属阳生子月，始见蓂敷六荚，宝剑出昆吾。","芒射斗牛分，光彩照坤舆。","备文武，宏器量，足谋谟。","世传韬略，出专阃制誓平胡。","尽护貔貅百万，仰副九重委注，指日复舆图。","祝寿如山阜，进位陟洪枢。"]},{"t":"水调歌头 和韵谢人贺生子","f":"词","c":["玉琯届良月，璇极炳明星。","适当季舍，有梦应麒麟。","但愧衡门深隐，偶尔玉川添累，还解振家声。","乐章歌一阕，笔阵扫千军。","羡君侯，为学富，焕文清。","青云咫尺要路，曳紫更腰金。","顾我荆榛虽茂，其奈栋材无用，何似八千椿。","君王行赐宴，礼重敬如宾。"]},{"t":"水调歌头","f":"词","c":["箫鼓阗街巷，锦绣裹山川。","夜来南极，闪闪光射泰阶躔。","陡觉佳祥翕集，听得闾阎笑道，蓬岛降真仙。","香满琴堂里，人在洞壶天。","斟凿落，歌窈窕，舞蹁跹。","重阳虽近，莫把萸菊玷华筵。","菲礼岂能祝寿，自有仙桃满院，一实数千年。","早晚朝元会，苍鬓映貂蝉。"]},{"t":"水调歌头 建炎庚戌题吴江","f":"词","c":["平生太湖上，短棹几经过。","如今重到，何事愁与水云多。","拟把匣中长剑，换取扁舟一叶，归去老渔蓑。","银艾非吾事，丘壑已蹉跎。","脍新鲈，斟美酒，起悲歌。","太平生长，岂谓今日识兵戈。","欲泻三江雪浪，净洗胡尘千里，不用挽天河。","回首望霄汉，双泪堕清波。"]},{"t":"水调歌头 寿周相子正月初一","f":"词","c":["雪霁万山出，和气蔼王正。","平园春事竞起，梅柳冻全醒。","此际朝元归路，疑有真仙呈瑞，笙鹤九霄声。","东阁识风度，南极粲光明。","看精神，秋夜月，玉壶冰。","淳熙相业隆盛，家自得仪刑。","闻道君王神武，捷报胡儿宵遁，玉殿正论兵。","行奉紫泥诏，帷幄佐中兴。"]},{"t":"水调歌头 寿史相七月廿九","f":"词","c":["两只补天手，一片济时心。","信道相门再相，现此宰官身。","涤洗乾坤都了，填压华戎既定，治世庆升平。","中外为冠冕，闻望耸簪缨。","星昴降，蓬矢挂，属芳辰。","黄阁一秋来早，明日又三旬。","庭戏莱衣双桂，砌列谢兰无数，廊庙会风云。","愿衍庄椿算，长沛傅岩霖。"]},{"t":"水调歌头 寿徐枢七月十二","f":"词","c":["称彼兕觥后，三日是中元。","地官较善，龙章玉佩压仙班。","自是德星孕秀，直与寿星争耀，茨福正绵绵。","堂已富金玉，屣踪视王官。","趣清闲，心洒落，在花间。","桃培万岁，千年仙种又栽莲。","静对秋香菊耐，长共岁寒松老，生意满西园。","待看椿同桂，洗馥迈燕山。"]},{"t":"水调歌头 庆史守正月初四","f":"词","c":["一札自天下，五马为民来。","潜藩久须重镇，帝命出蓬莱。","曾侍九重笔橐，暂剖一州符竹，人谓屈公材。","儒术要扬历，玉业待规恢。","庆三元，才四日，寿筵开。","夜深仰视霄汉，南极映星台。","休说石家父子，休说窦家昆季，乔木即三槐。","归觐玉皇案，馀事付盐梅。"]},{"t":"水调歌头 庆龙图八月十三","f":"词","c":["八月秋欲半，后夜月将圆。","天潢当日流润，馀派落人寰。","尘扫长淮千里，威振南蛮八郡，梓里绣衣还。","芳毓燕山桂，庆衍谢庭兰。","小山阴，长松下，白云间。","壶中自有天地，闻早挂蓬冠。","笑指横空丹壑。","闲倚拿云竹杖，佳处日跻攀。","山色既无尽，公寿亦如山。"]},{"t":"水晶帘/南歌子 上定齐六月廿七","f":"词","c":["谁道秋期远，正旬浃、双星相见。","雨足西帘，正玉井莲开，寿筵初展。","麈尾呼风袢暑净，那更著、纶巾羽扇。","殢清歌，不记杯行，任深任浅。","湖边小池苑。","渐苔痕竹色，青青如染。","辨橘中荷屋，晚芳自占。","蜗角虚名身外事，付骰子、纷纷戏选。","喜时平、公道开明，话头正转。"]},{"t":"长相思","f":"词","c":["晴也行。","雨也行。","雨也行时不似晴。","天晴终快人。","名也成。","利也成。","利也成时不似名。","名成天下惊。"]},{"t":"长相思","f":"词","c":["绣停针。","泪盈盈。","断肠梁燕语声频。"]},{"t":"长相思 其三","f":"词","c":["雨如丝。","柳如丝。","织出春来一段奇。","莺梭来往飞。","酒如池。","醉如泥。","遮莫教人有醒时。","雨晴都不知。"]},{"t":"长相思 其二","f":"词","c":["云垂垂。","雨霏霏。","只恐今年花事迟。","不然孤负伊。","燕飞飞。","柳依依。","有个人人倚翠扉。","深攒双黛眉。"]},{"t":"长相思","f":"词","c":["花满枝。","柳满枝。","眼底春光似旧时。","燕归人未归。","泪沾衣。","酒沾衣。","烦恼长多欢事稀。","此情风月知。"]},{"t":"长相思","f":"词","c":["去年秋，今年秋，湖上人家乐复忧。","西湖依旧流。","吴循州，贾循州，十五年前一转头。","人生放下休。"]},{"t":"长相思 其一","f":"词","c":["不思量。","又思量。","一点寒灯耿夜光。","鸳衾闲半床。","雨声长，漏声长。","几阵斜风摇纸窗。","如何不断肠。"]},{"t":"相思引 贺生子、其弟又新婚","f":"词","c":["潇洒江梅春早处，天然一种两般奇。","开花结子，何事恰同时。","昨夜北枝开雪里，朝来青子又南枝。","这般好事，消得付新词。"]},{"t":"长相思 其四","f":"词","c":["燕成双。","蝶成双。","飞去飞来杨柳旁。","问伊因底忙。","绿纱窗，篆炉香。","午梦惊回书满床。","棋声春昼长。"]},{"t":"风入松 寿刘倅九月初九","f":"词","c":["晓来凉气满芙蓉。","日到竹阴东。","称觞歌袖三千指，屏星畔、绕绿围红。","茱糁百杯秋色，桂华十里西风。","生朝对饮菊花丛。","九日一樽同。","文章歆向家声旧，便应去、黄阁从容。","唤起仙翁为寿，种成千岁椿松。"]},{"t":"风中柳令/谢池春","f":"词","c":["爱鬓云长，惜眉山，寻乍相见，一时眠起。","为伊尚验，未欲将言相戏。","早樽前、会人深意。","霎时间阻，眼儿早巴巴地。","便也解、封题相寄。","怎生是款曲，终成连理。","管胜如、旧来识底。"]},{"t":"风光好","f":"词","c":["柳阴阴。","水深深。","风约双凫不自禁。","碧波心。","孤村桥断人迷路。","舟横渡。","旋买村醪浅浅斟。","更微吟。"]},{"t":"风流子","f":"词","c":["淑景皇州满，和风渐、催促柳花飞。","过清明骤雨，五侯台榭，青烟散入，新火开时。","绣帘外、傍人飞燕子，映叶语黄鹂。","秋千昼永，绮罗人散，花阴笑隔，红粉墙低。","青门多行乐，寻芳处、何计强逐轻肥。","空对旧游满目，谁共开眉。","遇有时系马，垂杨影下，风前伫立，惆怅佳期。","回望故园桃李，应待人归。"]},{"t":"东风第一枝 其一","f":"词","c":["腊雪犹凝，东风递暖，江南梅早先拆。","一枝经晓芬芳，几处漏春信息。","孤根寒艳，料化工、别施恩力。","迥不与、桃李争妍，自称寿阳妆饰。","雪烂熳、怨蝶未知，嗟燕孤、画楼绮陌。","暗香空写银笺，素艳谩传妙笔。","王孙轻顾，便好与、移栽京国。","更免逐、羌管凋零，冷落暮山寒驿。"]},{"t":"东风第一枝 其二","f":"词","c":["溪侧风回，前村雾散，寒梅一枝初绽。","雪艳凝酥，冰肌莹玉，嫩条细软。","歌台舞榭，似万斛、珠玑飘散。","异众芳，独占东风，第一点装琼苑。","青萼点、绛唇疏影，潇洒喷、紫檀龙麝。","也知青女娇羞，寿阳懒匀粉面。","江梅腊尽，武陵人、应知春晚。","最苦是，皎月临风，画楼一声羌管。"]},{"t":"东坡引 寿余倅","f":"词","c":["人物伊周样。","清政龚黄状。","平分风月双溪上。","红颜方少壮。","红颜方少壮。","生贤令节，满觞摇漾。","红袖舞，青蛾唱。","我来祝寿无他望。","相门重拜相。","相门重拜相。"]},{"t":"击梧桐","f":"词","c":["雪叶红凋，烟林翠减，独有寒梅难并。","瑞雪香肌，碎玉奇姿，迥得佳人风韵。","清标暗折芳心，又是轻泄，江南春信。","最好山前水畔，幽闲自有，横斜疏影。","尽日凭阑，寻思无语，可惜飘琼飞粉。","但怅望、王孙未赏，空使清香成阵。","怎得移根帝苑，开时不许众芳近。","免教向、深岩暗谷，结成千万恨。"]},{"t":"古记/如梦令 其三","f":"词","c":["疑是水晶宫殿。","云女天仙宝宴。","吟赏欲黄昏，风送一声羌管。","烟淡。","霜淡。","月在画楼西畔。"]},{"t":"古记/如梦令 其二","f":"词","c":["腊半雪梅初绽。","玉屑琼英碎剪。","素艳与清香，别有风流堪羡。","苞嫩。","蕊嫩。","羞破寿阳人面。"]},{"t":"古记/如梦令 其一","f":"词","c":["一枕恹恹春困。","记得小梅风韵。","何处最关情，嫩蕊初传芳信。","堪恨。","堪恨。","谁傍横斜疏影。"]},{"t":"失调名 其三","f":"词","c":["捏个牛儿体态。","按年令，旋拖五彩。","鼓乐相迎，红裙捧拥，表一个、胜春节届。"]},{"t":"失调名","f":"词","c":["明年此□，□知谁健，且尽黄花酒。"]},{"t":"失调名","f":"词","c":["杨花飞絮。","搅乱少年情绪。"]},{"t":"失调名","f":"七言古诗","c":["汉宫梳罢女真妆，望金仙、朝朝暮暮。"]},{"t":"失调名","f":"词","c":["帝里元宵风光好，胜仙岛蓬莱。","玉动飞尘，车喝绣毂，月照楼台。","三官此夕欢谐。","金莲万盏，撒向天街。","讶鼓通宵，花灯竟起，五夜齐开。"]},{"t":"失调名","f":"七言古诗","c":["闻道酒肠宽似海。"]},{"t":"失调名 其一 古木犀词","f":"七言古诗","c":["费尽骚人词与诗。"]},{"t":"失调名","f":"词","c":["纱窗晓色朦胧。"]},{"t":"失调名","f":"词","c":["愁厌厌、脉脉上心谁消遣。"]},{"t":"失调名","f":"七言古诗","c":["恐将脂粉均妆面，羞被狂毫抹污来。"]},{"t":"失调名","f":"七言古诗","c":["别是一般春色好。"]},{"t":"木兰花 其六","f":"词","c":["况今宵好景，金吾不禁，玉漏休催。"]},{"t":"失调名","f":"词","c":["淡红衫，缕金裙。"]},{"t":"失调名","f":"七言古诗","c":["王孙去后多芳草。"]},{"t":"失调名","f":"词","c":["烛暗时酒醒，原来又是梦里。"]},{"t":"失调名","f":"词","c":["芳草绿如茵，与蓝袍、草争翠色。"]},{"t":"失调名","f":"七言古诗","c":["登楼欲认经由处，无奈云山遮望眼。"]},{"t":"失调名","f":"词","c":["独倚阑干十二。"]},{"t":"失调名 其一 古柳词","f":"五言古诗","c":["柳丝柔无力。"]},{"t":"失调名","f":"词","c":["月宫仙桂、被嫦娥试手，移来山谷。"]},{"t":"失调名","f":"五言古诗","c":["旋酌菖蒲酒，灵气满芳尊。"]},{"t":"失调名","f":"七言古诗","c":["曾教入夜月添白。"]},{"t":"失调名","f":"词","c":["有个秀才姓汪。","住在祁门下乡。","行第排来四八，做尽万千趋锵。"]},{"t":"失调名","f":"词","c":["愁烟恨粉。"]},{"t":"失调名","f":"词","c":["湖腻烟光，柳垂新绿。"]},{"t":"失调名","f":"七言古诗","c":["碧玉堂前金粟斗。"]},{"t":"失调名","f":"七言古诗","c":["燕子重来寻旧巢。"]},{"t":"失调名 其二 古鞦韆词","f":"词","c":["但入新年，愿百事、皆如意。"]},{"t":"失调名","f":"七言古诗","c":["海棠著雨透胭脂。"]},{"t":"失调名","f":"词","c":["西风渐冷，园林万木凋黄。"]},{"t":"失调名 其二","f":"五言古诗","c":["饮尽莫留残。"]},{"t":"失调名","f":"词","c":["料如今，甘心海角天涯。"]},{"t":"失调名","f":"五言古诗","c":["轻盈照路旁。"]},{"t":"失调名","f":"词","c":["天气阴阴。"]},{"t":"失调名","f":"词","c":["枕冷衾寒，夜长无奈愁何。"]},{"t":"失调名","f":"词","c":["金猊香冷。"]},{"t":"失调名","f":"五言古诗","c":["宝鸭香凝袖。"]},{"t":"失调名","f":"词","c":["高文虎，称伶俐。","万苦千辛，作个放生亭记。","后头没一句说著朝廷，尽把师归美。","这老子忒无廉耻。","不知润笔能几。","夏王说不是商王，只怕伏生是你。"]},{"t":"木兰花 其八","f":"词","c":["灯球儿小，闹蛾儿颤。","又何须头面。"]},{"t":"失调名","f":"词","c":["才向兰汤浴罢，娇羞簪云髻，正雅称鸳鸯会。"]},{"t":"失调名","f":"词","c":["不如柳絮，穿帘透幕，飞到伊行。"]},{"t":"失调名","f":"词","c":["魄散魂飞。"]},{"t":"失调名","f":"词","c":["等得秋风满院吹。","又争如、毒热时。","被唧唧啾啾，不教人来梦里，望前程也、促织儿。"]},{"t":"失调名","f":"词","c":["天上佳期。","九衢灯月交辉。","摩日候孩儿，斗巧争奇。","戴短檐珠子帽，披小缕金衣。","嗔眉笑眼，百般地、敛手相宜。","转晴底、工夫不少，引得人爱后如痴。","快输钱，须要扑，不问归迟。","归来猛醒，争如我、活底孩儿。"]},{"t":"失调名","f":"词","c":["千里有个好相识，望青山一色。"]},{"t":"失调名","f":"词","c":["□□□□□金缕。","探听春来处。"]},{"t":"失调名","f":"七言古诗","c":["柳丝只解风前舞。","诮系惹、那人不住。"]},{"t":"失调名","f":"词","c":["小窗幽幌，独坐都无侣。"]},{"t":"失调名","f":"词","c":["叠假山、得保义。","幞头上、带著百般村气。","做模样、偏得人憎，又识甚条例。","今日伏惟安置。","官诰又来索气。","不如更叠个盆山，卖八文十二。"]},{"t":"失调名","f":"词","c":["任他春去春来。"]},{"t":"失调名","f":"七言古诗","c":["砌畔蛩吟喧不住。"]},{"t":"失调名","f":"词","c":["手捻茱萸簪髻，一枝聊记重阳。"]},{"t":"失调名","f":"词","c":["从前浪荡休整理。","钉赤口、防猜忌。","而今魔难管全无，一似粽儿黏腻。"]},{"t":"失调名","f":"七言古诗","c":["怕到黄昏转凄切。"]},{"t":"失调名","f":"词","c":["送千里蟾宫客。"]},{"t":"失调名","f":"词","c":["六论不知出处。","写得乌梅几字。","圣恩广大如天，也赐束帛归去。"]},{"t":"失调名","f":"词","c":["同赏败荷疏柳。"]},{"t":"失调名","f":"词","c":["奈愁又、愁无避处，愁随一线□长。"]},{"t":"失调名","f":"七言古诗","c":["千丝万绪惹春风。"]},{"t":"失调名","f":"五言古诗","c":["湘簟展清波。"]},{"t":"失调名","f":"七言古诗","c":["炉香如雾斗帐深。"]},{"t":"失调名 其十六","f":"词","c":["倚风三喷横竹。"]},{"t":"失调名","f":"词","c":["自结成同心百索。","祝愿子、更亲自系著。"]},{"t":"失调名","f":"词","c":["东南妩媚，雌了男儿。"]},{"t":"失调名","f":"词","c":["须信道、颜色如花，命如秋叶。"]},{"t":"失调名","f":"七言古诗","c":["月移疏影上窗纱。"]},{"t":"失调名","f":"词","c":["五马游春，彩佩照人，光生南陌。"]},{"t":"失调名","f":"五言古诗","c":["何时一尊酒，重与细论文。"]},{"t":"失调名","f":"词","c":["有个秀才姓汪。","骑个驴儿过江。","江又过不得，做尽万千趋锵。"]},{"t":"失调名","f":"七言古诗","c":["入到春来转见愁。"]},{"t":"失调名","f":"词","c":["月到中秋偏莹。","乍团圆、早欺我孤影。","穿帘共透幕，来寻趁。","钩起窗儿，里面故把、灯儿扑烬。","看尽古今歌咏。","状玉盘、又拟金饼。","谁花言巧语、胡厮胫。","我只道、尔是照人孤眠，恼杀人，旧都名业镜。"]},{"t":"失调名","f":"七言古诗","c":["梧桐叶落雨潇潇。"]},{"t":"失调名 其十三","f":"七言古诗","c":["云情雨意商量雪。"]},{"t":"失调名","f":"词","c":["只为情多病也多，省可思量我。"]},{"t":"失调名","f":"七言古诗","c":["箫鼓声声且莫催。","彩球高下意难裁。"]},{"t":"失调名","f":"七言古诗","c":["落花点点绣苍苔。"]},{"t":"失调名","f":"词","c":["光生里闬，荣破天荒。"]},{"t":"失调名","f":"词","c":["瑞霞成绮。","映舴艋棹轻，鲤鱼狂风起。"]},{"t":"木兰花 其五","f":"词","c":["金吾不禁元宵，漏声更莫催晓。"]},{"t":"失调名 其七","f":"词","c":["金铺翠、蛾毛巧。","是工夫不少。","闹蛾儿拣了蜂儿卖，卖雪柳、宫梅好。"]},{"t":"失调名","f":"七言古诗","c":["花有重开月再圆。"]},{"t":"失调名","f":"五言古诗","c":["细雨乱如毛。"]},{"t":"失调名","f":"七言古诗","c":["夜来一阵催花雨。"]},{"t":"鹊桥仙","f":"七言古诗","c":["海棠花谢清明后。"]},{"t":"失调名","f":"词","c":["双凤钗头，争带御书符。"]},{"t":"失调名","f":"七言古诗","c":["嫩草初抽匀细绿。"]},{"t":"失调名","f":"词","c":["莫怪沈腰易瘦。"]},{"t":"失调名","f":"七言古诗","c":["绿草茸茸媚柳芳。"]},{"t":"失调名","f":"词","c":["说与教知。","便是中朝一汉儿。"]},{"t":"失调名","f":"词","c":["君是园中杨柳，能得几时青。","趁金明、春光尚好，尊酒赏闲情。","他年归去，强山阴处，一枕晓霞清。"]},{"t":"失调名","f":"七言古诗","c":["自有松篁为伴侣。"]},{"t":"失调名","f":"七言古诗","c":["双双飞燕柳边轻。"]},{"t":"失调名","f":"七言古诗","c":["春来长是病厌厌。"]},{"t":"失调名","f":"七言古诗","c":["寸心如铁不关愁。"]},{"t":"失调名 瑞雪对江梅赋","f":"七言古诗","c":["须教相并檐前望，被飞絮、扑簌香腮。"]},{"t":"失调名 其一","f":"七言古诗","c":["香野锦林谁是主。"]},{"t":"失调名","f":"词","c":["离情愁思，尽分付、眉头眼底。"]},{"t":"失调名","f":"词","c":["做园子，得数载。","栽培得、那花木，就中堪爱。","特将一个、保义酬劳，反做了、今日殃害。","诏书下来索金带。","这官告、看看毁坏。","放牙笏、便担屎担，却依旧种菜。"]},{"t":"失调名","f":"七言古诗","c":["薰风时送芰荷香。"]},{"t":"失调名","f":"词","c":["满地榆钱，算来难买住春归。"]},{"t":"失调名","f":"七言古诗","c":["帘卷画堂人寂静。"]},{"t":"失调名","f":"五言古诗","c":["暗把归期数。"]},{"t":"失调名","f":"词","c":["伤怀长是蹙双眉。","怎禁持。"]},{"t":"失调名","f":"七言古诗","c":["百紫千红开遍了。"]},{"t":"失调名","f":"词","c":["角黍厅前，祭天神、妆成异果。"]},{"t":"失调名","f":"七言古诗","c":["无情却被多情恼。"]},{"t":"失调名","f":"词","c":["为谁瘦、为谁癯。"]},{"t":"失调名","f":"七言古诗","c":["花有重开日□圆。"]},{"t":"失调名","f":"词","c":["兽炭共围，通宵不寐，守尽残更待春至。"]},{"t":"失调名","f":"七言古诗","c":["好容仪、取次梳妆。"]},{"t":"失调名","f":"词","c":["休休得也□，云深处、高卧斜阳。"]},{"t":"失调名","f":"七言古诗","c":["蟾辉兔影十分满。"]},{"t":"失调名","f":"词","c":["一寸柔肠，如丝千结，不奈愁如铁。"]},{"t":"失调名","f":"五言古诗","c":["缺月挂檐牙。"]},{"t":"失调名","f":"七言古诗","c":["瘦得脸儿两指大。"]},{"t":"失调名","f":"词","c":["来春高步过南宫，更答取龙头策。"]},{"t":"失调名","f":"七言古诗","c":["恐伊不信是龙头，和书寄与三题草。"]},{"t":"失调名","f":"词","c":["这愁绪、仗他谁。"]},{"t":"失调名","f":"七言古诗","c":["酒入柔肠似泪流。"]},{"t":"失调名","f":"七言古诗","c":["夜寒斗觉罗衣薄。"]},{"t":"失调名","f":"五言古诗","c":["更作句桃符。"]},{"t":"失调名","f":"词","c":["去不远，路无多。"]},{"t":"失调名","f":"五言古诗","c":["那得工夫送。"]},{"t":"失调名 其十四","f":"七言古诗","c":["凤楼帘卷鳌山对。"]},{"t":"失调名 其六 喷饶人词","f":"词","c":["尽啜情一饱，泪珠弹子重揾，背人睡也。"]},{"t":"失调名 其二 巫山云雨歌词","f":"词","c":["便直饶、铁作心肠，也须是泪滴。"]},{"t":"失调名","f":"词","c":["深诚杳隔无疑。"]},{"t":"失调名","f":"词","c":["知他今夜，好好为谁梳洗。"]},{"t":"失调名","f":"七言古诗","c":["满庭箫鼓簇飞球。","丝竿红网总台头。"]},{"t":"失调名 其四","f":"七言古诗","c":["彩缕幡儿花枝小。","凤钗上、轻轻斜袅。"]},{"t":"失调名","f":"词","c":["万户与千门，驱傩鼎沸。"]},{"t":"失调名","f":"词","c":["南楼人未起。","爆竹声闻，应在笙歌里。"]},{"t":"失调名","f":"词","c":["西楼独上等多时。","月团圆、人未归。"]},{"t":"失调名 其二 古岩桂词","f":"七言古诗","c":["岩玉枝头金粟斗。"]},{"t":"失调名","f":"五言古诗","c":["巧画远山眉。"]},{"t":"失调名","f":"七言古诗","c":["语燕飞来绕画梁。"]},{"t":"失调名","f":"词","c":["喜则喜、得入手。","愁则愁、不长久。","忻则忻、我两个斯守。","怕则怕、人来破斗。"]},{"t":"失调名","f":"七言古诗","c":["夜深青女湿微妆。"]},{"t":"失调名","f":"七言古诗","c":["花开时节连风雨。"]},{"t":"失调名","f":"词","c":["晓日楼头残雪尽。","乍破腊、风传春信。","彩燕丝鸡，珠幡玉胜，并归钗鬓。"]},{"t":"失调名","f":"词","c":["恨江南塞北，鱼沈雁杳，空肠断、书难寄。"]},{"t":"失调名","f":"词","c":["妙手庖人，搓得细如麻线。","面儿白、心下黑，身长行短。","蓦地下来后，吓出一身冷汗。","这一场欢会，早危如累卵。","便做羊肉燥子，勃推饤碗。","终不似、引盘美满。","舞万遍。","无心看。","愁听弦管。","收盘盏。","寸肠暗断。"]},{"t":"失调名","f":"词","c":["待醉里小王，书写副、神荼郁垒。"]},{"t":"失调名","f":"词","c":["一庭影浸梧竹。"]},{"t":"失调名","f":"词","c":["玉泉清洁，正好浮瓜沈李。"]},{"t":"失调名","f":"词","c":["谁道酒能消恨。"]},{"t":"卜算子","f":"词","c":["和尚性好耍，贪恋一枝花。","见说醉归明月夜，滋味难禁价。","金帛宁论价，毒手遭他下。","料想从今难更也，空惹傍人话。"]},{"t":"失调名","f":"七言古诗","c":["东君去后花无主。"]},{"t":"失调名","f":"七言古诗","c":["五花心里看抛球。","香腮红嫩柳烟稠。"]},{"t":"失调名","f":"词","c":["插黄花、对尊前，且看茱萸好。"]},{"t":"失调名","f":"五言古诗","c":["自家无好况。"]},{"t":"失调名 其十七","f":"五言古诗","c":["卷上珠帘光。"]},{"t":"失调名","f":"五言古诗","c":["无计奈愁何。"]},{"t":"失调名","f":"词","c":["盻盻秋波。"]},{"t":"失调名","f":"五言古诗","c":["夜深帘幕静，一曲管弦清。"]},{"t":"失调名","f":"词","c":["要解心头愁闷，除非殢酒。"]},{"t":"失调名","f":"词","c":["黄叶无风自落，彩云不雨空归。"]},{"t":"失调名 其十二","f":"五言古诗","c":["醉乡天广大。"]},{"t":"失调名","f":"七言古诗","c":["便是监商孟客儿。"]},{"t":"失调名 休休得也□，云深处、高卧斜阳 又","f":"词","c":["单于若问君家世，说与教知。","便是红窗迥底儿。"]},{"t":"失调名","f":"七言古诗","c":["杏花著雨胭脂透。"]},{"t":"失调名","f":"七言古诗","c":["恩爱顿成离别恨。"]},{"t":"失调名","f":"词","c":["春光悭涩，风颠雨恶，未放晴天气。"]},{"t":"失调名","f":"七言古诗","c":["枕上偷垂泪眼流。"]},{"t":"失调名","f":"词","c":["频拭脸边新泪。"]},{"t":"失调名","f":"词","c":["竹爆当门庭，震门陛也。"]},{"t":"失调名","f":"七言古诗","c":["欲折花枝斜插鬓。"]},{"t":"鹊桥仙 其二 琵琶行大曲","f":"词","c":["别有暗愁深意。"]},{"t":"失调名","f":"词","c":["三生春梦。"]},{"t":"失调名","f":"词","c":["枝头点检，退尽芳菲。"]},{"t":"失调名 其十九","f":"七言古诗","c":["一种相思两地愁。"]},{"t":"失调名","f":"七言古诗","c":["郎马频嘶竟不来。"]},{"t":"失调名","f":"词","c":["花底倾杯，花影娇随人醉。"]},{"t":"失调名","f":"五言古诗","c":["燕子引雏飞。"]},{"t":"失调名","f":"七言古诗","c":["频歌覆手抛将过，两行人待看回筹。"]},{"t":"失调名","f":"五言古诗","c":["蹙损两眉峰。"]},{"t":"失调名","f":"词","c":["香阁寂寥。"]},{"t":"失调名","f":"词","c":["鸳鸯鸥鹭，浴乱一池春碧。"]},{"t":"失调名","f":"七言古诗","c":["添憔悴、看肌瘦损。"]},{"t":"失调名","f":"词","c":["断肠屈曲屏山。"]},{"t":"失调名","f":"七言古诗","c":["落花狼藉无行处。"]},{"t":"失调名","f":"词","c":["往来与月为俦，舒展和天也蔽。"]},{"t":"失调名","f":"词","c":["蝶意蜂情，恣还飘逸。"]},{"t":"失调名","f":"七言古诗","c":["倚遍阑干十二楼。"]},{"t":"失调名","f":"词","c":["问醉吟今夜，何处凤楼偏好。"]},{"t":"失调名","f":"词","c":["灯火楼高，移下一天星斗。"]},{"t":"失调名","f":"七言古诗","c":["敧枕无眠又无寐。"]},{"t":"失调名","f":"五言古诗","c":["千里伤行客。"]},{"t":"失调名","f":"七言古诗","c":["清歌叠鼓连催促，这里不让第三头。"]},{"t":"失调名","f":"词","c":["华宫瑶馆游毕。","却返绛节、回鸾翼。","荷殷勤、三斝香醪，供养我、上真仙客。","赤霭浮空，祥云远布，是我来时节。","且频修，同泛舸、上云秋碧。"]},{"t":"失调名 其二 古赏芳春词","f":"七言古诗","c":["樱桃新荐小梅红。"]},{"t":"失调名","f":"词","c":["晓风吹人，酒醒时候。"]},{"t":"失调名 其一 咏纸钱谑词","f":"词","c":["你自平生行短，不公正、欺物瞒心。","交年夜、将烧毁，犹自昧神明。","若还替得，你可知好里，争奈无凭。","我虽然无口，肚里清醒。","除非阎家大伯，一时间、批判昏沈。","休痴呵，临时恐怕，各自要安身。"]},{"t":"头盏曲","f":"词","c":["黄阁方开。","金鼎和羹正待梅。"]},{"t":"归田乐","f":"词","c":["水绕溪桥绿。","泛苹汀、步迷花曲。","衣巾散馀馥。","种竹更洗竹。","咏竹题竹。","日暮无人伴幽独。","光阴双转毂。","可惜许、等闲愁万斛。","世间种种，只是荣和辱。","念足又愿足。","意足心足。","忘了眉头怎生蹙。"]},{"t":"归自谣","f":"词","c":["愁冉冉。","目送书空鸿数点。","落霞风剪江分染。","胜处屏云犹未掩。","羞娥敛。","红潮怕上春风脸。"]},{"t":"归朝欢 寿监丞四月初十","f":"词","c":["才鼓虞弦薰早入。","昴日三分今恰一。","清和时节天气佳，绿树莺簧巧调律。","祥云舒好色。","瑞气珑葱满籯室。","又争知、长庚叶梦，太白生今夕。","快上星辰听履舄。","州县劳人空役役。","暂辞朱皂养冲和，绿野堂延蓬岛客。","华筵倾玉液。","难老细听歌永锡。","寿何其，松椿不数，自可齐箕翼。"]},{"t":"扑蝴蝶","f":"词","c":["烟条雨叶，绿遍江南岸。","思归倦客，寻芳来较晚。","岫边红日初斜，陌上飞花正满。","凄凉数声羌管。","怨春短。","玉人应在，明月楼中画眉懒。","蛮笺锦字，多时鱼雁断。","恨随去水东流，事与行云共远。","罗衾旧香犹暖。"]},{"t":"八年神宗灵驾发引四首 其四 永裕陵歌","f":"词","c":["升龙德，当位富春秋。","受天球。","膺骏命，玉帛走诸侯。","宝阁珠楼临上苑，百卉弄春柔。","隐约瀛洲。","旦旦想宸游。","那知羽驾忽难留。","八马入丹邱。","哀仗出神州。","笳声凝咽，旌旗去悠悠。","碧山头。","真人地，龟洛奥，凤台幽。","绕伊流。","嵩峰冈势结蛟虬。","皇堂一闭威颜杳，寒雾带天愁。","守陵嫔御，想像奉龙辀。","牙盘赭案肃神休。","何日觌云裘。","红泪滴衣褠。","那堪风点缀、柏城秋。"]},{"t":"永遇乐","f":"词","c":["功名闲事，利禄休问，莫系心上。","幸有衣食，随缘过得，著甚乾劳攘。","风前月下，三杯两盏，撞著即莫与放。","且与个、山庄道友，退闲故人来往。","新来做得，一个宽袖布衫，著来也畅。","出户迎宾，入城干事，恰似王保长。","我咱忺后，神歌鬼舞，任尔万般毁谤。","死来后，一家一个，那底怎向。"]},{"t":"永遇乐 寿族兄正月初六，与定光佛同日生","f":"词","c":["柏颂才过，梅妆方试，六秀蓂荚。","恰是今朝，白花岩里，一佛生时节。","前身再现，金城桃熟，千岁莲花重发。","更一念、善根常在，作个在家菩萨。","活饥好事，造桥阴骘，乐施常开金穴。","瑶籍儿孙，玉京夫妇，庆聚神仙窟。","从今生旦，三千纪算，常对昙华优钵。","华严会，彩箱庆满僧宝骨。"]},{"t":"永遇乐 寄所思新第者","f":"词","c":["孤衾不暖，静闻银漏，敧枕难稳。","细想多情，多才多貌，总是多愁本。","而今幽会难成，佳期顿阻，只恁萦方寸。","知他莫是，今生共伊，此欢无分。","寻思断肠肠断，珠泪揾了，依前重揾。","终待临岐，分明说与，我这厌厌闷。","得伊知后，教人成病。","万种断也无限。","只恐他、恁不分晓，谩劳瘦损。"]},{"t":"永遇乐 其二","f":"词","c":["万法由心，应观法界，一切心造。","老子瞿昙，同归去揆，不离心是道。","自从识得，坎离交济，炼药粗知昏晓。","云腾雨飞，蟾宫兔走，丹阙更无烦恼。","气中真液，液中真气，和合不多不少。","种出黄芽，炼成赤水，龙虎交围绕。","七返九还，工夫到后，还我旧时年少。","待三千、功圆行满，恁时是了。"]},{"t":"永遇乐 其三","f":"词","c":["学道修心，存神炼性，直要轻举。","补脑还精，流水不腐，户枢终不蠹。","日魂月魄，抟归炉鼎，真气自然流聚。","把心猿缚住，意马追回，迥无尘虑。","定中明有，阳龙阴火，水火透时为度。","八段奇文，千口活法，向上有一路。","吕公高尚，未离人世，有分也须相遇。","约十洲三岛，骖鸾跨鹤，大家同去。"]},{"t":"永遇乐 庆李守正月十九","f":"词","c":["才过元宵，又经四日，门设弧矢。","信道长庚，当年降瑞，缘是诞生李。","葱葱佳气，今朝重见，洋溢门庭多喜。","这英贤、文章冠世，取青拾芥难比。","那堪绿鬓、朱颜年少，暂试牛刀百里。","迤逦黄堂，平章风月，见说清如水。","彩庭兰玉，森然挺特，捧献椒觞归美。","愿从今、增崇福寿，川流山峙。"]},{"t":"汉宫春","f":"词","c":["争似我，随时临风对月，畅饮更高歌。"]},{"t":"汉宫春 其四","f":"词","c":["雪打风摧。","正篱枯壁尽，却有寒梅。","衰柳败蒲碍眼，喜见芳蕾。","江村路曲，问青帘、与酌馀醅。","须凭取，东君为我，一枝先寄春来。","寂寞槿门牛巷，有清香自倚，不怕低回。","终须会逢赏目，健步移栽。","孤芳素艳，敢烦他、蜂蝶相陪。","偏爱有、春风靳惜，同时不放花开。"]},{"t":"汉宫春 其三","f":"词","c":["点点江梅，对寒威强出，一弄新奇。","零珠碎玉，为谁密上南枝。","幽香冷艳，纵孤高、却遣谁知。","惟只有、江头驿畔，征鞍独为迟迟。","聊捻粉香重问，问春来甚日，春去何时。","移将院落，算应未肯头低。","无人共折，傍溪桥、雪压霜欺。","君不见、长安陌上，只夸桃李芳菲。"]},{"t":"汉宫春 其三","f":"词","c":["梅萼知春，见南枝向暖，一朵初芳。","冰清玉丽，自然赋得幽香。","烟庭水榭，更无花、争染春光。","休谩说、桃夭杏冶，年年蝶闹蜂忙。","立马伫、凝情久，念美人自别，鳞羽茫茫。","临岐记伊，尚带宿酒残妆。","云疏雨阔，怎知人、千里思量。","除是托、多情驿使，殷勤折寄仙乡。"]},{"t":"汉宫春 其二","f":"词","c":["玉减香销，被婵娟误我，临镜妆慵。","无聊强开强解，蹙破眉峰。","凭高望远，但断肠、残月初钟。","须信道，承恩在貌，如何教妾为容。","风暖鸟声和碎，更日高院静，花影重重。","愁来待只殢酒，酒困愁浓。","长门怨感，恨无金、买赋临邛。","翻动念，年年女伴，越溪共采芙蓉。"]},{"t":"汉宫春 庆寡妇二月十九","f":"词","c":["四舞阶蓂，花朝节后，二月阳春。","观音降诞，当年对此良辰。","谁知好日，固多同、重现前身。","已壮门楣全四德，富将偕老卿卿。","天意不如人愿，坚柏舟节义，安富尊荣。","徐君两雏，戏彩歌舞莱庭。","勤教子、不厌三迁，何异轲亲。","福寿麻姑伴侣，长笑傲武陵春。"]},{"t":"汉宫春 其一","f":"词","c":["江月初圆，正新春夜永，灯市行乐。","芙蕖万朵，向晚为谁开却。","层楼画阁。","尽卷上、东风帘幕。","罗绮拥，欢声和气，惊破柳梢梅萼。","绰约。","暗尘浮动，正鱼龙曼衍，戏车交作。","高牙影里，缓控玉羁金络。","铅华间错。","更一部、笙歌围著。","香散处，厌厌醉听，南楼画角。"]},{"t":"汉宫春慢/汉宫春","f":"词","c":["春日迟迟。","称游人、尽日赏燕芳菲。","新荷泛水，渐入夏景云奇。","炎光易息，又早是、零落风西。","白露点，黄金菊蕊，朝云暮雪霏霏。","光阴迅速如飞。","邀酒朋共欢，且恁开眉。","清歌妙舞，更兼玉管瑶篪。","人生易老，遇太平、且乐嬉嬉。","莫待解，朱颜顿觉，年来不似当时。"]},{"t":"玉交枝/忆秦娥 其三","f":"词","c":["谁道花房采蜜脾。","剪成黄蜡小花儿。","恶嫌朱粉，不肯肖青枝。","檀吐暗香兰许韵，月移芳影雪生肌。","不妨花蕊，羌笛尽教吹。"]},{"t":"玉交枝/忆秦娥 其二 腊梅","f":"词","c":["蕙子兰孙小样儿。","化工簇就寄南枝。","笑他兰蕙，虽韵带轻肥。","香霭紫檀和雾重，色攒黄蜡界金徽。","有人潇洒，插向鬓边宜。"]},{"t":"玉交枝/忆秦娥 其一","f":"词","c":["胆样瓶儿几点春。","剪来犹带水云痕。","且移孤冷，相伴最深樽。","每为惜花无晓夜，教人甚处不销魂。","为君惆怅，独自倚黄昏。"]},{"t":"玉抱肚","f":"词","c":["园林草木，迤逦凋残。"]},{"t":"玉珑璁","f":"词","c":["城南路。","桥南路。","玉钩帘卷香横雾。","新相识。","旧相识。","浅颦低拍，嫩红轻碧。","惜惜惜。","刘郎去。","阮郎住。","为云为雨朝还暮。","心相忆。","空相忆。","露荷心性，柳花踪迹。","得得得。"]},{"t":"应天长 寿监岳","f":"词","c":["养高梓里，袖手珍祠，太平五福人物。","自是昔年，场屋文章旧豪杰。","诗书平生事业。","问造物、为谁悭惜。","谩眷怀、兰玉桂香，已露消息。","尝试问、天公好事，鼎来家庆自因袭。","更看绶蓝森列，映灵椿双碧。","诸郎击鲜奏食。","笑贾陆、一更十日。","画堂上，鹤算延长，兕觥无极。"]},{"t":"玉梅香慢","f":"词","c":["寒色犹高，春力尚怯。","微律先催梅拆。","晓日轻烘，清风烦触，凝散数枝残雪。","嫩英妒粉，嗟素艳、有蜂蝶。","全似人人，向我依然，顿成离缺。","裴回寸肠万结。","又因花、暗成凝咽。","捻蕊怜香，不禁恨深难绝。","若是芳心解语，应共把、此情细细说。","泪满阑干，无言强折。"]},{"t":"玉楼人","f":"词","c":["去年寻处曾持酒。","还是向、南枝见后。","宜霜宜雪精神，没些儿、风味减旧。","先春似与群芳斗。","暗度香、不待频嗅。","有人笑折归来，玉纤长、尽露罗袖。"]},{"t":"玉楼春 其三 蜡梅","f":"七言律诗","c":["腊前先报东君信。","清似龙涎香得润。","黄轻不肯整齐开，比着红梅仍旧韵。","纤枝瘦绿天生嫩。","可惜轻寒摧挫损。","刘郎只解误桃花，怅恨今年春又尽。"]},{"t":"玉楼春 贺生双子","f":"词","c":["天上双星欢迤逦。","报道一门双喜。","果庆双弧矢，双桂连芳，双璧光华起。","看取他时双彩戏。","双堕号、机云才子。","更带横双玉，鱼佩双金，作个无双字。"]},{"t":"玉楼春 其一","f":"七言律诗","c":["迢递前村深雪里。","望断行云香细细。","笛中宫里慕芳姿，怨曲啼妆长见泪。","不会同心荣落易。","冷艳翻随分岭水。","有谁曾念陇头人，远寄江南春日意。"]},{"t":"玉楼春 铅山驿壁","f":"七言律诗","c":["东风杨柳门前路。","毕竟雕鞍留不住。","柔情胜似岭头云，别泪多如花上雨。","青楼画幕无重数。","听得楼边车马去。","若将眉黛染情深，且到丹青难画处。"]},{"t":"玉楼春 其二","f":"七言律诗","c":["萧萧海上风长起。","也有梅花开玉蕊。","爱君风措莹如冰，伴我情怀清似水。","诗人纵复工难拟。","莫把闲花容易比。","浓香吹尽不须愁，细雨微风催结子。"]},{"t":"玉楼春 子寿母","f":"七言律诗","c":["戏彩堂高无溽暑。","满座风生闻笑语。","慈闱今日庆生申，歌遏行云香篆缕。","万事从今休挂虑。","儿辈行当壮门户。","一杯祝寿比庄椿，愿长与、儿孙作主。"]},{"t":"玉楼春 寿太守十月十九","f":"七言律诗","c":["姑苏台上春光泄。","菊老寒轻香未歇。","人言太守是龚黄，天为吾君生稷契。","明良庆会俱良月。","万岁千秋同瑞节。","明朝仙领趣持鳌，十万人家齐卧辙。"]},{"t":"甘露滴乔松","f":"词","c":["沙堤露近，喜五年相遇，朱颜依旧。","尽道名世半千，公望三九。","是今日、富民侯。","早生聚、考堂户口。","谁欤兼致，文章燕许，歌辞苏柳。","更饶万卷图书，把藤笈芸编，遍题青镂。","一经传得，旧事韦平先后。","试衮衮、数英游。","问好事、如今能否。","曲车正满，自酌太和春酒。"]},{"t":"生查子 九月廿一","f":"五言律诗","c":["才生申十日，便小春时候。","硕果已含生，一缕微阳透。","贞固见天机，寿脉滋培厚。","菊后早梅前，不尽长生酒。"]},{"t":"生查子 闺情","f":"五言律诗","c":["闲倚曲屏风，试写相思字。","不道极多情，却是浑无思。","笑近短墙阴，抛个青梅子。","苔上印钩弯，邂逅难忘此。"]},{"t":"生查子","f":"五言律诗","c":["朔风吹冻云，云破天容碧。","新月过溪来，隐见横云色。","天与水争妍，花与月争白。","一倩管城君，寄此春消息。"]},{"t":"买坡塘/摸鱼儿 和李玉田韵","f":"词","c":["喜西风、朝来如约，新凉一雨初霁。","家山望断知何处，渺渺长天秋水。","空眼底。","叹雁杳鱼沈，尺纸无人寄。","芸窗草砌。","渐影颤疏桐，声敲落叶，孤枕怎成睡。","逢场戏。","遮莫悲秋憔悴。","今朝有酒须醉。","尊前待唤佳人道，为雪藕丝轻脆。","闲省记。","便笑口频开，一岁知能几。","归期尚未。","且蜡屐兰桡，湖山深处，同赏月中桂。"]},{"t":"伊州曲","f":"词","c":["金鸡障下胡雏戏。","乐极祸来，渔阳兵起。","鸾舆幸蜀，玉环缢死。","马嵬坡下尘滓。","夜对行宫皓月，恨最恨、春风桃李。","洪都方士。","念君萦系。","妃子。","蓬莱殿里。","觅寻太真，宫中睡起。","遥谢君意。","泪流琼脸，梨花带雨，仿佛霓裳初试。","寄钿合、共金钗，私言徒尔。","在天愿为、比翼同飞。","居地应为、连理双枝。","天长与地久，唯此恨无已。"]},{"t":"嘉祐元年四曲 其二 合宫歌","f":"词","c":["泰阶平。","勋业属全盛。","旰昃焦劳，访道缵三朝仁政。","大庭蒇事款上灵。","服冕执圭，侑飨尊累圣。","豆笾奕奕嘉靖。","神光四照百礼成。","回御天门。","讲丕彝，敷大庆。","蒙被草木，万国仰声明。"]},{"t":"嘉祐七年四曲 其二 合宫歌","f":"词","c":["太平时。","宝殿垂衣治。","驭左右贤俊，万国执玉助祭。","凉秋九月霜华飞。","感发纯孝，五室配上帝。","紫汉入夜凝霁。","房心下，泛华芝。","大田栖粮，岁功成，农歌沸。","复道躬拜，肃迎神嬉。","漏声迟。","玉磬响，递清吹。","嘉荐升雕俎，柘桨屡酌几醉。","云扶灵驾欻若归。","天意留顾，万福如山委。","便御丹阙，布为皇泽，与民熙熙。","远观唐虞，未有如兹盛礼。","愿常遇鸣銮，三岁亲祠。"]},{"t":"多丽 寿临江通判","f":"词","c":["近中秋，迥然玉宇澄鲜。","更尧蓂、十有一叶，向人特敷妍。","喜名家、世行阴德，有馀庆、门拥祥烟。","梦协熊罴，间生鸑鷟，妙年攀桂振青毡。","横飞上，金闺粉署，小试佐临川。","翩然返，一身似叶，琳馆清闲。","记榜下、曩尝附骥，浪萍还有夤缘。","曳长裾、不辞远道，接漫刺、复面同年。","邂逅佳辰，铺排雅席，金炉香袅欲何言。","愿趣诏、入扶宗社，浩气愈纯全。","长年少，龟龄共永，鹤算同坚。"]},{"t":"好事近","f":"词","c":["小院看酴醾，正是盛开时节。","莫惜大家沈醉，有春醅初泼。","花前月下细看来，无物比清绝。","若问此花何似，似一堆香雪。"]},{"t":"好事近","f":"词","c":["潇洒小楼东，斜亚一枝梅雪。","若在玉溪仙馆，更风流奇绝。","花神应为护芳心，付与何人折。","行客几回搔首，认暗香浮月。"]},{"t":"好事近 其一 咏梅","f":"词","c":["篱落晓来霜，花嫩不禁寒力。","脉脉自摇疏影，印一奁空碧。","天生潇洒谢夫人，绝世有谁识。","何必嫣然一笑，已倾城倾国。"]},{"t":"好事近 寿郭宪","f":"词","c":["春信到梅梢，欲雪又还晴早。","趁得绣衣初度，作霜天清晓。","乡来事直有天知，行拜玉皇诏。","稳上神仙官府，听履声云杪。"]},{"t":"好事近 寿章宰四月十六","f":"词","c":["记紫极真人，前日是他生日。","颍水有兹风骨，弥诞当今夕。","等闲来现宰官身，任凫飞双舄。","治狱阴功多少，是长生妙术。"]},{"t":"好事近","f":"五言古诗","c":["更一声啼鸟。"]},{"t":"好事近 庆母寿子中举八月二十","f":"词","c":["王母庆生辰，方过中秋五日。","子舍文场鏖战，想功名来逼。","看看喜德捷音传，果信名登桂籍。","行拜君恩爵赏，寿萱堂永锡。"]},{"t":"如梦令","f":"词","c":["今夜荼风起。","应是玉消琼碎。","淡荡满城春，恼破愁人春睡。","须醉。","须醉。","莫待梅黄雨细。"]},{"t":"如梦令 佳人","f":"词","c":["韵似江梅标致。","美似江梅多丽。","清似腊梅香，白似雪梅香腻，非是。","非是。","我道梅花似你。"]},{"t":"如梦令","f":"词","c":["莺嘴啄花红溜。","燕尾点波绿皱。","指冷玉笙寒，吹彻小梅春透。","依旧。","依旧。","人与绿杨俱瘦。"]},{"t":"如梦令 留客","f":"词","c":["试问春归何处。","红入小桃花树。","同访古章台，把盏重听金缕。","休去。","休去。","应被好山留住。"]},{"t":"如意令 寿王学老八月廿一","f":"词","c":["久羡庞眉鹤发。","闻望孔堂煊赫。","信得彭乔仙，秘授长生真诀。","奇特。","奇特。","吕望师周时节。","才过中秋六日。","对此称觞欣怿。","双凤戏莱衣，金缕轻调莺舌。","难得。","难得。","九九算犹千百。"]},{"t":"如意令 寿新恩人六月廿二","f":"词","c":["炎暑尚馀八日。","火老金柔时节。","闻道间生贤，储秀降神崧极。","无敌。","无敌。","当代人伦准的。","射策当为第一。","高跃龙门三级。","荣著绿袍新，帝渥必加宠锡。","良弼。","良弼。","真个国家柱石。"]},{"t":"安平乐/安平乐慢","f":"词","c":["开琼筵，庆佳辰。","彩帟当中月华明。","笙歌乐、如梦幻，望丹山彩凤，飞舞邃庭。","遐艳异、寿杯同斟。","抃舞讴歌浃欢声。","方今永永太平。","更衍多男，共集锦昌寿恩。"]},{"t":"寻梅","f":"词","c":["幽香浅浅湿未透。","认雪底、思来始有。","剪裁尚觉琼瑶皱。","苦寒中、越恁骨清肌瘦。","东风气象园林旧。","又去年、而今时候。","急宜小摘当尊酒。","选一枝、且付玉人纤手。"]},{"t":"导引 宣祖昭宪皇后御容赴奉先禅院奉安嘉祐五年","f":"词","c":["于皇祖烈，大宋启鸿名。","骏命属炎灵。","閟宫厚德太阴精。","重华诞圣明。","轩台百世护基扃。","龙驾在清冥。","汉家原庙崇新饰，鼎业永安宁。"]},{"t":"景献太子薨导引一首","f":"词","c":["霜月苦、宫鼓冬冬。","霓旐启、鹤闱空。","洞箫声断知何处，海山依约五云东。","玉符龙节参神閟，昭圣眷、惨天容。","千古恨无穷。","遍山松柏撼悲风。"]},{"t":"神主祔庙导引一首","f":"词","c":["中兴四叶，休德继昭清。","王度日熙平。","气调玉烛金穰应，八表颂声腾。","中原图籍入宸廷。","列圣慰真灵。","衮龙登庙游仙阙，亿万载尊承。"]},{"t":"熙宁二年宗英御容赴西京会 圣宫应天禅院奉安导引一首","f":"词","c":["九清三境，飙驭杳难追。","功烈并巍巍。","洛都不及西巡到，犹识睟容归。","三条驰道隐金槌。","仙仗共逶迤。","珠宫绀宇申严奉，亿载固皇基。"]},{"t":"恭上寿圣皇太后至尊寿圣皇帝 寿成皇后尊号册宝导引一首","f":"词","c":["皇家盛事，三殿庆重重。","圣主极推崇。","瑶编宝列相辉映，归美意何穷。","钧韶九奏度春风。","彩仗焕仪容。","欢声和气弥寰宇，皇寿与天同。"]},{"t":"神主祔庙道宫导引","f":"词","c":["紫鸾飞去，玉殿锁坤宁，珠箔俨银屏。","仙家不似人间世，无处觅云軿。","金铺肃肃湛严扃，天册下彤庭。","嘉觞好在新宫荐，万世妥神灵。"]},{"t":"景灵宫奉安神御三首 其二 显仁皇后导引","f":"词","c":["坤仪厚载，遗德满寰中。","归御广寒宫。","玉容如在飙舆远，长乐起悲风。","霓旌绛节下层空。","云阙晓曈昽。","真游千载安原庙，圣孝与天通。"]},{"t":"仁宗神主祔庙 嘉祐八年 导引","f":"词","c":["九虞初毕，黼座掩瑶觞。","羽卫盛煌煌。","数声清跸来天上，想像赭袍光。","新成清庙勖云堂。","孝飨奉蒸尝。","子孙千载承丕绪，景福介无疆。"]},{"t":"导引 明德章德皇后御容赴普安禅院奉安嘉祐六年","f":"词","c":["母仪天宇，彤史蔼遗芳。","纡馀庆气固灵长。","基祚寝明昌。","重华大孝奉蒸尝。","原庙閟灵光。","采章褕翟严新饰，歆愿福穰穰。"]},{"t":"导引 其一","f":"词","c":["宝图熙盛，登格圣功全。","瑞命集灵篇。","钦修祀典成明察，道祖降云軿。","赖乡真馆宅真仙。","朝谒帝心虔。","尊崇教父膺鸿福，绵互万斯年。"]},{"t":"天禧三年南郊鼓吹歌曲三曲 其一 导引","f":"词","c":["皇穹锡瑞，帝业愈蕃昌。","会万玉来王。","名山珍馆神游接，实信降云房。","卜兹显位严坛墠，奕奕睹辉光。","精衷昭格灵心答，天历保无疆。","皇家立极，炎德赫中区。","执契应萝图。","文章焕烂垂星斗，威略定方隅。","丹扉翠巘锡灵符。","瑞物纪神输。","紫坛大报陈昭配，福庆降清都。"]},{"t":"虞主回京四首 其一 仪仗导引","f":"词","c":["龙舆春晚，晓日转三川。","鼓吹惨寒烟。","清明过后落花天。","望池馆依然。","东风百宝泛楼船。","共荐寿当年。","如今又到苑西边。","但魂断香軿。"]},{"t":"嘉祐元年四曲 其一 导引","f":"词","c":["龙驰驾，玉辂俨宸威。","天仗下端闱。","华旌翠羽笼黄道，赫奕照晨晖。","大哉仁孝逾尧舜，圭瓒罄虔祗。","神灵肸蚃来歆答，万寿保纯禧。"]},{"t":"导引 太祖皇帝","f":"词","c":["元符锡命，祗受庆诚明。","恭馆法三清。","开基盛烈垂无极，金像俨天成。","奉迎霞布甘泉仗，箫瑟振和声。","灵辰协吉鸿仪毕，万国保隆平。"]},{"t":"庄文太子薨导引一首","f":"词","c":["秋月冷、秋鹤无声。","清禁晓、动皇情。","玉笙忽断今何在，不知谁报玉楼成。","七星授辔骖鸾种，人不见、恨难平。","何以返霓旌。","一天风露苦凄清。"]},{"t":"奉祀太清宫三首 其一 导引","f":"词","c":["穹旻锡祐，盛德日章明。","见地平天成。","垂衣恭己干戈偃，亿载祐黎氓。","羽旄饰驾当春候，款谒届殊庭。","精衷昭感膺多福，夷夏保咸宁。","圣君御宇，祗翼奉三灵。","已偃革休兵。","区中海外鸿禧浃，恭馆励虔诚。","九斿七萃著声明。","徯后徇舆情。","丕图宝绪承繁祉，率土仰隆平。"]},{"t":"虞主祔庙仪仗内导引一首","f":"词","c":["轻舆小辇，曾宴玉栏秋。","庆赏殿宸游。","伤心处，兽香散尽，一夜入丹邱。","翠帘人静月光浮。","但半卷银钩。","谁知道，桂华今夜，却照鹊台幽。"]},{"t":"嘉祐七年四曲 其一 导引","f":"词","c":["帝皇盛烈，教孝谨民常。","严父位明堂。","管丝金石含天韵，笾豆荐芬芳。","肃然音响灵来下，容与动祥光。","四方内外交欣喜，饮福万年觞。"]},{"t":"加上太上皇帝太上 皇后册宝导引一首","f":"词","c":["皇家多庆，亲寿与天长。","德业播辉光。","焜煌宝册来清禁，玉篆映金相。","庭闱尊奉会明昌。","佳气溢康庄。","洪禧申辑名增衍，亿载颂无疆。"]},{"t":"景灵宫奉安神御三首 其一 徽宗皇帝导引","f":"词","c":["中兴复古，孝治日昭鸿。","原庙饰瑰宫。","金壁千门磻万磶，楹桷竞穹崇。","亭童芝盖拥旌龙。","列圣俨相从。","共锡神孙千万寿，龟鼎亘衡嵩。"]},{"t":"奉宝册导引三首 其二 景灵宫","f":"词","c":["明明道祖，金阙冠仙真。","清禁降飙轮。","遥源始悟垂鸿庆，亿兆耸群伦。","虔崇徽号盛仪陈。","宝册奉良辰。","邦家亿载蒙繁祉，圣寿保无垠。"]},{"t":"虞主赴德寿宫导引一首","f":"词","c":["上皇天大，华旦焕尧文。","鸿福浩无垠。","羽龙俄驾灵輴去，空锁鼎湖云。","稽山翠拥浙江濆。","归旆卷缤纷。","仙游指日严升祔，万载颂高勋。"]},{"t":"虞主回京四首 其一 导引","f":"词","c":["上林寒早，仙仗转郊圻。","笳鼓入云悲。","逶迤辇路过西池。","楼阁锁参差。","都人瞻望意如疑。","犹想翠华归。","玉京传信杳无期。","空掩赭黄衣。"]},{"t":"亲耕籍田四首 其一 导引","f":"词","c":["春融日暖，四野瑞烟浮。","柳菀更桑柔。","土膏脉起条风扇，宿雪润田畴。","金根毂转如雷动，羽卫拥貔貅。","扶携老稚康衢满，延跂望凝旒。","斗移星转，一气又环周。","六府要时修。","务农重谷人胥劝，耕籍礼殊尤。","坛壝岳峙文明地，黛耜驾青牛。","雍容南亩三推了，玉趾更迟留。"]},{"t":"导引 三圣御容赴滁并澶州奉安皇祐五年","f":"词","c":["穆清冲境，金阙秘寥阳。","二后侍虚皇。","真人恭默钦先烈，肖象启琳房。","岿然神物护灵光。","玉色粹逾彰。","虎旌龙节辉前后，馆御镇无疆。"]},{"t":"导引 诣泰山","f":"词","c":["我皇缵位，覆焘合穹旻。","秘箓示灵文。","齐居紫殿膺玄贶，降宝命氤氲。","奉符让德事严禋。","检玉陟天孙。","垂鸿纪号光前古，迈八九为君。","灵台偃武，书轨庆同文。","奄六合居尊。","圆穹锡命垂真箓，清晓降金门。","升中报本禅云云。","严祀事惟寅。","无为致治臻清净，见反朴还淳。"]},{"t":"高宗祀大礼鼓吹歌曲五首 其一 导引","f":"词","c":["圣皇巡狩，清跸驻三吴。","十世嗣瑶图。","边尘不动干戈戢，文德溥天敷。","灰飞缇室气潜嘘。","郊见紫坛初。","归来赦令楼前下，喜气溢寰区。"]},{"t":"五年景灵宫神御殿 成奉迎导引一首","f":"词","c":["新宫翼翼，钜丽冠神京。","金虬蟠绣楹。","都人瞻望洪纷处，陆海涌蓬瀛。","仙舆缥缈下圆清。","彩仗拥天行。","熉黄珠幄承灵德，锡羡永升平。"]},{"t":"导引 神主祔庙","f":"词","c":["岁华婉娩，侍宴玉皇宫。","雕辇出房中。","岂知轩后丹成去，望绝鼎湖龙。","寿原初掩九虞终。","归跸五云重。","惟馀宝册书鸿烈，清庙配三宗。"]},{"t":"庄献明肃皇后恭谢太庙 其一 导引","f":"词","c":["母仪天下，圣祚保延长。","声教被遐方。","严恭孝飨来清庙，鸾辂历康庄。","箫韶九奏凤来翔。","袆翟焕祥光。","惟馨蕊醴奠瑶觞。","万寿永无疆。","亲承先顾，保祐助吾皇。","亿载正乾纲。","宗文祖武尊邦社，天下锡蕃昌。","六宫扈从亲重翟，清庙荐萧芗。","礼行乐备神祗飨，四海永来王。"]},{"t":"天圣二年南郊鼓吹歌曲三曲 其一 导引","f":"词","c":["真人临御，实瑞集丰融。","万国仰天聪。","嘉禋盛礼文章焕，齐洁致清衷。","笙镛六变三神格，喜备盛仪容。","乾穹上达昭灵飨，庆绪蔼丕隆。","阳郊报本，礼意弥勤禋。","太一下威神。","天临两观推三赦，庆祉被臣民。","徽名荐册缛仪陈。","盛节焕书筠。","涂歌邑诵扬徽懿，鼎命协惟新。"]},{"t":"八年神宗灵驾发引四首 其一 导引","f":"词","c":["金殿晚，注目望宫车。","忽听受遗书。","白云缥缈帝乡去，抱弓空慕龙湖。","瑶津风物胜蓬壶。","春色至、望雕舆。","花飞人寂寂，凄凉一梦清都。"]},{"t":"加上寿圣皇太后尊号册宝导引一首","f":"词","c":["重亲万寿，八帙衍新元。","礼典备文孙。","温温和气迎长日，宝册焕瑶琨。","徽音显号自尧门。","德行已该存。","更期昌算齐箕翼，愈久愈崇尊。"]},{"t":"四年英宗御容赴景灵宫奉安导引一首","f":"词","c":["鼎湖龙去，仙仗隔蓬莱。","辇路已苍苔。","汉家原庙临清渭，还泣玉衣来。","凤箫鸾扇共徘徊。","帐殿倚云开。","春风不向天袍动，空绕翠舆回。"]},{"t":"治平二年南郊鼓吹歌曲四曲 其一 导引","f":"词","c":["治平天子，景至肇严禋。","华玉礼威神。","六龙齐捧銮舆动，采仗转钩陈。","归来瑞气满清晨。","金石舜韶新。","楼前山鹤衔书下，天地已为春。"]},{"t":"导引 熙宁十年南郊皇帝归 青城用降仙台一首","f":"词","c":["清都未晓，万乘并驾，煌煌拥天行。","祥风散瑞霭，华盖耸，旗常建，耀层城。","四列兵卫，爟火映、金支翠旌。","众乐警、作充宫庭。","皦绎成。","绀幄掀，衮冕明。","妥帖坛陛霄升。","振珩璜、神格至诚。","云车下冥冥。","储祥降嘏莫可名。","御端阙、肸号敷荣。","泽翔施溥，茂祉均被含生。"]},{"t":"明堂 其一 导引","f":"词","c":["膺乾兴运，辰火正心房。","宗祀继文王。","典容希阔成昭备，彬郁亶晖光。","因心崇孝申郊侑，内外罄斋庄。","神灵欢嘉昌绵瓞，受福介无疆。"]},{"t":"导引 别庙","f":"词","c":["蓬莱邃馆金碧照三山。","真境胜人间。","秋风又见芭蕉长，遗迹在人寰。","云轩一去杳难攀。","斑竹彩舆还。","深宫旧监闻箫鼓，怅望惨朱颜。"]},{"t":"章献明肃皇后章懿皇后升祔 导引 其一 庆历五年二曲","f":"词","c":["受遗仍几，负扆拥文明。","勤翼助持盈。","徽音不独流笙管，青册更峥嵘。","羽軿上汉玉衣轻。","隙驷去无程。","宸心追远严成配，亿世乡粢盛。"]},{"t":"导引 真宗加上谥号册宝 庆历七年","f":"词","c":["圣真下武，淳烈缉丕隆。","绝瑞与天通。","封山育谷声名举，仙驭邈轩龙。","腾金篆玉显成功。","业业承垂鸿。","惟皇孝述光前志，保祐福来同。"]},{"t":"奉宝册导引三首 其三 太庙","f":"词","c":["祖宗垂佑，亨会协重熙。","德泽被烝黎。","虔崇尊谥陈徽册，藻卫列葳蕤。","宸心致孝极孜孜。","展礼诏台司。","祥烟瑞霭浮清庙，绵宇被纯禧。"]},{"t":"景灵西宫坤元殿奉安钦 导引 成皇后御容","f":"词","c":["云軿芝盖，仙路去难攀。","海浪溅三山。","重迎遗像临驰道，还似在人间。","西宫瑶殿指坤元。","璇榜耸飞鸾。","移升宝殿从新诏，盛典永流传。"]},{"t":"导引 圣祖天尊","f":"词","c":["至真降鉴，飙驭下皇闱。","清漏正依依。","范金肖像申严奉，仙馆壮翚飞。","万灵拱卫瑞烟披。","岸柳映黄麾。","九清祚圣鸿基永，尧德更巍巍。"]},{"t":"导引 其四 太宗皇帝","f":"词","c":["膺乾抚运，垂庆洽重熙。","元圣嗣鸿基。","发挥宝绪灵仙降，感吉梦先期。","良金璀璨范真仪。","精意答蕃厘。","閟宫神馆崇严配，万祀播葳蕤。"]},{"t":"显仁皇后神主祔太庙导引一首 道宫","f":"词","c":["返虞长乐，犹是忆宾天。","何事驾仙軿。","箫笳仪卫辞宫阙，移仗入云烟。","于皇清庙敞华筵。","昭穆谨承先。","千秋长奉烝尝孝，永享中兴年。"]},{"t":"章惠皇太后神主赴西京导引一首","f":"词","c":["祥符盛际，二鄙正休兵。","瑞应满寰瀛。","东封西祀鸣銮辂，从幸见升平。","仙游一去上三清。","庙食享隆名。","寝园松柏秋风起，箫吹想平生。"]},{"t":"导引 其四 太祖皇帝","f":"词","c":["乘云英圣，千载仰皇灵。","垂法蔼朝经。","禹金熔范肖仪刑。","日角焕珠庭。","琳宫翠殿凤文屏。","迎奉庆安宁。","孝思瞻谒荐惟馨。","诚悫贯青冥。"]},{"t":"奉宝册导引三首 其一 玉清昭应宫","f":"词","c":["太霄垂佑，绵宇洽祺祥。","秘检焕云章。","宸心虔奉崇徽号，茂典迈前王。","霞明藻卫列通庄。","宝册奉琳房。","都人震抃腾谣颂，亿载保欢康。"]},{"t":"祔庙导引一首","f":"词","c":["虞觞奉主，仙驭返皇宫。","礼典极钦崇。","云旗前导开清庙，龙管咽薰风。","巍巍尧父告神功。","追慕孝诚通。","千秋万岁中兴统，宗祀与天同。"]},{"t":"庆元六年光宗皇帝导引一首","f":"词","c":["笳鼓发、云惨寒空。","丹旐去、卷悲风。","忧勤六载亲几务，有巍巍、圣德仁功。","褰裳尊处大安宫。","荆鼎就、遽遗弓。","仙游攀不及，臣民号恸诉苍穹。"]},{"t":"导引 其一 玉皇大帝","f":"词","c":["先天气祖，魄宝御中宸。","列位冠高真。","绿符锡瑞昭元圣，宝历亘千春。","琳宫壮丽俯严闉。","璇碧照龙津。","珍金铸像灵仪睟，集福庇蒸民。"]},{"t":"安穆皇后导引一首","f":"词","c":["凤箫声断，缥缈溯丹邱。","犹是忆河洲。","荧煌宝册来天上，何处访仙游。","葱葱郁郁瑞光浮。","嘉酌侑芳羞。","雕舆绣幰归新庙，百世与千秋。"]},{"t":"导引 太祖皇帝","f":"词","c":["石文应瑞，真主御寰瀛。","慈俭抚群生。","巍巍威德超千古，大业保盈成。","神皋福地开恭馆，灵贶日昭明。","铸金九牧天仪睟，绀殿矗千楹。"]},{"t":"导引 太宗元德皇后御容赴启圣院奉安至和二年","f":"词","c":["宝图全盛，端拱信巍巍。","声教暨华夷。","辰髦尽入英雄彀，齐筑太平基。","仙舆前指玉霄归。","夹道九鸾飞。","真宫秘殿严崇奉，圣治永无为。"]},{"t":"导引 三圣御容赴南京鸿庆宫 庆历七年","f":"词","c":["炎精凿乾，正统膺瑶历。","万宇归神德。","以圣继圣三后，光声明、扬典则。","天清日润莹玉泽。","华殿辉金碧。","宸心思孝仙驭，三灵休、绥万亿。"]},{"t":"导引 太祖孝明皇后御容赴太平兴国寺开先殿奉安至和二年","f":"词","c":["刬除霸轨，穆穆照皇明。","大统一寰瀛。","穷湖绝塞人安业，武库遂销兵。","仙游昔日上三清。","极望紫云平。","珠宫宝坐严崇奉，圣祚永绥宁。"]},{"t":"导引 神主祔别庙","f":"词","c":["柔容懿范，蚤岁蔼层闱。","兰梦结芳时。","秋风一夜惊罗幕，鸾扇影空回。","荣追袆翟盛威仪。","遗像掩瑶扉。","春来只有芭蕉叶，依旧倚晴晖。"]},{"t":"钦宗皇帝导引一首 道宫","f":"词","c":["鼎湖龙远，九祭毕嘉觞。","遥望白云乡。","箫笳凄咽离天阙，千仗俨成行。","圣神昭穆盛重光。","宝室万年藏。","皇心追慕思无极，孝飨奉烝尝。"]},{"t":"导引 其一 诣玉清昭应宫","f":"词","c":["紫霄金阙，重叠降元符。","亿兆祚皇图。","云章焜耀傅温玉，宝阁起清都。","奉迎彩仗溢天衢。","观者竟欢呼。","明君钦翼承鸿阴，亿载御中区。"]},{"t":"宝庆三年奉上宁宗徽号导引一首","f":"词","c":["中兴五叶，天子肇明禋。","一德格高旻。","宁皇至圣功超古，万国慕深仁。","徽称显号又还新。","功德粲雕珉。","乾坤绘画终难尽，遗泽在斯民。"]},{"t":"政和三年追册明达皇后导引一首","f":"词","c":["来嫔初载，令德冠层城。","柔范蔼徽声。","熊罴梦应芳兰郁，佳气拥雕楹。","珠宫缥缈泛蓬瀛。","脱屣世缘轻。","空馀宝册光琼玖，千古仰鸿名。"]},{"t":"导引 圣祖天尊","f":"词","c":["仙宗灵祖，御气降中宸。","孚宥庆维新。","国工熔范成金像，仪炳动威神。","玉虚圣境绝纤尘。","欢忭洽群伦。","导迎云驾归琳馆，恭肃奉高真。"]},{"t":"仁宗御空赴景灵宫奉安 治平二年 导引","f":"词","c":["彤霞缥缈，海上隐三山。","仙去莫能攀。","珠宫本是神灵宅，飙驭此来还。","云边天日望威颜。","不似在人间。","当时齐鲁鸣鸾处，稽首泪潺湲。"]},{"t":"景灵宫奉安神御三首 其三 钦宗皇帝导引","f":"词","c":["深仁厚德，流泽自无穷。","仙驭倏宾空。","衣冠未返苍梧远，遥望鼎湖龙。","人间仿佛认天容。","缥缈五云中。","帝城犹有遗民在，垂泪向西风。"]},{"t":"南郊恭谢三首 其一 导引","f":"词","c":["重熙累盛，睿化畅真风。","尊祖奉高穹。","林棼彩仗明初日，瑞气满晴空。","玉銮徐动出环宫。","虔巩罄宸衷。","礼成均庆人神悦，圣寿保无穷。"]},{"t":"籍田明道二年四曲 其一 导引","f":"词","c":["绵区浃宇，三万里封疆。","躬稼穑重光。","神宗昔举殊尤礼，今复睹吾皇。","先农祀罢东郊晓，玉趾染游场。","三推初毕公卿遍，从此万斯箱。","务农敦本。","自古属明王。","方册布彝章。","吾皇睿圣躬千亩，将欲积神仓。","去年宿雪田膏极，黛耜应农祥。","尧郊击壤迎归辂，解雨遍遐荒。"]},{"t":"导引 诣南郊","f":"词","c":["圣神缵绪，赫奕帝图昌。","宝箓降穹苍。","宸心励翼修郊报，彩仗列康庄。","祥烟瑞霭杂天香。","筦磬发声长。","升坛礼毕膺繁祉，睿算保无疆。"]},{"t":"真宗封禅四首 其四 告庙导引","f":"词","c":["明明我后，至德合高穹。","祗翼励精衷。","上真紫殿回飙驭，示圣胄延鸿。","躬承宝训表钦崇。","庆泽布寰中。","告虔备物朝清庙，荷景福来同。"]},{"t":"宁宗皇帝发引三首 其一 导引","f":"词","c":["三弄晓、云黯天低。","攀六引、转悲凄。","俭慈孝哲钟天性，深仁厚泽遍群黎。","东西南北傒商霓。","功甫就、别宸闺。","臣民千古恨，几时羽卫带潮归。"]},{"t":"双头莲令 其一 祫享太庙","f":"词","c":["天仪安豫洽无为。","九域被雍熙。","鸾刀亲割升圭瓒，清庙展孝思。","箫韶九变皇灵格，嘏告显深慈。","精诚动感归能飨，福祚衍金枝。"]},{"t":"神御奉安导引一首","f":"词","c":["龟书畀姒，历数在皇躬。","揖逊仰高风。","鼎湖龙去遗弓堕，冠剑锁深宫。","涂山齐德翊成功。","仙魄蚤宾空。","珍台闲馆栖神地，献飨永无穷。"]},{"t":"元丰二年慈圣光献皇后发引四首 其一 仪仗内导引","f":"词","c":["驾斑龙。","忽催金母转仙仗、去瑶宫。","绛阙深沈杳无踪。","渐尘空。","丝网琼林，花似怨东风。","垂清露啼红。","犹想旧春中。","献万寿、宝船空。"]},{"t":"淳熙十六年高宗神 御奉安导引一首","f":"词","c":["中兴揖逊，功德仰兼隆。","仁泽被华戎。","鼎湖俄痛遗弓堕，日日想威容。","柔仪懿范与尧同。","飙驭俨相从。","灵宫真馆偕来燕，垂裕永无穷。"]},{"t":"导引 三圣御空万寿观奉安皇祐五年","f":"词","c":["万灵昭瑞，天地赞昌期。","宝运协开基。","巍巍烈圣无疆德，神化洽重熙。","虔思出驾罄彰施。","岁暮俨神宜。","云舆迎奉依珍馆，塞外焕朝仪。"]},{"t":"真宗封禅四首 其一 导引","f":"词","c":["民康俗阜，万国乐升平。","庆海晏河清。","唐尧禹舜垂衣化，讵比我皇明。","九天宝命垂丕贶，云物效祥英。","星罗羽卫登乔岳，亲告禅云亭。","我皇垂拱，惠化洽文明。","盛礼庆重行。","登封降禅燔柴毕，天仗入神京。","云雷布泽遍寰瀛。","遐迩振欢声。","巍巍圣寿南山固，千载贺承平。"]},{"t":"中太一宫奉安神像导引一首","f":"词","c":["九霄仙驭，四纪乐西清。","游衍遍黄庭。","云軿万里归真室，上应泰阶平。","金舆玉像下瑶京。","彩仗拥霓旌。","天人感会千年运，福祚永昌明。"]},{"t":"治平四年英宗祔庙导引一首","f":"词","c":["寿原初掩，归跸九虞终。","仙驭更无踪。","思皇攀慕追来孝，作庙继三宗。","旌旗居外拥千重。","延望想威容。","宝舆迎引归新殿，奏享备钦崇。"]},{"t":"安恭皇后上仙发引三首 其一 黄钟羽导引","f":"词","c":["金殿晚、愁结坤宁。","天下母、忽仙升。","云山浩浩归何处，但闻空际彩鸾声。","紫箫断后无踪迹，烟霭霭，夜澄澄。","晓梦到瑶城。","当时花木正冥冥。"]},{"t":"亳州回诣玉清昭应宫一首 导引","f":"词","c":["秘文镂玉，金阁奉安时。","旌盖俨仙仪。","珠旒俯拜陈章奏，精意达希夷。","卿云郁郁曜晨曦。","玉羽拂华枝。","灵心报贶垂繁祉，宝祚永隆熙。"]},{"t":"显仁皇后上同发引三首 其一 导引","f":"词","c":["长乐晚彩戏莱衣。","奄忽梦报仙期。","帝乡渺渺乘鸾去，啼红嫔御不胜悲。","苍梧烟水杳难追。","肠断处、过江时。","银涛千万叠，不知何处是瑶池。"]},{"t":"导引 其二 玉皇大帝","f":"词","c":["太霄玉帝，总御冠灵真。","威德耸天人。","宝文瑞命符皇运，绵远庆维新。","洞开霞馆法虚晨。","八景降飙轮。","含生普洽□鸿福，圣寿比仙椿。"]},{"t":"慈孝寺彰德殿迁章献明肃皇后御容 赴景灵宫衍庆殿奉安导引一首","f":"词","c":["九清云杳，飙驭邈难追。","功化盛当时。","保扶仁圣成嘉靖，彤管载音徽。","天都左界抗华榱。","仙仗下逶迤。","宝楹黼帐承神贶，万寿永无期。"]},{"t":"亲享太庙一首 导引","f":"词","c":["躬朝太室，列圣大功宣。","彩仗耀甘泉。","秘文升辂空歌发，一路覆祥烟。","珠旒荐献极精虔。","列侍俨貂蝉。","穰穰降福均寰宇，垂拱万斯年。"]},{"t":"庆千秋 正月十七","f":"词","c":["点检尧蓂，自元宵过了，两荚初飞。","葱葱郁郁佳气，喜溢庭闱。","惟知降、月里姮娥，欣对良时。","但见婺星腾瑞彩，年年辉映南箕。","好是庭阶兰玉，伴一枝丹桂，戏舞莱衣。","椒觞迭将捧献，歌曲吟诗。","如王母、款对群仙，同宴瑶池。","萱草茂长春不老，百千祝寿无期。"]},{"t":"庆灵椿/摊破南乡子 夫人生日","f":"词","c":["瑞溪庭，满闺秋色好，帘幕低垂。","一床簪笏人间盛，沉檀影里，笙歌沸处，齐捧瑶卮。","习礼复明诗。","胡氏清畏人知。","寿堂已庆灵椿老，年年岁岁，重添嫩叶，频长繁枝。"]},{"t":"庆金枝","f":"词","c":["新春入旧年，绽梅萼、一枝先。","陇头人待信音传。","算楚岸、未香残。","小枕风雪凭栏干。","下帘幕、护轻寒。","年华永占入芳筵。","付尊前、渐成欢。"]},{"t":"庆金枝令/庆金枝","f":"词","c":["莫惜金缕衣。","劝君惜、少年时。","花开堪折直须折，莫待折空枝。","一朝杜宇才鸣后，便从此、歇芳菲。","有花有酒且开眉。","莫待满头丝。"]},{"t":"庆青春","f":"七言古诗","c":["平明一阵催花雨。"]},{"t":"庆春泽","f":"词","c":["晓风严，正萧然兔园，薄雾微罩。","梅渐弄白，耸危苞、匀胜胭脂，半点琼瑰小。","望江南、信息何杳。","纵寿阳妍姿，学就新妆，暗香须少。","幽艳满寒梢，更游蜂舞蝶，浑无飞绕。","天赋品格，借东皇施巧。","孤根占得春前俊，笑雪霜、谩欺容貌。","况此花高强，终待和羹，肯饶芳草。"]},{"t":"庆清朝","f":"词","c":["银漏花残，红消烛泪。","九重鱼钥欢声沸。","奏万乘、祥曦门外。","盖圣君、恭谢灵休，谨访景明嘉礼。","天意好，祥风瑞月，时正当、小春天气。","禁街十里香中，御辇万红影里。","千官花底，控绣勒、宝鞭摇曳。","看万年，永庆吾皇，拈指又瞻三载。"]},{"t":"庆清朝 寿知县三月廿四","f":"词","c":["节过重三，日逢四六，真贤应昴初生。","元来鼻祖，降瑞应长庚。","今喜重逢旧事，固宜依旧复青毡。","果然是、双雕一箭，雁塔书名。","大器也须小试，鸾凤暂栖，荆棘若为荣。","从容钜竹双松，足畅吟情。","行种河阳桃李，即飞诏、入厕朝绅。","从兹看、箕星上应，南极长明。"]},{"t":"庆清朝 寿章丞二月初六","f":"词","c":["点检尧阶，蓂生六叶，春深桃杏花开。","长庚入梦，重新产谪仙才。","事业十年灯火，文章笔下若掀雷。","果然是，两字功名，唾手拿来。","又况当年强仕，得志青云路，足慰高怀。","紫泥凤诏，行须非次招徕。","金马玉堂风月，从容九棘面三槐。","从今看，会唐九老，它日云台。"]},{"t":"庆清朝","f":"词","c":["北陆严凝，东郊料峭，化工争付归期。","前村夜来雪里，先见纤枝。","想像靓妆淡伫，钗头翡翠茧蛾儿。","冰壶莹，坐间静对，姑射仙姿。","潇洒处，非艳冶最奇。","是名赋、处士新诗。","尊前坐曲，忍听羌管频吹。","试问占先众卉，微笑不奈苦寒欺。","何须问，定应未羡，桃李芳菲。"]},{"t":"庆清朝 寿吴宪六月初三","f":"词","c":["朏月生西，杓星建未，画堂昼景偏长。","天生英杰，独向此炎光。","超卓凡尘表物，精神秋水自清凉。","真奇特，清沟挺秀，敌国传芳。","好是少年折桂，唾手功名就，腾踏飞黄。","君王眷厚，皇华绣斧还乡。","士贵姜谟盛事，未容专美独夸唐。","称觞处，颂闽境、斑戏公堂。"]},{"t":"扫地舞","f":"词","c":["酥点萼。","玉碾萼。","点时碾时香雪薄。","才折得。","春方弱。","半掩朱扉，垂绣幕。","怕吹落。","捻一饷。","嗅一饷。","捻时嗅时宿酒忘。","春争上。","不忍放。","待对菱花，斜插向。","宝钗上。"]},{"t":"早梅芳 雪梅","f":"词","c":["冰唯清，玉唯润。","清润无风韵。","此花风韵，自然清润传香粉。","故应春意别，不使凡英恨。","到春前腊后，长是寄芳信。","此情闲，此意远。","一点萦方寸。","风亭水馆，解与行人破离恨。","广寒宫未有，姑射仙曾认。","向雪中月下，吟未尽。"]},{"t":"早梅香","f":"词","c":["北帝收威，又探得早梅，漏春消息。","粉蕊琼苞，拟将胭脂，轻染颜色。","素质盈盈，终不许、雪霜欺得。","奈化工、偏宜赋与，寿阳妆饰。","独自逞冰姿，比夭桃繁杏，迥然殊别。","为报山翁，逢此有花，樽前须攀折。","醉赏吟恋，莫辜负、好天风月。","恐笛声悲，纷纷便似，乱飞香雪。"]},{"t":"江城梅花引 其二 和赵制机赋梅","f":"词","c":["逋仙千载独知心。","别无人。","泪痕深。","长是自开自落自成阴。","白石后来疏影句，饶绮丽，总输他、清浅吟。","伤情。","伤情。","角中声。","夜沉沉。","更捣砧。","欲雪未雪、天欲老，云气昏昏。","梦绕西湖路渐不堪行。","人已骑驴毡笠去，留恨也，仗梅花、说与君。"]},{"t":"江神子/江城子 其二 寿监镇十一月廿七","f":"词","c":["一阳来复气回新。","对芳辰。","庆生申。","月满惟迟、三日又三旬。","入仕致身知是早，年弱冠，正青春。","文章笔下扫千军。","擢铨衡。","袭簪缨。","荣捧宸恩，来镇此邦民。","行历华途须煊赫，添寿酒，祝椿龄。"]},{"t":"百字令","f":"词","c":["自天钟秀，看人物谁与、君家为比。","椿桂相辉年少日，事业文章如此。","玉殿诗书，金瓯姓字，简记宸衷里。","有三株桂，一时归耀桑梓。","我愿寿祝南山，尊空北海，不获陪珠履。","惟有瓣香心起敬，敢颂鲁侯燕喜。","大厦万间，金城千里，国计如家计。","日边有诏，苍生端望公起。"]},{"t":"百字谣/念奴娇 贺人娶姑女","f":"词","c":["太真姑女，问新来、谁与欢传玉镜。","莫恨无人伸好语，人在蓝桥仙境。","一笑樽前，欢然相与，便胜琼浆饮。","殷勤客意，耳边说与君听。","长记旧日君家，门阑喜动，绣褥芙蓉隐。","回首龙门人得意，又报凤楼芳信。","只是相传，房奁中物，好事骎骎近。","管教人道，一双冰玉清润。"]},{"t":"百字谣/念奴娇 叔庆侄生子","f":"词","c":["金秋行令，恰清晨、白露初交中节。","勿怪西窗传好事，生个他年英杰。","吉梦既符，知如徐子，冰玉为神骨。","吾家有庆，阶兰喜又新发。","如今早已生男，清樽华宴，且好延佳客。","更自承师勤问道，门外不妨立雪。","抗志云霄，留心简册，听我叮咛说。","骎骎月殿，桂枝取次高折。"]},{"t":"百字谣/念奴娇 二月初四","f":"词","c":["中和节后，云翳净、向夕新蟾飞出，月姊传声，明日是、紫府神仙诞节。","彩系麒麟，瑞腾嵩岳，喜气交洋溢。","魁星头上，光芒仍露消息。","好是一鹗秋风，鞭云驾雾，去作龙门客。","看取长安花夹道，人在广寒宫阙。","春酒千钟，秋娘一曲，大醉豪无敌。","八千椿算，摩挲重见铜狄。"]},{"t":"百字歌 寿父子同日八月廿五","f":"词","c":["蓂飞十荚，觉九分秋色，六分将极。","桂子风高时更好，天产英贤同日。","桥梓齐芳，一慈一孝，奋建真奇特。","称觞华旦，但将老少分别。","且看戏彩堂前，酒须双献，饮侍严君侧。","清赏阿戎防跨灶，大小欧阳相敌。","疏曰贤哉，古云有是，作个家家声烈。","无先无后，寿齐延应□翼。"]},{"t":"百字歌 寿张提干六月廿三","f":"词","c":["乾坤孕秀，正人间六月，下弦时节。","生此清奇潇洒客，秋水精神玉骨。","才吐天芳，毫挥月颖，更彬彬文质。","图南得志，抟风高展鹏翼。","好是大器难淹，暂陪庾使，赞画光原隰。","台省即须登衮衮，黄阁平章有日。","崔室称觞，莱庭戏彩，中外欢声溢。","祝君延寿，箕星上应南极。"]},{"t":"百字歌 庆潭帅兼平寇六月十四","f":"词","c":["庚金入伏，细推来、明日又还三五。","见说帅垣佳气蔼，天降崧神生甫。","礼乐词章，甲兵韬略，素备文兼武。","称觞华旦，颂声交赞台府。","好是比启元戎，剿除逋寇，不许奸偷侮。","有此奇功高渤海，足慰湖湘生聚。","暂统十连，折冲万里，行即驱残虏。","九重环召，万年永佐天子。"]},{"t":"百宝妆/新雁过妆楼","f":"词","c":["一抹弦器，初宴画堂，琵琶人把当头。","髻云腰素，仍占绝风流。","轻拢慢捻，生情艳态，翠眉黛颦，无愁谩似愁。","变新声曲，自成获索，共听一奏梁州。","弹到遍急敲颖，分明似语，争知指面纤柔。","坐中无语，惟断续金虬。","曲终暗会王孙意，转步莲、徐徐卸凤钩。","捧瑶觞，为喜知音，劝佳人、沉醉迟留。"]},{"t":"红窗迥","f":"词","c":["富春坊，好景致。","两岸尽是、歌姬舞妓。","引调得、上界神仙，把凡心都起。","内有丙丁并壬癸。","这两尊神，为你争些口气。","火星道，我待逞些神通，不怕你是水。"]},{"t":"红窗迥","f":"词","c":["河可挽。","石可转。","那一个愁字，却难驱遣。","眉向酒边暂展。","酒后依旧见。","枫叶满阶红万片。","待拾来、一一题写教遍。","却倩霜风吹卷。","直到沙岛远。"]},{"t":"行香子","f":"词","c":["清要无因，举选艰辛。","系书钱、须要十分。","浮名浮利，虚苦劳神。","叹旅中愁，心中闷，部中身。","虽抱文章，苦苦推寻。","更休说、谁假谁真。","不如归去，作个齐民。","免一回来，一回讨，一回论。"]},{"t":"行香子","f":"词","c":["浙右华亭。","物价廉平。","一道会、卖个三升。","打开瓶后，滑辣光馨。","教君霎时饮，霎时醉，霎时醒。","听得渊明。","说与刘伶。","这一瓶、约迭三斤。","君还不信，把秤来秤。","有一斤酒，一斤水，一斤瓶。"]},{"t":"行香子慢","f":"词","c":["瑞景光融。","换中天霁烟、佳气葱葱。","皇居崇壮丽，金碧辉空。","彤霄外、瑶殿深处，帘卷花影重重。","迎步辇、几簇真仙，贺庆寿新宫。","方逢。","圣主飞龙。","正休盛大宁，朝野欢同。","何妨宴赏，奉宸意慈容。","韶音按、露觞将进，蕙炉飘馥香浓。","长愿承颜，千秋万岁，明月清风。"]},{"t":"西地锦 其二","f":"词","c":["岭上初消残雪。","有梅花先坼。","东君造化多成翠，巧风韵奇绝。","小院黄昏时节。","暗香浮、疏影横斜。","寄取和羹未晚，却免教攀折。"]},{"t":"西地锦 其一","f":"词","c":["不与群花相续。","独占春光速。","幽香远远散西东，惟竹篱茅屋。","羌管谁调一曲。","送月夜、犹芬馥。","凭君折取向玉堂，只这些清福。"]},{"t":"西地锦 章台留客","f":"词","c":["重过黄梁古驿。","著一鞭春色。","长亭细柳，青青尚浅，不禁攀折。","且醉章台风月。","莫归鞍催发。","紫泥诏下，朝天去了，如何来得。"]},{"t":"西江月 即席呈吴节判二首 其十二","f":"词","c":["剪剪轻寒雨后，瞳瞳晓日晴时。","春风先到绿杨枝。","金缕野桥山市。","鶗鴂巧调琴筑，海棠惜吐胭脂。","玉骢未解锦障泥。","且挂征鞭一醉。"]},{"t":"西江月 其十一 雪","f":"词","c":["琼沼融成沆瀣，冰檐滴尽真珠。","一园草木气方苏。","又学杨花飞舞。","何必乱飘密洒，却疑细糁轻铺。","谁将粉墨画成图。","玉做小亭高树。"]},{"t":"西江月 寿六十四","f":"词","c":["葭管一阳已复，蓂阶五叶还留。","星瞻南极瑞光浮。","知是降生时候。","算衍恰侔周卦，福多更协箕畴。","绿衣戏舞捧琼舟。","满劝长生寿酒。"]},{"t":"西江月 其二 赠术士","f":"词","c":["身禀五行正气，此心如鉴光明。","不从龟鹤问年龄。","万物有衰有盛。","多谢道人著眼，我于身世常轻。","任从性巧与心灵，此事从来分定。"]},{"t":"西江月 庆赵宰季修","f":"词","c":["一派先天妙学，十年克己工夫。","割鸡聊此宰中都。","人在春台鼓舞。","昏垫非由已溺，拊摩不异予辜。","万家香火祝悬弧。","我亦无多颂语。"]},{"t":"西江月 其七 待雪","f":"词","c":["扑扑云垂四野，冥冥雁下平芜。","萧萧风叶乱黄芦。","寒入一滩鸥鹭。","准拟云窗水榭，装成玉树冰壶。","卷帘独坐拈髭须。","待看六花飞舞。"]},{"t":"西江月 二月廿三","f":"词","c":["蓂褪尧阶八叶，桃翻禹浪三层。","欢传崧岳挺生申。","儿女团栾争庆。","名注长生仙籍，未须仰祝龟龄。","芳联子舍早蜚声。","富贵荣华鼎盛。"]},{"t":"西江月 其一 寿苗摆铺","f":"词","c":["一夕凉浮如水，崧高瑞世生贤。","朅来闲伴幔亭仙。","行副九天隆眷。","数万范公兵甲，三千李白诗篇。","兜鍪元许换貂蝉。","好把平戎策献。"]},{"t":"西江月 为妻寿七月卅日","f":"词","c":["伴我鹿车鱼釜，从伊裙布钗荆。","年年七月甫三旬，今日生朝资庆。","二女长俱麻绩，三男俱读书声。","吾年五十不多争，好事且宜少等。"]},{"t":"西江月","f":"词","c":["早晚以成行色，主人莫与留延。","正当春月艳阳天。","去赛从前心愿。","执状去呈仙尉，殷勤早与周旋。","不辞客路往来难，暂辍舞裙歌扇。"]},{"t":"西江月 寿刘公子十月初西","f":"词","c":["良月才经四日，彭城庆诞真贤。","从来斗酒百诗篇。","锦绣文章灿烂。","自合宰官身现，谁知富贵由天。","但教福寿喜双全。","直看子孙荣显。"]},{"t":"西江月 寿黄帅干六月十九","f":"词","c":["隆暑正当三伏，明朝又是双旬。","崧高孕秀降生申。","再捧瑶觞称庆。","督府赞猷英俊，难淹大展经纶。","倚需召入秉洪钧。","上佐万年明圣。"]},{"t":"西江月 其一 待雪","f":"词","c":["膝下红金不暖，窗前绛蜡犹然。","夜深城麓走风烟。","的砾还飘雪霰。","海上正迷蝶梦，山阴未棹溪船。","愿骑白凤玉为鞭。","西赴瑶池芳宴。"]},{"t":"西江月 贺生第二子","f":"词","c":["积玉堆金闲事，惊天动地虚名。","算来二足是人生，有子方为吉庆。","莫道一夔足矣，也须学著徐卿。","我翁休笑又添丁。","这个孩儿好命。"]},{"t":"西江月 贺人女中秋日满月","f":"词","c":["八月秋中玉律，十分月满瑶台。","芳姿谪下佛宫来。","疑是东方世界。","黛绿旋闻香发，桃红新晕芳腮。","春风满面笑容开。","长似观音自在。"]},{"t":"西江月 寿居士","f":"词","c":["好个马山居士，功名富贵浮云。","庵儿侧傍万杉阴。","烟里时横小艇。","律中林钟将半，华堂寿斝频斟。","声声齐祝百千龄。","坐看云仍贵盛。"]},{"t":"西江月","f":"词","c":["健体安身可美，喜笑化食堪夸。","更言一事实为佳。","肥风瘦痨都罢。","兼且时光似箭，更加景色难赊。","名园等处乐奢华。","一任佳人玩耍。"]},{"t":"西江月 贺人生子","f":"词","c":["绛蜡攒宝炬，碧刍香衬金卮。","东风吹下玉龙儿。","融就满堂和气。","此日兰汤新浴，他年桂苑同携。","小词聊代弄璋诗。","剩与犀钱利市。"]},{"t":"西江月","f":"词","c":["北岭天饶瑞雪，南枝地段红苞。","朦胧霁月映寒梢。","谁把玉人纱罩。","香胜炉薰龙麝，奇过庭拥琼瑶。","一杯清酒愿相招。","慰我茅堂清瘦。"]},{"t":"西江月 其八","f":"词","c":["风雨朝来恶甚，池塘春去无多。","绿杨阴里溜莺梭。","枝上老红犹堕。","酒满蚁浮金匜，烛残泪滴铜荷。","更阑孤枕奈情何。","只恐巫山梦破。"]},{"t":"西江月 其九 冷氏小楼春望","f":"词","c":["花下春光正好，柳边春色才多。","雨声日夜长沧波。","暗地芳心滴破。","拍拍浪飞白雪，冥冥山点青螺。","汀兰岸芷有情么。","还惜江城春过。"]},{"t":"西江月 其十四","f":"词","c":["风雨馀寒过了，池塘春水生时。","迁莺飞上拂云枝。","春遍柳村花市。","酒面清空似水，玉杯温莹如脂。","莫教花谢涴尘泥。","把住东君索醉。"]},{"t":"西江月","f":"词","c":["么六把门已定，二四三五成梁。","须知四六做烟梁。","五六单行无障。","掷得么三采出，填胲此处高强。","到家先起妙无双。","号曰金赢取赏。"]},{"t":"西江月","f":"词","c":["请知诸郡子弟，尽是湖海高朋。","今年神首赛齐云。","别是一般风韵。","来时向前参圣，然后疏上挥名。","香金留下仿花人，必定气球取胜。"]},{"t":"西江月 寿人八十一","f":"词","c":["剧饮犹能鲸吸，细书仍作蝇头。","人间八十最风流。","况又今年九九。","不用蒲轮加璧，不须磻石垂钩。","八千春更八千秋。","但愿灵椿长寿。"]},{"t":"西江月 寿东屏有青在堂","f":"词","c":["几萼红搀桃径，双茎翠舞蓂阶。","小春霏霭瑞蓬莱。","寿旦称觞青在。","牛斗辉腾气概，风云壮入襟怀。","年年鹤发笑颜开。","西爽亭前戏彩。"]},{"t":"西江月 赠友","f":"词","c":["忆昔钱塘话别，十年社燕秋鸿。","今朝忽遇暮云东。","对坐旗亭说梦。","破帽手遮西日，练衣袖卷寒风。","芦花江上两衰翁。","消得几番相送。"]},{"t":"西江月","f":"词","c":["灯火楼台欲下，笙歌院落将归。","冰瓷金缕胜琉璃。","春笋捧来纤细。","饮罢高阳人散，曲终巫峡云飞。","千方修合斗新奇。","须带别离滋味。"]},{"t":"西江月","f":"词","c":["梁上喃喃燕语，纸间戢戢蚕生。","满城风雨近清明。","不道有人新病。","春事一溪流水，杨花千点浮萍。","好风一霎为吹晴。","独步小园清影。"]},{"t":"西江月","f":"词","c":["早岁轻衫短帽，中间圆顶方袍。","忽然天赐降宸毫。","接引私心入道。","可谓一身三教，如今且得逍遥。","擎拳稽首拜云霄。","有分长生不老。"]},{"t":"西江月","f":"词","c":["强调朱粉对菱花。","蹙损眉峰懒画。"]},{"t":"西江月","f":"词","c":["翡翠枝头晚萼，婵娟月里飘香。","春兰秋蕙作寻常。","不与夭桃朋党。","笑见深红浅白，从教蝶舞蜂忙。","风流标致道家妆。","潇洒得来别样。"]},{"t":"西江月 其二 寿周主簿","f":"词","c":["侯绩分从东鲁，世勋来在姬公。","桂枝少日冠蟾宫。","枳棘暂栖鸾凤。","报道小春来也，令辰申降高崧。","功名富贵管无穷。","指日经纶大用。"]},{"t":"西江月 其一 赠画士","f":"词","c":["三级掀腾波浪，一堂庆会风云。","快乘霹雳化龙门。","头角人中有分。","谁状个中佳致，须还笔扫千军。","是他画手亦通神。","同向来春奋迅。"]},{"t":"西江月","f":"词","c":["银烛晓催春漏，珠帘暮卷东风。","乃翁相对玉楼中。","不枉当年冰梦。","花意似随人好，酒香难比情浓。","夜深欲睡海棠红。","密密骖鸾驾凤。"]},{"t":"西江月 十月初三","f":"词","c":["才入冬来三日，人都道小春来。","生生一脉早胚胎。","消息南枝大。","好向腊前冬后，贞元接处滋培。","调羹手段栋梁材。","直待文明嘉会。"]},{"t":"西江月 其六 登城晚望","f":"词","c":["草市人归日落，荒城风急鸦翻。","独携尊酒上高寒。","缥缈云横楚观。","柳外半篙绿水，烟中数笔青山。","天涯流落岁将残。","望断故园心眼。"]},{"t":"西江月 寿中山","f":"词","c":["一片冰霜气概，几多锦绣文章。","鹏抟相踵桂枝香。","盛事争夸歆向。","岁岁蓂敷九叶，喜催一线迎长。","柏松祝处奉霞觞。","事业非熊吕望。"]},{"t":"西江月 其三 蜡梅","f":"词","c":["黄蜡谁将点缀，红膏不许施妆。","孤根来自水云乡。","风味天然酝酿。","看取玉奴呵手，摘来珠露沾裳。","翠鬟斜插一枝香。","似簇蜂儿头上。"]},{"t":"西江月 邮亭壁上词","f":"词","c":["昨夜轺车宿处，乱山深锁邮亭。","烟溪霜叶颤秋声。","不管愁人不听。","枕冷安排难稳，衾寒重叠犹轻。","凭谁说与那人人。","报道衾寒枕冷。"]},{"t":"西江月","f":"词","c":["蹴鞠场中年少，秋千架上佳人。","三三两两趁芳辰。","玩赏风光美景。","日暖风和明媚，更加花草香馨。","红颜移步出闺门，偷揭绣帘相认。"]},{"t":"西江月 其四","f":"词","c":["万木经霜冻折，孤根独报春来。","前村雪里一枝开。","将缓月华光彩。","一点唇红不褪，妆如傅粉皑皑。","和羹端的禀天才。","终入庖人鼎鼐。"]},{"t":"西江月 其十三","f":"词","c":["翠岭游仙梦破，暖香残酒醒时。","子规啼月下花枝。","日涌山光照市。","柳拂眉间黛色，桃匀脸上胭脂。","萋萋芳草路无泥。","脉脉归心似醉。"]},{"t":"西江月慢","f":"词","c":["烟笼细柳，映粉墙、垂丝轻袅。","正岁稍暖律风和，装点后苑台沼。","见乍开、桃若燕脂染，便须信、江南春早。","又数枝、零乱残花，飘满地、未曾扫。","幸到此、芳菲时渐好。","恨间阻、佳期尚杳。","听几声、云里悲鸿，动感怨愁多少。","谩送目、层阁天涯远，甚无人、音书来到。","又只恐、别有深情，盟言忘了。"]},{"t":"阮郎归","f":"词","c":["春风吹雨绕残枝。","落花无可飞。","小池寒渌欲生漪。","雨晴还日西。","帘半卷，燕双归。","讳愁无奈眉。","翻身整顿著残棋。","沈吟应劫迟。"]},{"t":"阮郎归","f":"五言古诗","c":["无心傍照台。"]},{"t":"阮郎归 其一 端五","f":"词","c":["及妆时结薄衫儿。","蒙金艾虎儿。","画罗领抹襭裙儿。","盆莲小景儿。","香袋子，搐钱儿。","胸前一对儿。","绣帘妆罢出来时。","问人宜不宜。"]},{"t":"阮郎归","f":"词","c":["薄罗生色画酴醾。","酴醾满架时。","隔池贪看燕争泥。","坠双红荔支。","销金字，晚唐诗。","夹纱团扇儿。","自遮微雨傍花归。","个情天得知。"]},{"t":"阮郎归 其二 端五","f":"词","c":["门儿高挂艾人儿。","鹅儿粉扑儿。","结儿缀着小符儿。","蛇儿百索儿。","纱帕子，玉环儿。","孩儿画扇儿。","奴儿自是豆娘儿。","今朝正及时。"]},{"t":"齐天乐 寿刘机宜","f":"词","c":["天开图画江山秀。","怪得人间希有。","屏岛精神，潭溪骨格，钟作名门华胄。","满堂昼绣。","甚禊集兰亭，竹修林茂。","得得明朝，绂麟亲解公侯绶。","心胸剩罗列宿。","便能光绍，太常勋旧。","却恋槃湖，贪求精舍，日日佳篇醇酎。","陶朱敌富。","更沧海双珠，掌中明透。","赢得年年，莲龟松鹤祝公寿。"]},{"t":"齐天乐 寿碧涧三月初一","f":"词","c":["百花香里莺声好，晴日暖风天气。","诗境春融，壶天昼永，今日祥开弧矢。","疏帘约翠。","想歌遏行云，暖薰沉水。","羽扇纶巾，寿星因甚降尘世。","那堪流觞节近，一樽相庆处，何用辞醉。","管领溪山，平章风月，从此身心无累。","明年此际。","愿添个孙枝，伴君娱戏。","举案齐眉，更同龟鹤□。"]},{"t":"吴音子","f":"词","c":["早团圆，早早团圆。"]},{"t":"声声令/胜胜令","f":"七言古诗","c":["未怕飞燕似轻盈。"]},{"t":"声声慢","f":"词","c":["心虽相许，事未曾谐。"]},{"t":"声声慢","f":"词","c":["双双旧家燕子，又飞来、清明池阁。"]},{"t":"声声慢","f":"词","c":["梅黄金重，雨细丝轻，园林雾烟如织。","殿阁风微，帘外燕喧莺寂。","池塘彩鸳戏水，雾荷翻、千点珠滴。","闲昼永，称潇湘竿叟，烂柯仙客。","日午槐阴低转，茶瓯罢、清风顿生双腋。","碾玉盘深，朱李静沈寒碧。","朋侪闲歌白雪，卸巾纱、樽俎狼藉。","有皓月、照黄昏，眠又未得。"]},{"t":"寿延长 中腔令","f":"词","c":["彤云映彩色相映，御座中、天簇簪缨。","万花铺锦满高庭。","庆敞需宴欢声。","千龄启统乐功成。","同意贺、元圭丰擎。","宝觞频举侠群英。","万万载、乐升平。"]},{"t":"寿延长破字令","f":"词","c":["青春玉殿和风细。","奏箫韶络绎。","瑞绕行云飘飘曳。","泛金尊、流霞艳溢。","瑞日晖晖临丹扆。","广布慈德宸遐迩。","愿听歌声舞缀。","万万年、仰瞻宴启。"]},{"t":"寿星明 庆黄宰秩满八月廿七","f":"词","c":["玉露迎寒，金风荐冷，正兰桂香。","觉秋光过半，日临三九，葱葱佳气，蔼蔼琴堂。","见说当年，申生谷旦，梦叶长庚天降祥。","文章伯，英声早著，腾踏飞黄。","双凫暂驻东阳。","已种得春阴千种棠。","有无边风月，几多事业，安排青琐，入与平章。","百里民歌，一樽春酒，争劝殷勤称寿觞。","愿此去，龟龄难老，长侍君王。"]},{"t":"尾犯","f":"词","c":["轻风淅淅，正园林萧索，未回暖律。","岭头昨夜，寒梅初发，一枝消息。","香苞渐拆。","天不许、雪霜欺得。","望东吴，驿使西来，为谁折赠春色。","玉莹冰清容质。","迥不同、群花品格。","如晓妆匀罢，寿阳香脸，徐妃粉额。","好把琼英摘。","频醉赏、舞筵歌席。","休待听，呜咽临风，数声月下羌笛。"]},{"t":"应天长 庆新恩母八月三十","f":"词","c":["萱堂积庆，桂苑流芳，于门瑞蔼佳气。","正属仲秋弥月，称觞对此际。","西王母、来人世。","拥佩从、尽皆珠翠。","彩庭下，争看蓝袍，衬斑斓戏。","富贵有谁同，四德躬全，五福由来备。","况善断机迁教，轲亲实无异。","看看仕无淹滞。","即召入、佐君经济。","愿延寿，鸾轴金花，年年加赐。"]},{"t":"快活年","f":"五言古诗","c":["蛩吟声不住。"]},{"t":"折丹桂 七月廿八","f":"七言律诗","c":["初秋两两留蓂荚。","算恰是、生申佳节。","祝君寿阅八千秋，岁岁对、长空皓月。","威宣比部推刚决。","气凛凛、秋霜争烈。","滩头双鶒看飞来，便有诏、催归天阙。"]},{"t":"折红梅 其三","f":"词","c":["忆笙歌筵上，匆匆见了，□□相别。","红炉暖、画帘绣阁，曾共鬓边斜插。","南枝向暖，北槛里、春风犹怯。","也应别后，不减芳菲，念咫尺阑干，甚时重折。","清风间发，如天与浓香，粉匀檀颊。","纱窗影、故人凝处，冷落暮天残雪。","一轩明月。","怅望花争清切。","便教尽放，都不思量，也须有，蓦然上心时节。"]},{"t":"折红梅 其二","f":"词","c":["倚花阑清晓，裴回探得，南枝初绽。","通春意、漏巧斗奇，东君首先回暖。","盈盈素面。","刚强点、胭脂深浅。","是他自有，标格清香，恣千种妖饶，万般闲雅。","移时细看。","算浓雪严霜，怎生拘管。","也拟是、小桃未蕊，依约杏添清伴。","笛声休怨。","怕恐使、群芳零乱。","待须把酒，守著花枝，愿期与花枝，久长相见。"]},{"t":"折红梅 其四","f":"词","c":["睹南翔征雁，疏林败叶，凋霜零乱。","独红梅、自守岁寒，天教最后开绽。","盈盈水畔。","疏影蘸、横斜清浅。","化工似把，深色胭脂，怪姑射冰姿，剩与红间。","谁人宠眷。","待金锁不开，凭阑先看。","曾飞落、寿阳粉额，妆成汉宫传遍。","江南风暖。","春信喜、一枝清远。","对酒便好，折取奇苞，撚清香重嗅，举杯重劝。"]},{"t":"折红梅 其一","f":"词","c":["陇上消残雪，曲水流断，淑气潜通。","群花冷未吐，夜来梅萼，数枝繁红。","光夺化工。","发艳色、不染东风。","信凭晓风，难压精神，占青春未上，别是标容。","天香渐杳，似蓬阙玉妃，酒困娇慵。","只愁恐、上阳爱惜，各种移向瑶宫。","西归驿使，折赠处、庾岭溪东。","又须寄与，多感多情，道此花开早，未识游蜂。"]},{"t":"小抛球乐/抛球乐","f":"七言绝句","c":["两行花窍占风流。","缕金罗带系抛球。","玉纤高指红丝网，大家著意胜头筹。"]},{"t":"水龙吟","f":"词","c":["洞天景色常春，嫩红浅白开轻萼。","琼筵镇起，金炉烟重，香凝锦幄。","窈窕神仙，妙呈歌舞，攀花相约。","彩云月转，朱丝网徐在，语笑抛球乐。","绣袂风翻凤举，转星眸、柳腰柔弱。","头筹得胜，欢声近地，光容约。","满座佳宾，喜听仙乐，交传觥爵。","龙吟欲罢，彩云摇曳，相将归去寥廓。"]},{"t":"抛球乐 折花令 三台词","f":"词","c":["翠幕华筵，相将正是多欢宴。","举舞袖、回旋遍。","罗绮簇宫商，共歌清羡。","当琼浆泛泛满金尊，莫惜沉醉，莫惜沉醉，永日长游衍。","愿乐嘉宾，嘉宾式燕。"]},{"t":"更漏子","f":"词","c":["宝香瓶，桐叶卷。","荡水痕微还远。","思乡信，觉春迟。","野梅初见时。","上潮风，临晚渡。","人欲过西江去。","吹寒管，陇云低。","江南花未知。"]},{"t":"更漏子","f":"词","c":["鬓慵梳，眉懒画。","独自行来花下。","情脉脉，泪垂垂。","此情知为谁。","雨初晴，帘半卷。","两两衔泥新燕。","人比燕，不成双。","枉教人断肠。"]},{"t":"更漏子","f":"词","c":["绛纱笼，金叶盖。","向晓灯花犹在。","冰未结，小琉璃。","陇梅香满枝。","雪无香，花有意。","不是江南新寄。","霜月尽，碧天寒。","玉楼人倚阑。"]},{"t":"杏花天 贺人三兄弟皆娶赵氏","f":"词","c":["弟兄旧说河东凤。","怎得似、君家伯仲。","一双白璧殷勤种。","齐向金屏选中。","乘龙去、门阑喜动。","管取早叶、熊罴吉梦。","儿孙不与尘埃共。","总是龙驹凤种。"]},{"t":"杏花天 贺人女晬","f":"词","c":["画堂帘幕香风细。","郁郁南阳佳气。","欢传吉梦占蛇虺。","此日还当一岁。","华筵外、初随彩戏。","早已似、文姬聪慧。","伫看色动门阑喜。","便有乘龙佳婿。"]},{"t":"杏花天 侄寿姑三月廿七","f":"词","c":["婺星呈瑞，对春馀几许，日临三九。","正属我姑初度旦，帨设当年门右。","绿鬓犹新，红颜未改，真月宫仙友。","柏舟节义，富而荣贵长守。","况有诜桂青春，潜心黄卷，指日功名就。","女郎乘龙全四德，未老得闲仁寿。","天命方知，岁饥常赈，阴德还多有。","麻姑王母，年年同宴春酒。"]},{"t":"杜韦娘","f":"词","c":["华堂深院，霜笼月采生寒晕。","度翠幄、风触梅香喷。","渐岁晚、春光将近。","惹离恨万种，多情易感，欢难聚少愁成阵。","拥红炉，凤枕慵敧，银灯挑尽。","当此际，争忍前期后约，度岁无凭准。","对好景、空积相思恨。","但自觉、恹恹方寸。","拟蛮笺象管，丹青好手，写出寄与伊教信。","尽千工万巧，唯有心期难问。"]},{"t":"添声杨柳枝","f":"词","c":["簌簌花飞一雨残。","乍衣单。","屏风数幅画江山。","水云闲。","别易会难无计那，泪潸潸。","夕阳楼上凭栏干。","望长安。"]},{"t":"极相思","f":"词","c":["一番雨过横塘。"]},{"t":"极相思","f":"词","c":["夕阳外，禽声切。"]},{"t":"五羊仙 步虚子令","f":"词","c":["碧烟笼晓海波闲。","江上数峰寒。","佩环声里，异香飘落人间。","弭绛节、五云端。","宛然共指嘉禾瑞，开一笑、破朱颜。","九重峣阙，望中三祝高天。","万万载、对南山。"]},{"t":"步蟾宫 庆友人四月初四","f":"七言律诗","c":["蓂开四叶祥光发。","又还是、清和时节。","昴星呈瑞夜来明，庆此日、挺生英杰。","少年玉树神清澈。","未说到、龟龄鹤发。","愿言鹗荐早蜚声，任丹桂、一枝高折。"]},{"t":"步蟾宫 庆正月二十一日生又二十一岁及第","f":"词","c":["垂弧门左当今日。","恰过了、元宵六夕。","喜妙龄秀发步蟾宫，信富贵、荣华莫敌。","纪年甲子才三七。","即翰苑、从容西掖。","便从兹、谈笑觅封侯，更管取、寿延千亿。"]},{"t":"沁园春","f":"词","c":["道过江南，泥墙粉壁，石具在前。","述某州某县，某乡某里，住何人地，佃何人田。","气象萧条，生灵憔悴，经略从来未必然。","惟何甚，为官为已，不把人怜。","思量几许山川。","况土地分张又百年。","正西蜀巉岩，云迷鸟道，两淮清野，日警狼烟。","宰相弄权，奸人罔上，谁念干戈未息肩。","掌大地，何须经理，万取千焉。"]},{"t":"沁园春 寿壮寺丞四月十一","f":"词","c":["申伯嵩神，李白长庚，萧何昴精。","恰先公三日，金仙氏降，后公三日，吕洞宾生。","五百仙班，一千佛号，喜听胪声传集英。","君恩重，早升华监寺，扬厉朝廷。","金瓯已覆香名。","正天下苍生须太平。","看黄麻一命，难留五马，蟠桃三熟，会庆千龄。","一尉凄凉，有官守者，莫到公堂称寿觥。","三熏沐，但焚香清夜，遥拜台星。"]},{"t":"沁园春 寿郭宪使","f":"词","c":["阊阖初开，羽葆来从，斗畔天南。","看长身玉立，精神耿耿，风姿冰冷，琼佩珊珊。","政数龚黄，才称屈宋，君合居其伯仲间。","犹堪庆，早恩沾令子，新著朝冠。","东园。","未即开藩。","且乡曲吾曹共往还。","向棋边几见，烂柯樵客，琴中时写，流水高山。","野鹤立阶，灵龟支坐，修竹梅花伴岁寒。","荣华事，有传家从橐，立上清班。"]},{"t":"沁园春 其二 寿朱佥判，以鹤为寿","f":"词","c":["有鹤东来，鸣而向余，借篇寿词。","道临皋亭下，坡仙曾梦，锦宫城里，清献常携。","山斗才名，冰霜节操，苏赵如今重见之。","生申旦，正菊花开后，橙子黄时。","自从枳棘鸾栖。","何尚泛芙蓉绿水池。","便来归西掖，坐看红药，也应天禄，书照青藜。","顾我鸡群，来陪燕贺，且祝千年寿与齐。","樽前鹤，乃翩跹起舞，来上瑶卮。"]},{"t":"沁园春 其一 寿冰壶刘监丞，以竹为寿","f":"词","c":["径竹扶疏，直上青霄，玉立万竿。","似冰壶潇洒，虚心直节，清标贞干，风月无边。","清荫盈庭，细香满座，凡款公门皆七贤。","称觞旦，与松梅并祝，辞表南山。","绵延。","龙种儿孙。","列砌森庭栖凤鸾。","况节楼辟命，管城草檄，计台琐试，玉笋联班。","盛事重重，荐腾楛茧，渡蚁阴功须状元。","燕山乐，又使符踵至，趣赴淇园。"]},{"t":"沁园春 寿长斋友人","f":"词","c":["眼底高年，如老曾仙，斗南一人。","能持斋守戒，香山居士，乐天知命，康节先生。","满眼儿孙，满堂金玉，多宝如来现后身。","真堪羡，有许多福力，越见精神。","庆公今日生申。","喜渐近中秋对月明。","这平生积善，三千功行，前程享福，八百椿龄。","见说寿筵，大开佛事，煮鹤炮龙烙凤麟。","从今后，愿年年长健，事事如心。"]},{"t":"沁园春 其一 贺生第二子","f":"词","c":["蛮柳眠风，妃棠醉日，春意方浓。","怪凌晨乾鹊，欢声啧啧，充闾瑞霭，佳气葱葱。","白鹿效灵，黄龟献梦，还应君生第二龙。","兰房里，想犀帷晕翠，锦褓裁红。","五峰。","秀气攸钟。","更头玉硗硗天性聪。","自谪仙芳歇，久尘赋颂，江西派冷，谁嗣宗风。","骨脉尤香，云仍载诞，衮衮公侯从此封。","三朝满，好平分犀玉，满泛金钟。"]},{"t":"沁园春","f":"词","c":["凝眸。","悔上层楼。","便惹起新愁与旧愁。"]},{"t":"沁园春","f":"词","c":["国步多艰，民心靡定，诚吾隐忧。","叹浙民转徙，怨寒嗟暑，荆襄死守，阅岁经秋。","虏未易支，人将相食，识者深为社稷羞。","当今亟，出陈大谏，箸借留侯。","□□迂阔为谋。","天下士如何可籍收。","况君能尧舜，臣皆稷契，世逢汤武，业比伊周。","政不必新，贯仍宜旧，莫与秀才做尽休。","吾元老，广四门贤路，一柱中流。"]},{"t":"沁园春 寿东屏","f":"词","c":["奏捷淮堧，勒功燕石，鼓吹凯旋。","正归班玉笋，花袍方卸，彩衣亟著，忠孝双全。","清德独高，皇心简注，燕寝凝香朱两幡。","君王问，录屏风姓字，趣对金銮。","平山。","蹑履緌冠。","竞来庆嘉平五日间。","是炎刘昴宿，光至再现，绛人甲子，四百新颁。","碧麦称觞，玉枝等算，长对梅花开岁寒。","春回也，报调羹时候，梅子微酸。"]},{"t":"沁园春 寿刘宰","f":"词","c":["天下知名，今日刘郎，胜如旧时。","记当年幕府，元戎高会，万花围席，争看题诗。","尽道坡仙，再生尘世，有制宜烦立马挥。","东阳小，岂容久驻，凫舄暂双飞。","诸公荐墨交驰。","要推上青云百丈梯。","况平生慷慨，闻鸡起舞，中原事业，不付公谁。","生记今朝，频将指数，较莱公争半月期。","功名事，不输前辈，行即诏封泥。"]},{"t":"沁园春 寿刘提干","f":"词","c":["学富总龟，英蜚漕鹗，正当少年。","向山阴发轫，从容莲幕，结知当路，翠剡争先。","万斛龙骧，湖襄飞饷，赏秩新纶来日边。","重重庆，又金鱼新渥，玉树芝兰。","今朝好语欢传。","正南极真人生世天。","是紫囊阴骘，朱幡美德，平山钟秀，崧岳生贤。","事业惊人，行魁胪唱，展庆公庭云母间。","称觞祝，对今宵明月，千古团圆。"]},{"t":"沁园春 其二 寿赵宰","f":"词","c":["快阁春边，倚阑干外，东西晚晴。","有银潢公子，摩挲石刻，金华仙伯，主掌鸥盟。","陶柳清新，潘花红嫩，早有丰年笑语声。","还知道，是街头父老，竞说升平。","怪来昨夜长庚。","与一道澄江月共明。","但寿烟起处，千山天远，寿杯满后，千尺泉清。","兴庆宫中，长生殿里，早踏金鳌背上行。","明年好，望紫云楼上，一点台星。"]},{"t":"沁园春 寿闽帅正月初二","f":"词","c":["意一仙翁，自紫府中，出游戏身。","看脊梁铁铸，担当社稷，精神玉炼，照映乾坤。","谏省伏蒲，紫垣直笔，硬语曾惊天上人。","福身去，建红牙兼纛，南海之滨。","天公偏福吾闽。","遣夜锦开藩为帅臣。","记前回散了，几多饭碗，如今积了，千万禾囷。","心与天通，阴功无量，直待时来秉化钧。","年年宴，在人正次日，寿庆千春。"]},{"t":"沁园春 庆云山创屋","f":"词","c":["法从西清，雅志山东，超然燕怡。","笑洛城卢老，贫来屋破，花溪杜叟，雨里床移。","晚乃经营，欢言结架，夭矫晴虹朝已跻。","开山了，一灯灯相续，第一宗师。","乘闲小隐幽栖。","天与人谋应此时。","算春霆震响，不教龙蛰，甘霖布润，待倩云飞。","宥密思贤，明谟经远，共指神州克复归。","归来也，更身名烜赫，锦绣光辉。"]},{"t":"沁园春 冬至日娶","f":"词","c":["姑射琼仙，论人间世，学宫样妆。","费精神刺绣，裁成云锦，今朝喜遇，弱线添长。","收拾云情，铺张雨态，来嫁朱门趁一阳。","真还是，两情鱼水，并颈鸳鸯。","登科人道无双。","问小底何如大底强。","幸洞房花烛，得吹箫侣，短檠灯火，伴读书郎。","办苦工夫，求生富贵，要折丹枝天上香。","来秋也，看载膺鹗荐，载弄之璋。"]},{"t":"沁园春","f":"词","c":["柳眼偷金，梅肌晕玉，春信已催。","正浅寒天气，嫩晴日色，雨收巫峡，烟卷蓬莱。","青鸟衔音，彩鸾迎驾，白昼传呼王母来。","屏帏里，看合欢杯尽，连理花开。","笙歌上下楼台。","更罗绮丛中薰麝煤。","想雪香酥暖，粉娇翠软，风流乐事，慰惬情怀。","花帽兰袍，皂鞋槐简，谁似何郎年少才。","人偕老，类鸳鸯匹偶，鸾凤和谐。"]},{"t":"沁园春 侄寿叔又调官","f":"词","c":["长至阳生，律转黄钟，门左弧垂。","记当年瑞世，梦传玉燕，今朝诞节。","香爇金猊。","南极星明，北山堂邃，松桧苍苍龟鹤随。","况蟠桃下熟，仙童来献，喜介双眉。","平生谋画多奇。","算收拾功名须有时。","曾指麾万骑，刍飞粟挽，折冲千里，彗扫星驰。","荐口澜翻，宸恩鼎至，此去须还衣锦归。","人都道，黑头卿相，慷慨男儿。"]},{"t":"沁园春 寿冰壑十月十七","f":"词","c":["冰壑平生，如伯伦狂，似希乐豪。","喜观书不用、菊茶明眼，登山不倩、藜杖扶腰。","豆粥萍齑，鲙羹鳞脯，湖海人常折简招。","谁云老，有满怀风月，藏在诗瓢。","凌晨向鹄冲霄。","道昴宿于今又应萧。","记垂弧令节，恰当后日，下元好景，正属前朝。","冷胆如天，刚肠如剑，须把千杯寿酒浇。","那堪更，是梅花时月，烂熳溪桥。"]},{"t":"沁园春 自寿","f":"词","c":["甲子一周，织乌相催，又还十年。","但诗狂酒圣，坐常有客，书痴传癖，囊不留钱。","拍手浩歌，出门长笑，谁是知心有老天。","犹多事，更时游艺圃，日耨情田。","细思世事无边。","只好把清樽对眼前。","看槐国功名，有如戏剧，竹林宴赏，便似神仙。","富贵危机。","荣华作梦，早已输人一著先。","从今去、莫将醉趣，与醒人传。"]},{"t":"沁园春 贺生孙","f":"词","c":["喜见于门，子月阳生，子舍春回。","想释丘抱送，绝奇神骨，皙参授受，忠恕胚胎。","跨灶参先，撞楼踵后，鼎样一门三秀才。","应不数，那窦家五桂，王氏三槐。","南丰门户奇哉。","他日一声平地雷。","若非是河东，名传三凤，也应天上，光映三台。","莫道后时，方为贺客，且把犀钱玉果来。","却还取，这长生一曲，富贵三杯。"]},{"t":"沁园春 寿刘常州十二月廿九","f":"词","c":["淮海知名，今日刘郎，胜如旧时。","记当年幕府，从容赞画，云从万骑，电掣千麾。","威震新塘，气吞涟楚，涤扫妖氛但指期。","论功处，载骖鸾鹤，衣锦赋荣归。","九重诏已封泥。","看稳上青云万丈梯。","况平生慷慨，闻鸡起舞，中原事业，不付公谁。","昨夜颁春。","明朝献岁，且对椒盘奉寿卮。","功名事，不输前辈，行到凤凰池。"]},{"t":"沁园春 未开梅","f":"词","c":["我善观梅，识梅妙处，舍我其谁。","待裁冰剪雪，已无足道，凝酥弄粉，愈不为奇。","枉费心神，巡檐索笑，点检南枝并北枝。","梅应道，似这般题品，未是相知。","分明有个端倪。","遮莫把人间凡眼窥。","那精神全在，半含蕊处，风流全在，未有香时。","万木丛边，两三点白，此是生生化化机。","花开也，又怎生消得，个样词儿。"]},{"t":"沁园春 寿黄守","f":"词","c":["皂盖朱幡，玉节虎符，宏开大藩。","把济川舟楫，试横碧水，擎天柱石，小驻丹山。","麦秀两歧，棠敷千里，治最当今黄颍川。","平章看、文词坡谷，人品欧韩。","竭来游戏人间。","况雅量汪汪海样宽。","适弧垂门外，香凝燕寝，□星对照，两地交欢。","自有青州，活民阴德，不用延年九转丹。","人皆祝，愿黑头黄阁，绿鬓朱颜。"]},{"t":"沁园春","f":"词","c":["衮绣堂前，福星开度，寿星入垣。","有建隆臣普，上天宰辅，绍光臣鼎，平地神仙。","入秉钧衡，出分藩屏，托住东南半壁天。","年来好，甚烽消万里，尘静三边。","紫宸几度传宣。","刚不肯归班押讲筵。","纵云台勋业，已登盟府，金城筹策，犹念中原。","好袖山河，更扶日月，色正三台第一躔。","王韩去，愿齐休社稷，于万斯年。"]},{"t":"沁园春","f":"词","c":["山驿萧疏，水亭清楚，仙姿太幽。","望一枝颖脱，寒流林外，为传春信，风定香浮。","断送光阴，还同昨夜，叶落从知天下秋。","凭阑处，对冰肌玉骨，姑射来游。","无端品笛悠悠。","似怨感长门人泪流。","奈微酸已寄，青青杪，助当年太液，调鼎和馐。","樵岭渔桥，依稀精彩，又何藉纷纷俗士求。","孤标在，想繁红闹紫，应与包羞。"]},{"t":"沁园春 寿王倅","f":"词","c":["天遣东皇，来庆诞辰，和气先回。","趁未将风月，平分八桂，且垂弧矢，相映三槐。","歌遏行云，舞萦回雪，不比常年寿宴开。","有贤守，送三千乐指，环侍金罍。","文章政事奇哉。","曾飞舄双凫天外来。","便合除之六察，少旌最绩，何为别驾，暂屈长才。","尚亿传家，行将跨灶，岂但侯藩与外台。","称觞看，灵龟支坐，老鹤眠阶。"]},{"t":"沁园春 寿游侍郎","f":"词","c":["五岳三光，孕秀精神，时生俊髦。","看出匣锋铓，备施盘错，济川力量，历试风涛。","直卷经纶，十徵不就，争羡先生出处高。","徜徉处，有晋公绿野，陶令东皋。","精神翰墨游遨。","无一点风霜上鬓毛。","不访蓬莱，遍搜仙药，不登阆苑，三摘蟠桃。","洒洒丰姿，棱棱标致，长对梅花雪里梢。","青如许，与老松苍竹，定岁寒交。"]},{"t":"沁园春","f":"词","c":["萱草阑干，杨花庭院，夜景澄虚。","望庚星昴宿，荧荧照室，祥烟瑞霭，郁郁充闾。","白鹿入胎，黄龟献梦，果应君家生凤雏。","真英物，似昆山片玉，沧海明珠。","玳筵丝竹□□。","有多少犀钱分座隅。","念谢堂冷落，久无神语，淮淝骚扰，谁定边谟。","天产英雄，地钟秀气，振起家声今有馀。","□□□，看宫袍加鹄，玉带悬鱼。"]},{"t":"沁园春 其二 贺生第二子","f":"词","c":["明月呈规，祥烟非雾，载符梦铃。","记前时已庆，人间鸑鷟，今番再见，天上麒麟。","知是于门，功标紫府，夜半仙官敕五丁。","亲送与，向君家作个，难弟难兄。","绝奇不数徐卿。","看他日名登千佛经。","正翁翁矍铄，婆婆老福，薰修觉海，结果初成。","自愧空词，不酬杯水，汤饼难充堂上宾。","无功也，这犀钱玉果，敢望平分。"]},{"t":"泛兰舟","f":"词","c":["霜月亭亭时节，野溪开冰灼。","故人信付江南，归也仗谁托。","寒影低横，轻香暗度，疏篱幽院何在，秦楼朱阁。","称帘幕。","携酒共看，依依承醉更堪作。","雅淡一种天然，如雪缀烟薄。","肠断相逢，手捻嫩枝，追思浑似，那人浅妆梳掠。"]},{"t":"花心动 得于江西歌者，而不知名氏","f":"词","c":["粉堞云齐，度清笳、愁入暮烟林杪。","素艳透春，玉骨凄凉，勾带月痕生早。","江天苍莽黄昏后，依然是、粉寒香瘦。","动追感、西园嫩约，夜深人悄。","记得东风窈窕。","曾夜踏横斜，醉携娇小。","惆怅旧欢，回首俱非，忍看绿笺红豆。","香销纸帐人孤寝，相思恨、花还知否。","梦回处，霜飞翠楼已晓。"]},{"t":"花心动慢/花心动","f":"词","c":["暑逼芳襟，甚全无因依，便教人恶。","赖有枕溪百尺，朱楼映日，数重香箔。","驮冰围定犹嫌暖，红日绽、雨收残脚。","漫试取，红绡弄雪，碎琼推削。","妆罢低云未稤。","叶叶地仙衣，剪轻裁薄。","汗洒泪珠，急捧金盘，向前颗颗盛却。","凤凰双扇相交扇，越撋就、越腰肢弱。","待做个、青纱罩儿罩著。"]},{"t":"花前饮","f":"词","c":["雨馀天色渐寒渗。","海棠绽、胭脂如锦。","告你休看书，共我花前饮。","皓月穿帘未成寝。","篆香透、鸳衾双枕。","似恁天色时，你道是、好做甚。"]},{"t":"花酒令","f":"词","c":["花酒。","是我平生结底亲朋友。","十朵五枝花，三杯两盏酒。","休问南辰共北斗。","任从他乌飞兔走。","酒满金卮花在手。","且戴花饮酒。"]},{"t":"苏幕遮","f":"词","c":["陇云沈，新月小。","杨柳梢头，能有春多少。","试著罗裳寒尚峭。","帘卷青楼，占得东风早。","翠屏深，香篆袅。","流水落花，不管刘郎到。","三叠阳关声渐杳。","断雨残云，只怕巫山晓。"]},{"t":"苏幕遮","f":"词","c":["水中金，冲牛斗。","玉锁金关，护法灵童守。","赤水丹台龙虎走。","万象森罗，勃勃投珠口。","饮灵源，明火候。","太乙炉开，丹熟神光透。","浮名浮利终不久。","下手速修。","穷取无中有。"]},{"t":"诉衷情","f":"词","c":["悠悠万里云水。"]},{"t":"诉衷情令","f":"词","c":["碧天明月晃金波。","清浅滞星河。","深深院宇人静，独自问姮娥。","圆夜少，缺时多。","事因何。","嫦娥莫是，也有别离，一似人么。"]},{"t":"诉衷情","f":"七言古诗","c":["黄昏新月一钩纤。"]},{"t":"迎春乐令/迎春乐","f":"词","c":["神州丽景春先到。","看看是、韶光早。","园林深处东风过，红杏里、莺声好。","漠漠青烟远远道。","触目是、绿杨芳草。","莫惜醉重游，逡巡又、年华老。"]},{"t":"还宫乐","f":"词","c":["喜贺我皇，有感蓬莱，尽降神仙。","到乘鸾驾鹤御楼前。","来献长寿仙丹。","玉殿阶前排筵会，今宵秋日到神仙。","笙歌寥亮呈玉庭，为报圣寿万年。"]},{"t":"远朝归","f":"词","c":["新律才交，早旧梢南枝，朱污粉腻。","烟笼淡妆，恰值雨膏初细。","而今看了，记他日、酸甜滋味。","多应是，伴玉簪凤钗，低丫斜堕。","迤逦。","对酒当歌，眷恋得芳心，竟日何际。","春光付与，尤是见欺桃李。","叮咛寄语，且莫负、尊前花底。","拚沈醉，尽铜壶、漏传三二。"]},{"t":"乳燕飞/贺新郎 寿种春翁","f":"词","c":["指点金蕉叶。","倩双成、十分为注，九天琼液。","中有玉梅风露气，持寿卯金仙伯。","听贱子、歌翻新阕。","不作寻常儿女祝，把先生、好事从头说。","须快饮，莫留滴。","风流晋宋人物。","有锦囊万首，不博小儿馆职。","膝下双雏真伟器，足继传家事业。","且做个、人间闲客。","试问种春春几许，尽芝田万顷天来阔。","天有尽，春无极。"]},{"t":"乳燕飞/贺新郎 十二月十九日","f":"词","c":["问讯绂麟何日是，腊月生辰十九。"]},{"t":"侍香金童","f":"词","c":["喜叶之地，手把怀儿摸。","甚恰恨、出题厮撞著。","内臣过得不住脚。","忙里只是，看得斑驳。","骇这一身冷汗，都如云雾薄。","比似年时头势恶。","待检又还猛想度。","只恐根底，有人寻着。"]},{"t":"侍香金童","f":"词","c":["宝台蒙绣，瑞兽高三尺。","玉殿无风烟自直。","迤逦传杯盈绮席。","苒苒菲菲，断处凝碧。","是龙涎凤髓，恼人情意极。","想韩寿、风流应暗识。","去似彩云无处觅。","惟有多情，袖中留得。"]},{"t":"卓牌儿/卓牌子","f":"词","c":["当年早梅芳，曾邂逅、飞琼侣。","肌云莹玉，颜开嫩桃，腰支轻袅，未胜金缕。","佯羞整云鬟，频向人、娇波寄语。","湘佩笑解，韩香暗传，幽欢后期难诉。","梦魂顿阻。","似一枕、高唐云雨。","蕙心兰态，知何计重遇。","试问春蚕丝多少，未抵离愁半缕。","凝伫。","望凤楼何处。"]},{"t":"夜游宫","f":"词","c":["因被吾皇手诏。","把天下、寺来改了。","大觉金仙也不小。","德士道。","却我甚头脑。","道袍须索要。","冠儿戴、恁且休笑。","最是一种祥瑞好。","古来少。","葫芦上面生芝草。"]},{"t":"夜游宫","f":"词","c":["是处追寻侣。","灯光散、九衢红雾。","人在星河繁闹处。","暗相逢，惹天香，飘满路。","游困先归去。","奈怨别、相思情绪。","闲傍小桃□独步。","月明寒，捻宜男，无一语。"]},{"t":"治平二年南郊鼓吹歌曲四曲 其四 奉禋歌","f":"词","c":["皇天眷命集珍符。","上圣膺期起天衢。","环紫极鸿枢。","此时朝野欢娱。","乐于于。","似住华胥。","和气至，嘉生遂，豆实正芬敷。","礼与诚俱。","风飘洒，灵来下，喜怡愉。","斗随车转，月上坛觚。","奉禋初。","至诚孚。","如山岳、福委祥储。","车旋轨、云间双阙峙，百尺朱绳到地，两行雉扇排虚。","仙鹤衔书。","珍袍上笏相趋。","共欢呼。","号令崇朝，遍满寰区。","阳动春嘘。","躬盛事，受多祉，千万祀，天长地久皇图。"]},{"t":"亲耕藉田四首 其四 奉禋歌","f":"词","c":["吾皇端立太平基。","奉祀肃雍、格神祇。","抚御耦，降嘉种何辞。","手览洪縻。","命太史视日，祗告前期。","验穹象，天田入望更光辉。","掌礼陈仪。","搜钜典，迎春令，颁宣温诏遍九围。","人尽熙熙。","仰明时。","俨垂衣。","佳气氤氲表庞禧。","丰年屡，大田生异粟，含滋吐秀，九种传图，尽来丹阙，瑞应昌时。","亨运正当摄提。","伫见咏京坻。","躬稼穑，重耘耔。","盛礼兴行先百姓，崇本业，忧勤如禹稷，播在声诗。"]},{"t":"祫享太庙 其二 奉禋歌","f":"词","c":["皇泽均普，群生遂。","万宇和祔，讲天津、合祭圣宗神祖，八音钧奏谐节。","堂上荐鸣球，琴瑟击。","越布濩、霜空静，月华凝、光景蔼蔼。","纷纷晓霞披。","和铃作、鸾舆回。","天人共睹，庆无疆、祚崇明祀。","五辂驾、腾黄纯驷。","旗常扈跸严环卫。","公卿奉引，虚徐驰道，祲容靡。","葱葱郁郁，祥风瑞霭。","发天光旖旎。","锡羡丰融，漏泉该浃，上恩遐被。","群心豫，颂声作，皇德至，侔乾贶，浩浩霈。"]},{"t":"高宗祀大礼鼓吹歌曲五首 其四 奉禋歌","f":"词","c":["苍苍天色是还非。","视下应疑。","亦若斯。","统元气，覆无私。","四时寒暑推移。","物蕃滋。","造化有谁知。","严大报，反本始，礼重祀神祇。","律管灰吹。","黄宫动，阳来复，景长时。","车陈法驾，仗列黄麾。","帝心祗。","紫霄霁，霜华薄，星烂明垂。","祥烟起，纷敷浮衮冕，六变笙镛迭奏，一诚币玉交持。","宫漏声迟。","千官显相多仪。","百神嬉。","风马云车，来止来绥。","诞降纯禧。","受神策、万年无极，歌颂昊天，成命周诗。"]},{"t":"藉田明道二年四曲 其四 奉禋歌","f":"词","c":["六龙承驭。","紫坛平、瑞蔼葱笼拥神都。","肃环卫、严貔虎。","鸡人行漏传呼。","灵景霁、星斗临帝居。","旷天宇。","微风来、翠幄绕相乌。","对越方初。","笳鼓震，铙箫举。","阳律才动协气舒。","氛祲交祛。","物昭苏。","抚瑶图。","柴类精诚，当契唐虞。","思前古。","泰平承多祐。","包戈偃革，柔远咏皇谟。","称文武。","四表覆盂。","端冕出、从路车。","兵帅谨储胥。","唯奏凯、乐康衢。","朝野欢娱。","歌帝烈，扬盛节，圜丘礼大洽，霈泽绵区。"]},{"t":"宁宗郊祀大礼四首 其三 奉禋歌","f":"词","c":["葭飞璇籥，孕初阳。","云绝清台、荐景祥。","风应律，日重光。","岁功顺，底金穰，寿而康。","庭壶乐无疆。","皇展报，新礼乐，觚陛咏宾乡。","珠幄熉黄。","登瑞缫，陈俎豆，澹嘉觞。","衮衣辉焕，宝佩琳琅。","奠椒浆。","庆阴阴，神来下，凤翥龙骧。","灵燕喜，锡符仍降嘏，镛管琳琅。","欢亮神之出，祓兰堂。","辇路天香。","轻烟半袭旗常。","祉滂洋。","受厘宣室，返驭斋房。","恩与凤翔。","华封祝、皇来有庆，八荒同寿，宝历无疆。"]},{"t":"孤鸾","f":"词","c":["天然标格。","是小萼堆红，芳姿凝白。","淡伫新妆，浅点寿阳宫额。","东君相留厚意，倩年年、与传消息。","昨夜前村雪里，有一枝先折。","念故人、何处水云隔。","纵驿使相逢，难寄春色。","试问丹青手，是怎生描得。","晓来一番雨过，更那堪、数声羌笛。","归去和羹未晚，劝行人休摘。"]},{"t":"定风波","f":"词","c":["痛饮形骸骑蹇驴。","葛巾不整倩人扶。","笑指桃源泥样醉，三睡。","诗魔长是泣穷途。","画手也知仙骨瘦，□□。","昆山玉水点银须。","天地不能容此老，笑傲。","一竿风月钓江湖。"]},{"t":"定风波","f":"词","c":["雨雾云收望远山。","钓竿林下恣清闲。","蝉噪日斜林影转。","溪岸。","绿深红浅画屏间。","对酒狂歌时鼓枻。","更邀同志醉前湾。","待月却寻维缆处，归来，烟萝一径接柴关。"]},{"t":"定风波","f":"七言古诗","c":["古鼎龙涎香犹喷。"]},{"t":"定风波","f":"七言古诗","c":["素笺封了还重拆。"]},{"t":"定风波 其二","f":"词","c":["一树寒梅傍小溪。","夜来陡觉绽南枝。","冷艳冰姿金蕊浅。","堪羡。","凝明因与雪霜期。","折赠美人临宝鉴。","云脸。","鬓边斜插最相宜。","凭仗高楼频祝付。","说与。","马融羌管且停吹。"]},{"t":"定风波 其一","f":"词","c":["又是春归烟雨村。","一枝香雪度黄昏。","竹外云低疏影亚。","潇洒。","水清沙浅见天真。","瘦玉欺寒香不暖。","堪羡。","冰姿照夜月无痕。","楼上笛声休听取。","说与。","江南人远易销魂。"]},{"t":"定风波慢","f":"词","c":["漏新春、消息前村，数枝楚梅轻绽。","□雪艳精神，冰肤淡伫，姑射依稀见。","冷香凝，金蕊浅。","青女饶伊妒无限。","堪羡。","似寿阳妆阁，初匀粉面。","纤条绿染。","异群葩、不似和风扇。","向深冬、免使游蜂舞蝶，撩拨春心乱。","水亭边，山驿畔。","立马行人暗肠断。","吟恋。","又忍随羌管，飘零千片。"]},{"t":"宝鼎现 寿曹安抚","f":"词","c":["天高良月。","瑞霭葱倩，绮霞粲浩。","望宝阁、奎躔交绚，秀毓文星正佳节。","九万里俱在下，礼乐三千剀切。","扶兴运、魁星标瑞，曾补赭黄衮阙。","盎盎一道棠阴芾，宜福星、临照南国。","岁屡稔，月沉夜柝，父老欢谣齐喜溢。","庆衮衮、罗庭前兰玉，好是香连夜月。","十万户深深祝，愿此寿星南极。","自是天上神仙，宽宸顾、实劳耆德。","辄使星入觐，又报日边消息。","天为遣、梅花催雪。","惟有春知得。","要待列、金鼎和羹，两两台星齐色。"]},{"t":"念奴娇","f":"词","c":["雨肥红绽，把芳心轻吐，香喷清绝。","日暮天寒，独自倚修竹，冰清玉洁。","待得春来，百花若见，掩面应羞杀。","当风抵雨，犯寒则怕吹霎。","潇潇爱出墙东，途中遥望，已慰人心渴。","斗压阑干，人面共花面，难分优劣。","嚼蕊寻香，凌波微步，雪沁吴绫袜。","玉纤折了，殢人须要斜插。"]},{"t":"念奴娇 二月廿三","f":"词","c":["池塘风暖，算流觞盛集，恰迟旬日。","晓听儿童传好语，瑞气华堂充溢。","天产英雄，封侯骨相，才气千人敌。","暂游尘世，妙名已上仙籍。","争羡金紫盈门，灵椿正茂，荣庆谁能及。","会展龙韬并豹略，重把山河开辟。","鼻祖汾阳，佐唐勋业，管取今犹昔。","名垂彝鼎，寿龄更比箕翼。"]},{"t":"念奴娇","f":"词","c":["脉脉此情难识。"]},{"t":"念奴娇 寿侍郎","f":"词","c":["今年秋早，似常年、人世光阴如电。","君看老仙风度别，绿发芳瞳长健。","细数平生，三千功行，一一修持遍。","通明殿上，钧天张乐高燕。","应似六一先生，神清之洞，万仞苍苔藓。","少待中原开霁了，一片闲云舒卷。","姹女炼成，婴儿养就，坐阅蓬莱浅。","青霄笙鹤，也应回顾鸡犬。"]},{"t":"念奴娇 寿司户四月廿六","f":"词","c":["绿云霁雨，倚晴空千尺，长江澄縠。","十里薰低、绣幕四叶，其馀华屋。","怪得清都，奔云拥鹤，环佩声相续。","朝来无是，有人初降仙箓。","且与小试民曹，梅花岭外，雪片三冬足。","眼底承家人物在，楚楚圭璋兰玉。","雾阁云窗，翠眉红颊，解唱长生曲。","壶中难老，定应两鬓长绿。"]},{"t":"念奴娇","f":"词","c":["玲珑枝枝，斗妆金粟。"]},{"t":"念奴娇 温州平阳灵峰摩崖词","f":"词","c":["天工谬巧，恁平地、推出崚嶒岩壁。","虎跃龙骧飞凤翥，疑道补天馀石。","洞壑穿云，来今往古，知是谁开辟。","千年兰若，林峦隐映金碧。","我兴丘壑尤长，朅来此境，惯蹑登山屐。","适意人生随处好，何必岘南阳峄。","谢傅东山，裴公绿野，俯仰俱陈迹。","何如轻举，廓寥云外横笛。"]},{"t":"念奴娇","f":"词","c":["万里秋容浩荡。"]},{"t":"念奴娇","f":"词","c":["沁园秋早。","对亭台冷落，荒凉池沼。","西帝晨游无异胜，都把仙花开了。","金粟玲珑，鹅黄娇嫩，不管霜风悄。","清香入梦，梦魂惟怕天晓。","乘兴折取一枝，满身兰麝，不减蟾宫好。","赠与佳人，因笑道、休学姮娥空老。","待约明朝，金英满地，莫遣儿童扫。","相将花上，醉眠尤胜芳草。"]},{"t":"念奴娇","f":"词","c":["一点芳姿，信道是、不比人间凡木。"]},{"t":"念奴娇","f":"词","c":["岁华渐杪，又还是春也，难禁愁寂。","欲探疏梅，独自个、寻访山村水驿。","路转溪斜，竹低墙短，应是瑶姬宅。","玉蕤不动，月轮寒浸国色。","回首故国风光，只因清好，重作江南客。","堪笑广平，争解我、羁旅芳心脉脉。","不借铅华，枝头雪霁，愈见香肌白。","高楼且住，恁渠一弄羌笛。"]},{"t":"念奴娇 其二 寿陈运使","f":"词","c":["素娥不老，才胜赏中秋、无边月色。","又报仙翁来桂苑，连庆生申佳节。","玉宇无尘，金茎有露，对景成三绝。","重阳近也，黄花香入瑶席。","尽说湖海元龙，裕民堂上，几度吟梅雪。","满眼阴阴甘棠树，消得寿同南极。","八桂难留，九芝促觐，早露真消息。","星辰听履，好看明岁今日。"]},{"t":"念奴娇 六月廿六","f":"词","c":["先秋四日，正祥开弧矢，生申佳节。","天上彩麟曾入梦，钟作人间英杰。","袭庆盘坡，流芳星渚，家世绵簪绂。","昨宵凝眺，老人星现天阙。","鼎创庭馆连云，宴仙停棹，咫尺尘凡隔。","好把蟠桃庭外种，坐看花开花结。","秀长孙枝，辉联子舍，蟾桂行攀折。","它年称寿，满堂朱紫罗列。"]},{"t":"念奴娇","f":"五言古诗","c":["对景真奇绝。"]},{"t":"念奴娇 侄庆叔五月十七","f":"词","c":["垂弧纪节，正尧天日永，蓂飞双绿。","岳渎钟灵来瑞世，孕出精神冰玉。","九曲溪山，一船烟雨，物外谁拘束。","钓头香饵，只愁牵动周卜。","好是红藕池边，双房毓秀，瑞霭浮昆轴。","记得君家流庆远，几见祥开陆续。","来岁花时，西湖十里，叶映恩袍绿。","竹林小阮，不妨傍借馀馥。"]},{"t":"念奴娇","f":"词","c":["兰枯蕙死，向竹斋深处，谁传消息。","霜雪丛中浑似个，缥缈吴人标格。","绛萼微深，琼苞不露，自与尘凡隔。","黄昏遥见，一枝烟淡笼白。","曾记雾阁云窗，轻飞香篆，佳句应难得。","道韫能文，终未胜、潇洒风流姿质。","待到春来，满城桃李，相并无颜色。","殷勤祝付，画楼休品长笛。"]},{"t":"拨棹子","f":"词","c":["烟姿媚，冰容薄。","芳蕖嫩、隐映新萍池阁。","撷英人去后，清香微绽，透真珠帘幕。","似无语含情垂彩佩，戏芳阴，渐许纤鲜相托。","西风直须爱惜，看看浓艳，伴秋光零落。"]},{"t":"枕屏儿","f":"词","c":["江国春来，留得素英肯住。","月笼香，风弄粉，诗人尽许。","酥蕊嫩，檀心小，不禁风雨。","须东君、与他做主。","繁杏夭桃，颜色浅深难驻。","奈芳容，全不称，冰姿伴侣。","水亭边，山驿畔，一枝风措。","十分似、那人淡伫。"]},{"t":"武林春/武陵春","f":"词","c":["昨夜前村深雪里，春信为谁传。","风送清香满座间。","不用热沈檀。","竹外一枝斜更好，偏称玉人攀。","休放游蜂去又还。","嫌怕损芳颜。"]},{"t":"武陵春","f":"七言古诗","c":["柳绿花红春烂熳。"]},{"t":"河传","f":"词","c":["香苞素质。","天赋与、倾城标格。","应是晓来，暗传东君消息。","把孤芳、回暖律。","寿阳粉面增妆饰。","说与高楼，休更吹羌笛。","花下醉赏，留取时倚阑干，斗清香、添酒力。"]},{"t":"转调贺圣朝/贺圣朝","f":"词","c":["渐觉一日，浓如一日，不比寻常。","若知人、为伊瘦损，成病又何妨。","相思到了，不成模样，收泪千行。","把从前泪，来做水流，也流到伊行。"]},{"t":"采桑子 其七","f":"词","c":["霜风漏泄春消息，折破孤芳。","野兴彷徨。","姑射神仙触处藏。","新妆不假施朱粉，雪月交光。","欲赠东皇。","冷淡龙涎点点香。"]},{"t":"采桑子 其一","f":"词","c":["阳和欲报春来也，先上南枝。","桃李休疑。","折遍香梢人未知。","黄昏小院谁攀折，疏影斜敧。","半掩朱扉。","旋嗅清香月下归。"]},{"t":"采桑子 其九 再雪中","f":"词","c":["飞琼欲赴瑶台宴，先具威仪。","云驾霓衣。","从者皆骑白凤飞。","人间尽变为银海，此景偏奇。","姑射冰姿。","昨夜前村见一枝。"]},{"t":"采桑子","f":"词","c":["年年才到花时候，风雨成旬。","不肯开晴，误却寻花陌上人。","今朝报道天晴也，花已成尘。","寄语花神。","何似当初莫做春。"]},{"t":"采桑子 其一 蜡梅","f":"词","c":["熔金脱得花钿小，点缀琼枝。","月淡风微。","露浥香肌自是奇。","玉人呵手昂头剪，纤鬓边垂。","似簇蜂儿。","春入芳容不肯飞。"]},{"t":"采桑子 其五","f":"词","c":["东君有意观群卉，故放争先。","带露含烟。","对月偏宜映水边。","琼苞素蕊胭脂淡，雪后风前。","堪赏堪怜。","曾与歌楼佐管弦。"]},{"t":"采桑子 其八","f":"词","c":["烟笼淡月寒宵永，悄悄帘栊。","微度香风。","几点梅开小院中。","拥衾敧枕难成寐，萧寺初钟。","雁响遥空。","家在青山千万重。"]},{"t":"采桑子 其三","f":"词","c":["南枝淡伫无妖艳，蜡蕊羞黄。","争似红妆。","不假施朱弄晓光。","雪融日暖琼肌腻，酒晕生香。","桃脸相当。","尤笑桃花混众芳。"]},{"t":"采桑子 其二","f":"词","c":["江南春信梅先赋，休道春迟。","映竹开时。","姑射仙人雪作肌。","青楼且莫吹羌管，留劝金卮。","折取南枝。","香满名园蝶未知。"]},{"t":"采桑子 其六","f":"词","c":["群芳尽老园林烬，独有寒梅。","探得春回。","昨夜前村一朵开。","轻盈雪里孤根秀，素脸香腮。","羌管休催。","留取琼葩佐酒杯。"]},{"t":"采桑子 其四","f":"词","c":["幽芳莹白前村里，岂藉春工。","胜尽群红。","琼捻凝酥向不同。","一声羌管愁人处，片片西东。","睹此遗踪。","不怨狂风怨马融。"]},{"t":"采莲令","f":"词","c":["重阳泪眼，又早是、苦离肠。"]},{"t":"金盏子令 嗺子","f":"词","c":["东风报暖，到头嘉气渐融怡。","巍峨凤阙，起鳌山万仞，争耸云涯。","梨园弟子，齐奏新曲，半是埙篪。","见满筵、簪绅醉饱，颂鹿鸣诗。"]},{"t":"金盏子慢/金盏子","f":"词","c":["丽日舒长，正葱葱瑞气，遍满神京。","九重天上，五云开处，丹楼碧阁峥嵘。","盛宴初开，锦帐绣幕交横。","应上元佳节，君臣际会，共乐升平。","广庭。","罗绮纷盈。","动一部、笙歌尽新声。","蓬莱宫殿神仙景。","浩荡春光，逦迤王城。","烟收雨歇，天色夜更澄清。","又千寻火树，灯山参差，带月鲜明。"]},{"t":"金盏倒垂莲","f":"词","c":["依约疏林，见盈盈春意，几点霜蕤。","应是东君，试手作芳菲。","粉面倚、天风微笑，是日暖、雪已晴时。","人静么凤翩翩，踏碎残枝。","幽香浑无著处，甚一般雨露，独占清奇。","淡月疏云，何处不相宜。","陌上报春来也，但绿暗、青子离离。","桃杏应仗先容，次第追随。"]},{"t":"金钱子","f":"词","c":["昨夜金风，黄叶乱飘阶下。","听窗前、芭蕉雨打。","触处池塘，睹风荷凋谢。","景色凄凉，总闲却、舞台歌榭。","独倚阑干，惟有木犀幽雅。","吐清香、胜如兰麝。","似金垒妆成，想丹青难画。","纤手折来，胆瓶中、一枝潇洒。"]},{"t":"金缕衣/贺新郎 贺云溪建楼","f":"词","c":["帝遣司花女。","炯琼琚瑶佩，新来满空飞舞。","飞到水晶宫阙处，还被六丁迎住。","唤月娣、天孙说与。","道是云溪新洞府，粲玉虹、拥出神仙宇。","齐星汉，切云雾。","朝来细把虹梁举。","命日兄、催上金鸦，高高腾翥。","云母卷帘三万数，不碍风斤月斧。","真个是、去天尺五。","恰则紫皇香案近，那砖花、院柳宜年少。","双鬓绿，朝天去。"]},{"t":"金缕词/贺新郎 寿宁化刘宰","f":"词","c":["瑞气重闽宇。","小春馀、璇霜避暖，敛威青女。","一点阳和钟英气，崧岳今朝诞甫。","正两荚、尚留蓂舞。","应想宁川称寿处，听金笼、放鸽儿童语。","愿千岁，祝慈父。","君家自有安民谱。","袖良规、时宽辔策，夜闲桴鼓。","直赖汀南为保障，无复鼪鼯啸聚。","果峻秩、升朝褒叙。","治最行将书第一，去思碑、拟颂歌明府。","飞诏趣，缀鸳鹭。"]},{"t":"金落索","f":"词","c":["风撼梧桐影碎。","凄凉天气。"]},{"t":"金殿乐慢 踏歌唱","f":"词","c":["驾紫鸾軿。","乘风缥缈游仙。","红霓蘸影，近瑶池、鹤戏芝田。","临蕙圃、饮琼泉。","上萧台、遥瞻九天。","对真人蕊书亲授，已向南宫住长年。"]},{"t":"宁宗郊祀大礼四首 其四 降仙台","f":"词","c":["星芒收采，云容放晓，羲驭渐扬明。","觚坛竣事，斋风袭、衮衣轻。","銮路尘清。","甘泉卤簿，祲威肃、回轸旋衡。","千官道从粲簪缨。","钧奏间韶英。","瞻龙闱，近凤城。","都人云会，芬茀夹道欢迎。","宸极尊荣。","卮玉庆熙成。","琼楼天上起和声。","布春泽，洪畅寰瀛。","嵩呼万岁，鳌三抃、颂升平。"]},{"t":"高宗祀大礼鼓吹歌曲五首 其五 降仙台","f":"词","c":["升烟既罢，良夜未晓，天步下神丘。","锵锵鸣玉佩，炜炜照金莲，杳蔼云裘。","彩仗初转，回龙驭、旌旆悠悠。","星影疏动与天流。","漏尽五更筹。","大明升，东海头。","杲杲灵曜，倒影射旗旒。","辇路具修。","葱郁瑞光浮。","归来双阙看御楼。","有仙鹤、衔书赦囚。","万方喜气，均祉福，播歌讴。"]},{"t":"雨中花慢","f":"词","c":["宴阙倚栏郊外，乍别芳姿，醉登长陌。","渐觉联绵离绪，淡薄秋色。","宝马频嘶，寒蝉晚、正伤行客。","念少年踪迹。","风流声价，泪珠偷滴。","从前与、酒朋花侣，镇赏画楼瑶席。","今夜里、清风明月，水村山驿。","往事悠悠似梦，新愁苒苒如织。","断肠望极。","重逢何处，暮云凝碧。"]},{"t":"雨中花慢","f":"词","c":["梦破江南春信，渐入江梅，暗香初发。","乞与横斜疏影，为怜清绝。","梁苑相如，平生有赋，未甘华发。","便广寒争遣，韶华惊怨，讵妨轻折。","扬州二十四桥歌吹，不道画楼声歇。","生怕有、江边一树，要堆轻雪。","老去苦无欢事，凌波空有纤袜。","恨无好语，何郎风味，定教谁说。"]},{"t":"青门怨","f":"词","c":["月痕烟景。","远思孤影。","旧梦云飞，离魂冰冷。","脉脉恨满东风。","对孤鸿。","翠珠尘冷香如雾。","人何许。","心逐章台絮。","夜深酒醒，烛暗独倚危楼。","为谁愁。"]},{"t":"青玉案","f":"词","c":["更憔悴、羞人见。"]},{"t":"青玉案","f":"词","c":["人生南北如歧路。","世事悠悠等风絮。","造化小儿无定据。","翻来覆去，倒横直竖，眼见都如许。","伊周功业何须慕。","不学渊明便归去。","坎止流行随所寓。","玉堂金马，竹篱茅舍，总是无心处。"]},{"t":"青玉案 其一 寿赵宰母二月十四","f":"词","c":["柳阴花底春将半。","吹不断、祥烟散。","何处绮罗丝竹乱。","天孙星里，老人星畔，昨夜光芒现。","绿衣好把斑衣换。","照新渥、金花满。","酌斗深深频祝愿。","凤池它日，莺花此景，春酒年年劝。"]},{"t":"青玉案 其二 二月十五","f":"词","c":["红娇绿软芳菲遍。","正荏苒、春方半。","帘幕任垂花影乱。","年年此日，月娥仙子，来赴瑶池宴。","绮罗暗帘成行满。","尽酌金樽十分劝。","愿指松椿为寿算。","北堂深处，朱颜绿鬓，赢得此身强健。"]},{"t":"青玉案","f":"词","c":["钉鞋踏破祥符路。","似白鹭、纷纷去。","试盝幞头谁与度。","八厢儿事，两员直殿，怀挟无藏处。","时辰报尽天将暮。","把笔胡填备员句。","试问闲愁知几许。","两条脂烛，半盂馊饭，一阵黄昏雨。"]},{"t":"青玉案 送刘置宠","f":"词","c":["青螺江上梅花暮。","有姑射、神仙侣。","剩把明珠倾满斛。","老仙源委，玉妃风韵，真是欺蛮素。","彩鸾齐跨山中去。","浑似天台旧时路。","试问风流春几许。","芳心嫩叶，如今时候，好景才三五。"]},{"t":"青玉案","f":"七言古诗","c":["彤云黯黯寒云绕。"]},{"t":"驻马听","f":"词","c":["雕鞍成谩驻。","望断也不归，院深天暮。","倚遍旧日，曾共凭肩门户。","踏青何处所，想醉拍、春衫歌舞。","征旆举。","一步红尘，一步回顾。","行行愁独语。","想媚容、今宵怨郎不住。","来为相思苦。","又空将愁去。","人生无定据。","叹后会、不知何处。","愁万缕。","仗东风、和泪吹与。"]},{"t":"鱼水同欢 庆两子同日十月初六","f":"词","c":["棣萼楼前佳气蔼。","欣遇称觞，正斗杓移亥。","三两日来连庆会。","贺宾喜色增加倍。","未逊徐雏分小大。","好比晋朝，二陆休声在。","更祝灵椿颜不改。","三苏相继居台宰。"]},{"t":"临江仙 寿友人六月初七","f":"词","c":["六月炎天收火伞，南薰洗尽烦蒸。","尧蓂七荚又争青。","问知陈仲举，元是此时生。","别驾功名清暇日，题兴尚带屏星。","黑头非晚到公卿。","且倾浮蚁酒，来听祝龟龄。"]},{"t":"临江仙 十一月十三","f":"词","c":["要问南枝消息早，一阳恰喜方回。","望前二日验云台。","祥光呈五色，瑞彩上三台。","生机一脉何尝息，正看用世真才。","调羹手段此胚胎。","文明观盛会，直待六阳来。"]},{"t":"临江仙","f":"词","c":["乐奏箫韶花烛夜，风流玉女才郎。","同心结上桂枝香。","如鸾如凤友，永效两双双。","莫把画堂深处负，笙歌引入兰房。","满斟玉斝醉何妨。","南山堪作誓，福禄应天长。"]},{"t":"临江仙 寿判府七月十四","f":"词","c":["长记秋来多好处，清凉遍满人间。","天教收拾孕真贤。","何时初度日，明日是中元。","喜与莱公同盛旦，官居鼎鼐相传。","未应此地借蕃宣。","来年开宴处，人在凤池边。"]},{"t":"临江仙 寿石守","f":"词","c":["良月露浓仙掌润，郁葱佳气充闾。","几年重席旧师儒。","大椿同未老，灵寿不须扶。","江左衣冠登桂籍，蝉联四世谁如。","琳宫昨下凤凰书。","金闺班趣缀，禁路莫踟蹰。"]},{"t":"临江仙 十二月初八","f":"词","c":["称觞喜对二阳临。","况当弦月上，一醉祝千春。"]},{"t":"临江仙 寿妇人七十十一月十一","f":"词","c":["鲁观书云方在候，颍川家庆非常。","望前四日上椒觞。","北堂人未老，南极夜增光。","借问遐龄今几许，希年恰喜相当。","愿同王母寿延长。","蟠桃看屡熟，萱草镇长芳。"]},{"t":"南歌子 贺生孙","f":"词","c":["祖德绵绵盛，家声烨烨传。","流光重庆子生贤。","想见朝来庭户、起非烟。","对客延汤饼，呼童散彩钱。","休夸骨瘦与神全。","看取犀庭玉角、已朝天。"]},{"t":"临江仙 寿何察推六月廿一","f":"词","c":["六月翠蓂飞六荚，流空大火将西。","当年名世间生时。","似光风霁月，神爽更精奇。","三十成名登上第，芙蓉照水真犀。","难淹逸步造丹墀。","经纶须大手，谈笑入黄扉。"]},{"t":"临江仙 庆梁孺人十二月初三","f":"词","c":["数朵寒梅方破腊，良宵新月初生。","晓来闺阁庆生辰。","天孙应降诞，德迈孟光贤。","喜配伯鸾真得耦，乘龙产凤齐名。","称觞岁岁祝长年。","瑶池桃未熟，南极婺星明。"]},{"t":"临江仙 其五","f":"词","c":["玉貌香腮天赋与，清姿不假铅华。","素芳寻在五陵家。","欲知春信息，庾岭一枝斜。","别有玲珑潇洒处，月梢淡影笼遮。","休教羌笛一声嗟。","宫妆犹未似，留取意无涯。"]},{"t":"临江仙 贺人寿有父有兄弟十一月初三","f":"词","c":["三叶翠蓂开子月，九天降诞文星。","满堂佳气蔼祥云。","称觞椒有颂，介寿酒浮春。","强仕宜为攀折客，须知富贵催人。","看看雁塔即联名。","一门夸盛事，棠棣对灵椿。"]},{"t":"临江仙 寿赵簿四月廿一","f":"词","c":["结夏骎寻逾六日，蓬壶纪瑞生辰。","祥烟葱郁蔼门庭。","骖鸾双女侍，毓凤二雏新。","暂尔勾稽淹大手，声名已彻枫宸。","行膺当路荐章荣。","璇源添喜庆，椿算祝遐龄。"]},{"t":"临江仙","f":"词","c":["促坐重燃绛蜡，香泉细泻银瓶。","一瓯月露照人明。","清真无俗韵，久淡似交情。","正味能销酒力，馀甘解助茶清。","琼浆一饮觉身轻。","蓝桥知不远，归卧对云英。"]},{"t":"临江仙 其一","f":"词","c":["漏出春光三四朵，冰肌玉骨偏宜。","乍开应笑百花迟。","将军曾止渴，画角已先知。","素艳不容蜂蝶采，清香自有人知。","而今虽被霜雪欺。","和羹终待手，金鼎自逢时。"]},{"t":"临江仙","f":"词","c":["绿暗汀洲三月暮，落花风静帆收。","垂杨低映木兰舟。","半篙春水滑，一段夕阳愁。","灞水桥东回首处，美人亲上帘钩。","青鸾无计入红楼。","行云归楚峡，飞梦到扬州。"]},{"t":"临江仙 寿赵守","f":"词","c":["香雾菲微笼薄晓，帘栊爱日如春。","谪仙游戏到寰瀛。","金枝推独秀，宝籍著长生。","锦轴疏恩怡寿母，朱轮光映难兄。","会看家庆日增荣。","雁联鸳序立，彩戏衮衣新。"]},{"t":"临江仙 其二","f":"词","c":["陇首云收天色暮，寒光射月初开。","昆荆山玉莫疑猜。","琳琅疑此地，仙子不红腮。","丽质霜裾真性雅，馀香暗送人来。","乱将碎玉缀枝排。","雪中寻不见，青萼辨奇才。"]},{"t":"临江仙 庆寿日趋朝十一月廿三","f":"词","c":["律按黄钟馀七日，左扉弧矢呈祥。","好看一点上眉黄。","台星还又照，相映寿星光。","今岁生辰应迥别，趋朝已趣曹装。","姓名稳稳造鸳行。","来年三四月，衣锦早还乡。"]},{"t":"临江仙 十二月十三日","f":"词","c":["欣遇月圆先两日，称觞对二阳来。"]},{"t":"临江仙 闻郡守移传芗林","f":"词","c":["竹里行厨草草，花边系马匆匆。","使君移传意何穷。","儿童随骑火，猿鹤避歌钟。","梅雪自欺舞态，烛花先放春红。","酒醒人散夜堂空。","殷勤松上月，独照老仙翁。"]},{"t":"临江仙 其三","f":"词","c":["昨夜新阳回候馆，芳菲正满霜林。","此时珍赏重千金。","谁知红粉艳，还有岁寒心。","风动霞衣香散漫，酒醺丹脸深沈。","妖娆偏称美人簪。","一枝无处赠，折得自孤吟。"]},{"t":"临江仙 其四","f":"词","c":["爱日新添春一线，化工先到寒梅。","不随桃李傍熙台。","前村深雪里，昨夜一枝开。","姑射仙人标格韵，凝墙粉谢香腮。","数家清弄笛声哀。","愁人不怨听，自向枕边来。"]},{"t":"促拍满路花 其二","f":"词","c":["人能常清静，天地悉皆归。","一真含众妙，入希夷。","昭文不会，气候有成亏。","妄心寂灭尽，困睡饥餐，更无作用施为。","自然，炉鼎就，光彩透帘帏。","玉池神水涌，上生肥。","如人饮水，冷暖自家知。","自家性命事，自家了得，自家性命便宜。"]},{"t":"促拍满路花 其一","f":"词","c":["抱元能守一，四大自轻安。","心中须返照，几曾闲。","金乌衔耀，飞入烂银盘。","心心心是道，只在心心，更于何处求仙。","又何须衣冕，燕处欲超然。","荣华能几日，便凋残。","修真甚易，积行累功难。","劝君强为善，五浊三途，便为云岛神山。"]},{"t":"促拍满路花 其三","f":"词","c":["若论修养事，知有几多门。","谛当归宿处，是灵根。","至真至道，简易合乾坤。","坎离并水火，止是筌蹄，粹然一点长存。","个中如荐得，悟了五千言。","金晶飞肘后，透昆崙。","清江九曲，一棹破烟昏。","水击三千里，九万鹏程，化成元是冥鲲。"]},{"t":"南乡子 其二 咏双荔支","f":"词","c":["深结花工知。","赐与衣裳尽是绯。","曾向玉盘深处见，隈随。","两个心肠一片儿。","从小便相依。","酒伴歌筵不暂离。","只恐被人分擘破，东西。","怎得团圆似旧时。"]},{"t":"南乡子 其七 催梅","f":"词","c":["把酒祝江梅。","春到南枝早早开。","人在陇头凝望久，徘徊。","驿使如今尚未来。","寄语莫相催。","直待东风细剪裁。","只恐未能传信息，妆台。","先要飞来衬粉腮。"]},{"t":"南乡子 其五","f":"词","c":["栏槛对幽堂，翠叶枝头万朵霜。","檀口乍开龙麝喷，非常。","体胜佳人异骨香。","花与月争光。","偏引蜂儿戏绕墙。","不与群英争艳丽，芬芳。","溪落东君只淡妆。"]},{"t":"南乡子 其四","f":"词","c":["醉捻一枝春。","此意谁人会得君。","嫩白轻红才入手，盈盈。","一似前时酒半醺。","心眼两相亲。","绝代风流恼杀人。","粉蝶霜禽休怅望，叮咛。","只要扬州作主盟。"]},{"t":"南乡子 其六","f":"词","c":["凛冽苦寒时。","万木凋枯力渐衰。","昨夜前村深雪里，春回。","庾岭南枝绽早梅。","映月与清辉。","驿使加鞭喜探回。","风送馨香来小院，芳时。","料想群花尚未知。"]},{"t":"南乡子","f":"词","c":["李郭共仙舟。","准拟苏台烂熳游。","风雪为谁留住也，沧洲。","一尺银沙未肯收。","无语只关愁。","强殢金卮不计筹。","想得人人梳洗懒，妆楼。","只窣帘儿不上钩。"]},{"t":"南乡子 其二","f":"词","c":["把酒对江梅。","个是花中第一枝。","冰雪肌肤潇洒态，须知。","姑射仙人正似伊。","东阁赋新诗。","惭愧当年杜拾遗。","月里何人横玉笛，休吹。","正是芳梢著子时。"]},{"t":"南乡子 其三","f":"词","c":["莫作俗花看。","珠有清香雪太寒。","拟把千钟酬国艳，林间。","醉倒犹嫌酒量悭。","欲去更重攀。","送尽斜阳未忍还。","争得重城休上锁，留连。","借取冰轮照玉颜。"]},{"t":"南乡子 其一","f":"词","c":["梅蕊露鲜妍。","雪态冰姿巧耐寒。","南北枝头香不断，堪观。","露浥琼苞粉未乾。","画手写应难。","横管休吹恐易残。","留得佳人临晓际，凭栏。","试把新妆比并看。"]},{"t":"南乡子","f":"词","c":["帘卷水西楼。","一曲新腔唱打油。","宿雨眠云年少梦，休讴。","且尽生前酒一瓯。","明日又登舟。","却指今宵是旧游。","同是他乡沦落客，休愁。","月子弯弯照几州。"]},{"t":"南柯子/南歌子 寿赵路分","f":"词","c":["花萼清辉近，蓬莱紫气浓。","濮园流庆与天同。","生得名驹千里、籋秋风。","阅武戈初偃，论文酒不空。","摩挲铜狄灞桥东。","看取朱衣双引、袭真封。"]},{"t":"南柯子/南歌子","f":"词","c":["翠袖熏龙脑，乌云映玉台。","春葱一簇荐金杯。","曾记西楼同醉、角声催。","袅袅凌波浅，深深步月来。","隔纱微笑恐郎猜。","素艳浓香依旧、去年开。"]},{"t":"南歌子","f":"词","c":["楼迥迷云日，溪深涨晓沙。","年来悴憔费铅华。","楼上一天春思、浩无涯。","罗带宽腰素，真珠溜脸霞。","海棠开尽柳飞花。","薄倖只知游荡、不思家。"]},{"t":"南歌子","f":"词","c":["席近浑如远，帘高故放低。","偏它能画斗头眉。","戴顶烧香铺翠、小冠儿。","酒伴残妆在，花随秀鬓垂。","薄罗小扇写新诗。","解下双双罗带、要重题。"]},{"t":"南歌子","f":"词","c":["夕露沾芳草，斜阳带远村。","几声残角起谯门。","撩乱栖鸦、飞舞闹黄昏。","天共高城远，香馀绣被温。","客程常是可销魂。","乍向心头、横著个人人。"]},{"t":"南歌子 其五","f":"词","c":["风动槐龙舞，花深禁漏传。","一竿红日照花砖。","走马晨晖门里、快行宣。","百五开新火，清明尚禁烟。","鱼符不请便朝天。","醉里归来疑是、梦游仙。"]},{"t":"南歌子 其三","f":"词","c":["玉殿分时果，金盘弄赐冰。","晚来阶下按歌声。","恰好一方明月、可中庭。","露下天如水，风来夜又清。","偏他不肯大家行。","漾下扇儿拍手、引流萤。"]},{"t":"南歌子","f":"词","c":["象戏红牙局，琵琶绿锦绦。","小窗方簟困香醪。","帘外拂檐宫柳、翠阴交。","烟媚莺莺近，风微燕燕高。","更将乳酪伴樱桃。","要共那人一递、一匙抄。"]},{"t":"南歌子","f":"词","c":["禁苑沈沈静，春波漾漾行。","仙姿才韵两相并。","叶上题诗、千古得佳名。","墙外分明见，花间隐约声。","银钩掷处眼双明。","应讶昔时、不得见情人。"]},{"t":"南歌子 其四","f":"词","c":["阁儿虽不大，都无半点俗。","窗儿根底数竿竹。","画展江南山景、两三幅。","彝鼎烧异香，胆瓶插嫩菊。","悠然无事净心目。","共那人人相对、弈棋局。"]},{"t":"南歌子","f":"五言古诗","c":["菖蒲泛酒香。"]},{"t":"品令","f":"词","c":["雪花飞坠。","有人报、江南意。","博山炉畔，砚屏风里，铜盘寒水。","赋得幽香，疏淡数枝相倚。","绛肤黄蕊。","另一种、高标致。","笛中芳信，岭头春色，不传红紫。","寂寞闲亭，月下夜阑影碎。"]},{"t":"品令 其一","f":"词","c":["山重云起。","断桥外、池塘水。","晓来风定，竹枝相亚，残阳影里。","多少风流，都在冷香疏蕊。","江南千里。","问折得、谁能寄。","几番归去，酒醒月满，阑干十二。","且隐深溪，免笑等闲桃李。"]},{"t":"品令 其七","f":"词","c":["一阳生暖。","见庾岭、梅初绽。","琼枝玉树，浑如傅粉，寿阳妆面。","疏影横斜，隐隐月溪清浅。","前村雪里，向雪里、真难辨。","倩谁说与，高楼人道，休吹羌管。","且与从容，来岁和羹未晚。"]},{"t":"品令","f":"词","c":["急雨惊秋晓。","今岁较、秋风早。","一觞一咏，更须莫负、晚风残照。","可惜莲花已谢，莲房尚小。","汀苹岸草。","怎称得、人情好。","有些言语，也待醉折，荷花向道。","道与荷花，人比去年总老。"]},{"t":"娇木笪/木笪","f":"词","c":["酒入愁肠，谁信道、都做泪珠儿滴。","又怎知道恁他忆。","再相逢、瘦了才信得。"]},{"t":"怨王孙/忆王孙","f":"词","c":["梦断漏悄。","愁浓酒恼。","宝枕生寒，翠屏向晓。","门外谁扫残红。","夜来风。","玉箫声断人何处。","春又去。","忍把归期负。","此情此恨此际，拟托行云。","问东君。"]},{"t":"拜星月/拜星月慢","f":"词","c":["贺新春，尽带春花、春幡春胜，是处春光明媚。"]},{"t":"春光好","f":"词","c":["看看腊尽春回。","消息到、江南早梅。","昨夜前村深雪里，一朵花开。","盈盈玉蕊如裁。","更风细、清香暗来。","空使行人肠欲断，驻马裴回。"]},{"t":"春雪间早梅","f":"词","c":["梅将雪共春。","彩艳灼灼不相因。","逐吹霏霏能争密，排枝碎碎巧妆新。","谁令香来满坐，独使净敛无尘。","芳意饶呈瑞，寒光助照人。","玲珑次第开已遍，点缀坐来频。","那是俱怀疑似，须知造化，两各逼天真。","荧煌清影初乱眼，浩荡逸气忽迷神。","未许琼花并重，将从玉树相亲。","先期迎献岁，更同歌酒占兹辰。","六华蜡蒂相辉映，轻盈敢自珍。"]},{"t":"昼夜乐","f":"词","c":["一阳生后风光好。","百花瘁，群木槁。","南枝探暖欺寒，嘉卉争先占早。","晓来风送清香杳。","映园林、报春来到。","素艳自超群，似姑射容貌。","画堂开宴邀朋友，赏琼英，同欢笑。","陇头寄信丁宁，楼上新妆斗巧。","对景乘兴倾芳酒，拚沈醉、玉山频倒。","结实用和羹，是真奇国宝。"]},{"t":"昼锦堂","f":"词","c":["雨洗桃花，风飘柳絮，日日飞满雕檐。","懊恼一春幽恨，尽属眉尖。","愁闻双飞新燕语，更堪孤枕宿酲忺。","云鬟乱，独步画堂，轻风暗触珠帘。","多厌。","晴昼永，琼户悄，香销金兽慵添。","自与萧娘别后，事事俱嫌。","短歌新曲无心理，凤箫龙管不曾拈。","空惆怅，长是每年三月，病酒恹恹。"]},{"t":"柳初新","f":"词","c":["千林凋谢严凝日。","青帝许、梅花拆。","孤根回暖，前村雪里，昨夜一枝凝白。","天匠与、雕琼镂玉，淡然非、人间标格。","别有神仙第宅。","绣帘垂、碧纱窗隔。","月明风送，清香苒苒，著摸美人词客。","向晓来、芳苞乍摘。","对菱花、倍添姿色。"]},{"t":"柳梢青 贺生第三女。全用三女事","f":"词","c":["家近闽南。","三姑姊妹，秀揖仙岩。","须女精神，玉卮标格，谪下尘凡。","他时佳婿成双，红丝应牵第三。","倚看樽前，团栾六子，三女三男。"]},{"t":"柳梢青","f":"词","c":["有个人人。","海棠标韵，飞燕轻盈。","酒晕潮红，羞娥凝绿，一笑生春。","为伊无限伤心。","更说甚、巫山楚云。","斗帐香消，纱窗月冷，著意温存。"]},{"t":"柳梢青 寿人母五月初六","f":"词","c":["荷绽花繁。","蓂开六荚，喜溢门阑。","好是骖鸾，特离月殿，来驻人间。","儿童歌舞衣斑。","接踵升堂视笑颜。","祝颂勤拳，将何比况，只个南山。"]},{"t":"柳梢青 贺陈姓娶田氏","f":"词","c":["孺子风流，孟尝门地，合下相当。","俏似年时，送他织女，来嫁牛郎。","满堂珠履飞觞。","看花烛、迎归洞房。","海誓山盟，从今结了，永效鸾凰。"]},{"t":"柳梢青","f":"词","c":["晓星明灭。","白露点、秋风落叶。","故址颓垣，荒烟衰草，溪前宫阙。","长安道上行客，念依旧、名深利切。","改变容颜，销磨古今，垄头残月。"]},{"t":"柳梢青 庆太守正月廿五","f":"词","c":["爆竹声收，烧灯节过，恰又经旬。","闻道当年，长庚梦李，嵩岳生申。","江淮草木知名。","有多少、阴功在人。","只恐称觞，棠阴未徙，促觐枫宸。"]},{"t":"柳梢青 其二 寿在人","f":"词","c":["正好江南，一分春色，梨花白雪。","化日迟迟，文章半刺，平分风月。","满堂花醉三千，看妙舞、六么十八。","笑捧瑶卮，祝君归去，琼楼金阙。"]},{"t":"洞仙歌","f":"七言古诗","c":["窗外蛩吟雨声细。"]},{"t":"洞仙歌 其四","f":"词","c":["梳风洗雨，兰蕙摧残后。","玉蕊檀芳做霜晓。","板桥平，溪岸小。","月下归来、乘露冷，赢得清香满抱。","一枝春在手，细嗅重看，风味人间自然少。","拟欲问东君，妙语难寻，搜索尽、池塘春草。","想不是、诗人赏幽姿，纵竹外横斜，是谁知道。"]},{"t":"洞仙歌","f":"词","c":["独拥香衾一半。"]},{"t":"洞仙歌 其二","f":"词","c":["摧残万物，不忍临轩槛。","待得春来是早晚。","向纷纷、雪里开，一枝见。","清香满。","漏泄东君先绽。","暗香浮动、疏影横斜，只这些儿意不浅。","怎禁他，澹澹地、匀粉弹红，争些儿、羞杀桃腮杏脸。","为传语、东风共垂杨，奈辛苦，千丝万丝撩乱。"]},{"t":"洞仙歌 寿丞相夫人十月廿八","f":"词","c":["潭潭仙隐，婺宿光联地。","喜见门阑蔼佳气。","对芳辰，诮一似、王母会瑶池，又却是、夫人诞生明世。","普陀见真相，淑德温柔，更比嫦娥又何异。","小春吉月，日数推来，成七四好景，杯觞须记。","况荣贵，见青紫满门，争戏舞莱衣，祝千秋岁。"]},{"t":"洞仙歌 寿宫教八月初九","f":"词","c":["桂风高处，渐近中秋节。","屈指推来先六日。","对芳辰、符吉梦，知降神、嵩极应诞，主作人间英杰。","文章逾晁董，学擅卿云，高揭声猷缙绅列。","上瀛洲册府，师表宗藩，推第一、即黄扉召入。","佐君王、经邦整顿乾坤，愿寿等广成，更延千百。"]},{"t":"古四北洞仙歌","f":"词","c":["银缸挑尽，纱窗未晓，独拥寒衾一半。"]},{"t":"洞仙歌","f":"七言古诗","c":["今夜谁添一种愁。"]},{"t":"洞仙歌","f":"词","c":["溶溶泄泄，似飘扬愁绪。","不是因风等闲度。","道无心用甚，却又情多，行未驻，还作高阳暮雨。","襄王情尚浅，会少离多，空自朝朝又暮暮。","肠断晓光中，一缕归时，销散后、不知何处。","试密锁、琼楼洞房深，与遮断江皋，楚台归路。"]},{"t":"洞仙歌 其三","f":"词","c":["断云疏雨，冷落空山道。","匹马骎骎又重到。","望孤村，两三间、茅屋疏篱，溪水畔、一簇芦花晚照。","寻思行乐地，事去无痕，回首湘波与天杳。","叹人生几度，能醉金钗，青镜里、赢得朱颜未老。","又枝头、一点破黄昏，问客路春风，为谁开早。"]},{"t":"洞仙歌","f":"词","c":["惟有莺莺燕燕。"]},{"t":"洞仙歌 其一","f":"词","c":["蓬莱宫殿。","去人间三万。","玉体仙娥有谁见。","被月朋雪友，邀下琼楼，溪桥畔。","相对寒光浅浅。","一般天上格，独带真香，冰麝犹嫌未清远。","似太真望幸，一饷销凝，愁未惯。","消瘦难禁素练。","又只恐、东风破寒来，伴神女同归，阆峰仙苑。"]},{"t":"洞仙歌","f":"词","c":["六尺湘漪簟冷。"]},{"t":"洞庭春色/沁园春","f":"词","c":["绛萼欺寒，暗传春信，一枝乍芳。","向篱边竹外，前村雪里，青梢犹瘦，疏影溪傍。","惹露和烟凝酥艳，似潇洒玉人初试妆。","江南路，有多情伫立，回尽柔肠。","倚楼最难忘处，正皓月、千里流光。","纵广平心劲，难思丽句，少陵诗兴，犹爱清香。","休怪东君先留意，问他日和羹谁又强。","还轻许，笑凌空桧影，松荫交相。"]},{"t":"点绛唇 其八","f":"词","c":["赋雪归来，绿窗一夜霜风紧。","也知春信。","消息南枝近。","隐映斜阳，玉暖香成阵。","西湖景。","繁英有恨。","只□□□□。"]},{"t":"点绛唇 其六","f":"词","c":["昨夜寒梅，一枝雪里多风措。","幽香无数。","不与群花语。","最是凝情，月夜交光处。","谁为主。","待须折取。","羌管休轻举。"]}]};